(1015880000001, 1015880000000, E'<html xmlns="http://www.w3.org/1999/xhtml"><head runat="server">\r\n    <title>Process Flow</title>\r\n    <meta name="viewport" content="width=device-width, initial-scale=1a">\r\n    <link rel="stylesheet" href="../../UI/axpertUI/style.bundle.css">\r\n    <link rel="stylesheet" href="../../UI/axpertUI/plugins.bundle.css">\r\n    <link rel="stylesheet" href="../../ThirdParty/jquery-confirm-master/jquery-confirm.min.css">\r\n    <link rel="stylesheet" href="css/AxpertInbox.css?v=11" type="text/css">\r\n\r\n    <style>\r\n        .v2-child-item {\r\n            border-top: 1px solid #e5e5e5;\r\n            margin-left: 20px;\r\n        }\r\n\r\n        .v2-child-header {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            padding: 10px 12px;\r\n            cursor: pointer;\r\n            background: #fafafa;\r\n        }\r\n\r\n        .v2-child-body {\r\n            display: none;\r\n        }\r\n\r\n        .v2-child-body.show {\r\n            display: block;\r\n        }\r\n\r\n        .people-row {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: space-between;\r\n            padding: 12px 16px;\r\n            cursor: pointer;\r\n            border-bottom: 1px solid #eee;\r\n            align-items: center;\r\n\r\n            cursor: pointer;\r\n            background-color: #fff;\r\n            margin: 00;\r\n            overflow: hidden;\r\n        }\r\n\r\n        .people-row:hover {\r\n            background: #f7f9fc;\r\n        }\r\n\r\n        .people-scheduler {\r\n            visibility: hidden;\r\n            color: #4e86c7;\r\n            cursor: pointer;\r\n        }\r\n\r\n        .people-row:hover .people-scheduler {\r\n            visibility: visible;\r\n        }\r\n    </style>\r\n    <!-- <style>\r\n        #Process-stepper {\r\n\r\n            flex: none !important;\r\n            margin-left: 32.3333% !important;\r\n            width: 67.6667% !important;\r\n            max-width: 115% !important;\r\n            background: #fff;\r\n            position: relative;\r\n            z-index: 10;\r\n            top: 3px;\r\n\r\n            /* scrollbar */\r\n            overflow-x: auto !important;\r\n            overflow-y: hidden !important;\r\n            white-space: nowrap;\r\n            height: 40px;\r\n        }\r\n\r\n        #horizontal-processbar {\r\n            display: inline-flex !important;\r\n            width: max-content !important;\r\n            min-width: max-content !important;\r\n            flex-wrap: nowrap !important;\r\n        }\r\n\r\n        body#Task_activity {\r\n            overflow: hidden;\r\n        }\r\n\r\n        div#ktMenu {\r\n            /* transform: translate(327px, 35px)!important; */\r\n            cursor: pointer;\r\n            padding: 8px;\r\n            font-size: small;\r\n            font-weight: 500;\r\n            position: absolute;\r\n            inset: unset !important;\r\n            transform: none !important;\r\n        }\r\n\r\n        .text-hover-primary:hover {\r\n            background: #d3d3d35c;\r\n            transition: color .2s ease, background-color .2s ease;\r\n            /* color: #0774fe!important; */\r\n            /* width: -webkit-fill-available; */\r\n            color: black !important;\r\n        }\r\n\r\n\r\n        .user-main {\r\n            background: #4e86c7;\r\n            color: #fff;\r\n            padding: 5px 16px;\r\n            border-radius: 6px;\r\n            font-weight: 500;\r\n            cursor: pointer;\r\n            display: block;\r\n            align-items: center;\r\n            user-select: none;\r\n            position: relative !important;\r\n            z-index: 100000 !important;\r\n            pointer-events: auto;\r\n            font-size: 15spx;\r\n            font-size: 15px;\r\n            min-width: 110px;\r\n            max-width: 160px;\r\n            left: -10px;\r\n        }\r\n\r\n        .arrow {\r\n            position: absolute;\r\n            right: 0px;\r\n            top: 50%;\r\n            transform: translateY(-50%);\r\n            font-size: 12px;\r\n            pointer-events: none;\r\n\r\n        }\r\n\r\n        .group-btn .material-icons {\r\n            font-size: 18px;\r\n        }\r\n\r\n\r\n\r\n        .user-item {\r\n            padding: 10px 14px;\r\n            cursor: pointer;\r\n            font-size: 14px;\r\n        }\r\n\r\n\r\n\r\n\r\n        /* ===============================\r\n   INBOX USER SWITCHER — FINAL FIX\r\n================================ */\r\n\r\n        #topPanel {\r\n            position: relative !important;\r\n            overflow: visible !important;\r\n\r\n        }\r\n\r\n        .inbox-user-switcher {\r\n            position: relative !important;\r\n            display: inline-block;\r\n            z-index: 9999;\r\n\r\n        }\r\n\r\n\r\n        /* Dropdown menu */\r\n        .user-dropdown {\r\n            position: absolute !important;\r\n            top: calc(100% + 6px);\r\n            left: 0;\r\n            min-width: 200px;\r\n            background: #fff;\r\n            border-radius: 8px;\r\n            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);\r\n            display: none;\r\n            z-index: 100001 !important;\r\n            transform: none !important;\r\n            inset: unset !important;\r\n            top: 46px !important;\r\n            left: -11px !important;\r\n        }\r\n\r\n        /* When opened */\r\n        .user-dropdown.open {\r\n            display: block !important;\r\n        }\r\n\r\n        /* Prevent Axpert overlays from covering it */\r\n        .Page-Title,\r\n        .Title-Section,\r\n        .Tkts-toolbar-Right,\r\n        .Tkts-toolbar-Left {\r\n            overflow: visible !important;\r\n        }\r\n\r\n\r\n\r\n        .user-item:hover {\r\n            background: #f3f6fb;\r\n        }\r\n\r\n        /* .pagename{\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    width: max-content;\r\n    gap: 4px;\r\n} */\r\n        .icon-filters {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n        }\r\n\r\n        .icon-filter {\r\n            display: flex;\r\n            align-items: center;\r\n            /* gap: 6px; */\r\n            padding: 6px 10px;\r\n            border-radius: 8px;\r\n            cursor: pointer;\r\n            background: #f3f6fb;\r\n            color: #444;\r\n            font-size: 12px;\r\n            transition: all .2s ease;\r\n            margin: 10px 0px;\r\n        }\r\n\r\n        .icon-filter .material-icons {\r\n            font-size: 18px;\r\n        }\r\n\r\n        .icon-filter:hover {\r\n            background: #e1e7f5;\r\n        }\r\n\r\n        .icon-filter.active {\r\n            background: #4e86c7;\r\n            color: white;\r\n        }\r\n\r\n        .icon-filter .count {\r\n            font-size: 11px;\r\n            opacity: 0.85;\r\n        }\r\n\r\n        .icon-all {\r\n            color: #3b82f6;\r\n        }\r\n\r\n        /* Blue */\r\n        .icon-active {\r\n            color: #f59e0b;\r\n        }\r\n\r\n        /* Amber */\r\n        .icon-completed {\r\n            color: #22c55e;\r\n        }\r\n\r\n        /* Green */\r\n        .icon-sent {\r\n            color: #6366f1;\r\n        }\r\n\r\n        /* Indigo */\r\n        .icon-pending {\r\n            color: #f97316;\r\n        }\r\n\r\n        /* Orange */\r\n        .icon-approved {\r\n            color: #10b981;\r\n        }\r\n\r\n        /* Teal */\r\n        .icon-rejected {\r\n            color: #ef4444;\r\n        }\r\n\r\n        /* Red */\r\n        .icon-returned {\r\n            color: #8b5cf6;\r\n        }\r\n\r\n        /* Violet */\r\n        .icon-filter.active .material-icons {\r\n            color: inherit;\r\n        }\r\n\r\n        .icon-message {\r\n            color: #0ea5e9;\r\n        }\r\n\r\n        /* Sky Blue */\r\n        .icon-notification {\r\n            color: #facc15;\r\n        }\r\n\r\n        /* Yellow */\r\n        .inbox-user-select {\r\n            padding: 6px 14px;\r\n            border-radius: 6px;\r\n            border: 1px solid #d0d5dd;\r\n            background: #2563eb;\r\n            color: #fff;\r\n            font-weight: 600;\r\n            cursor: pointer;\r\n        }\r\n\r\n        .inbox-user-select {\r\n            background: #4e86c7;\r\n            color: #fff;\r\n            padding: 6px 36px 6px 16px;\r\n            border-radius: 6px;\r\n            font-weight: 500;\r\n            cursor: pointer;\r\n            font-size: 15px;\r\n            border: none;\r\n            outline: none;\r\n            appearance: none;\r\n            min-width: 140px;\r\n            max-width: 200px;\r\n            background-image: url("data:image/svg+xml;utf8,<svg fill=''white'' height=''16'' viewBox=''0 0 24 24'' width=''16'' xmlns=''http://www.w3.org/2000/svg''><path d=''M7 10l5 5 5-5z''/></svg>");\r\n            background-repeat: no-repeat;\r\n            background-position: right 10px center;\r\n        }\r\n\r\n        .inbox-user-select option {\r\n            color: #000;\r\n        }\r\n\r\n        /* Make ONLY the dropdown options white */\r\n        .inbox-user-select option {\r\n            background: #ffffff !important;\r\n            color: #000000 !important;\r\n        }\r\n\r\n        /* Highlight on hover / selected option */\r\n        .inbox-user-select option:checked,\r\n        .inbox-user-select option:hover {\r\n            background: #f3f6fb !important;\r\n            color: #000000 !important;\r\n        }\r\n\r\n        .filter-group {\r\n            position: relative;\r\n        }\r\n\r\n        .group-btn {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 6px;\r\n            background: #f3f6fb;\r\n            border-radius: 8px;\r\n            padding: 6px 12px;\r\n            border: none;\r\n            cursor: pointer;\r\n            font-size: 13px;\r\n            width: 100px;\r\n        }\r\n\r\n        .group-btn:hover {\r\n            background: #e1e7f5;\r\n        }\r\n\r\n        .group-btn .arrow {\r\n            font-size: 16px;\r\n            transition: .2s;\r\n        }\r\n\r\n        .filter-group.open .arrow {\r\n            transform: rotate(180deg);\r\n        }\r\n\r\n        .group-menu {\r\n            position: absolute;\r\n            top: 115%;\r\n            left: 0;\r\n            background: #fff;\r\n            border-radius: 10px;\r\n            box-shadow: 0 10px 25px rgba(0, 0, 0, .15);\r\n            padding: 6px;\r\n            display: none;\r\n            z-index: 1000;\r\n            min-width: 210px;\r\n        }\r\n\r\n        .filter-group.open .group-menu {\r\n            display: block;\r\n        }\r\n\r\n        .group-menu .icon-filter {\r\n            width: 100%;\r\n            justify-content: flex-start;\r\n            border-radius: 6px;\r\n        }\r\n\r\n        .group-menu .icon-filter:hover {\r\n            background: #f3f6fb;\r\n        }\r\n\r\n        /* \r\n        new */\r\n\r\n        .inbox-sub-toolbar {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 40px;\r\n            /* padding: 8px 12px; */\r\n            /* border-bottom: 1px solid #e5e7eb; */\r\n            /* background: #fff; */\r\n        }\r\n\r\n        .all-toggle {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 6px;\r\n            font-size: 13px;\r\n        }\r\n\r\n        .filter-btn {\r\n            border: none;\r\n            background: transparent;\r\n            cursor: pointer;\r\n        }\r\n\r\n        .active-filters {\r\n            display: flex;\r\n            gap: 8px;\r\n            flex-wrap: wrap;\r\n        }\r\n\r\n        .filter-chip {\r\n            background: #eef2f7;\r\n            border-radius: 14px;\r\n            padding: 4px 10px;\r\n            font-size: 12px;\r\n        }\r\n\r\n        .filter-chip span {\r\n            cursor: pointer;\r\n            margin-left: 6px;\r\n        }\r\n\r\n\r\n\r\n        .hidden {\r\n            display: none !important;\r\n        }\r\n\r\n        .inbox-sub-toolbar {\r\n            position: relative;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 12px;\r\n        }\r\n\r\n        .filter-wrapper {\r\n            position: relative;\r\n            /* 🔑 anchor for popup */\r\n        }\r\n\r\n        .filter-panel {\r\n            display: none;\r\n            position: absolute;\r\n            top: calc(100% - 12px);\r\n            left: 220px;\r\n            width: 330px;\r\n            background: #fff;\r\n            border: 1px solid #ddd;\r\n            border-radius: 6px;\r\n            padding: 10px 12px;\r\n            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);\r\n            z-index: 1000;\r\n        }\r\n\r\n\r\n\r\n\r\n        .filter-panel label {\r\n            display: inline-block;\r\n            width: 48%;\r\n            margin-bottom: 8px;\r\n            font-size: 14px;\r\n        }\r\n\r\n        .filter-panel.show {\r\n            display: block;\r\n            position: absolute;\r\n            z-index: 2000;\r\n        }\r\n\r\n\r\n        .filter-option {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            padding: 6px 0;\r\n            cursor: pointer;\r\n        }\r\n\r\n        .filter-btn {\r\n            background: none;\r\n            border: none;\r\n            cursor: pointer;\r\n        }\r\n\r\n\r\n\r\n        .filter-message-bar {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: space-between;\r\n            /* pushes X to last */\r\n            background: #eaeef2;\r\n            padding: 5px 16px;\r\n            border-radius: 4px;\r\n            margin: 0;\r\n            font-size: 14px;\r\n        }\r\n\r\n        #filterMessageText {\r\n            flex: 1;\r\n        }\r\n\r\n\r\n        .close-btn {\r\n            background: transparent;\r\n            border: 1px solid #94a3b8;\r\n            color: #1f2937;\r\n            width: 28px;\r\n            height: 28px;\r\n            border-radius: 4px;\r\n            cursor: pointer;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n        }\r\n\r\n        .all-toggle.active {\r\n            color: #2563eb;\r\n            font-weight: 600;\r\n        }\r\n\r\n        .search-box {\r\n            position: relative;\r\n            display: flex;\r\n            align-items: center;\r\n        }\r\n\r\n        .search-input {\r\n            flex: 1;\r\n            padding-right: 149px;\r\n            /* width: 178%; */\r\n            padding-left: 5px;\r\n        }\r\n\r\n        .filter-icon {\r\n            position: absolute;\r\n            right: 10px;\r\n            cursor: pointer;\r\n            color: #888;\r\n        }\r\n\r\n        .filter-icon.active {\r\n            color: #0d6efd;\r\n            /* blue highlight */\r\n        }\r\n\r\n        .menu.menu-sub.menu-sub-dropdown.menu-rounded.menu-gray-600.menu-state-bg-light.fw-bolder.w-300px.py-3.initialized.show {\r\n            position: absolute;\r\n            right: 0px;\r\n        }\r\n\r\n        #plistContent {\r\n            height: 90vh;\r\n            overflow-y: auto;\r\n        }\r\n\r\n        #filterMessageBar {\r\n            position: absolute;\r\n            top: 82px;\r\n            left: 0;\r\n            right: 0;\r\n            z-index: 1000;\r\n            /* background: #eef4ff; */\r\n            padding: 0px 16px;\r\n            border-bottom: 1px solid #ddd;\r\n            transform: translateY(-100%);\r\n            transition: transform 0.3s ease;\r\n        }\r\n\r\n        #filterMessageBar.show {\r\n            transform: translateY(0);\r\n        }\r\n\r\n        #filterMessageBar.hidden {\r\n            transform: translateY(-100%);\r\n        }\r\n\r\n        .nametime {\r\n            display: block;\r\n            width: 80px;\r\n            white-space: nowrap;\r\n            overflow: hidden;\r\n            text-overflow: ellipsis;\r\n        }\r\n\r\n        .content:has(#New-Landing-layout) {\r\n            background: #f1f4f9 !important;\r\n            height: 50vh !important;\r\n            max-height: calc(100vh - 90px) !important;\r\n        }\r\n\r\n        /* ul#horizontal-processbar { */\r\n        /* margin-top: 45px !important; */\r\n        /* padding: 0px !important; */\r\n        /* } */\r\n        /* #Process-stepper {\r\n    display: block !important;\r\n    flex: none !important;\r\n    margin-left: 32.3333% !important;\r\n    width: 44.6667% !important;\r\n    /* max-width: 82.6667% !important; \r\n    background: #fff;\r\n    max-width: 68% !important;\r\n    position: relative;\r\n    z-index: 10;\r\n    top: 3px;\r\n    overflow-x: auto;\r\n    overflow-y: hidden;\r\n} */\r\n        /* \r\n#horizontal-processbar {\r\n    width: max-content;\r\n    min-width: 100%;\r\n} */\r\n        .deep-search-highlight {\r\n            animation: highlightFlash 1s ease-in-out 3;\r\n            background: #fff3cd;\r\n            border: 1px solid #ffc107;\r\n        }\r\n\r\n        @keyframes highlightFlash {\r\n            0% {\r\n                background: #fff3cd;\r\n            }\r\n\r\n            50% {\r\n                background: #ffe69c;\r\n            }\r\n\r\n            100% {\r\n                background: #fff3cd;\r\n            }\r\n        }\r\n\r\n        .custom-header {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n        }\r\n\r\n        /* button style */\r\n        .hdr-btn {\r\n            padding: 6px 14px;\r\n            background: #4e86c7;\r\n            border-radius: 5px;\r\n            cursor: pointer;\r\n            font-size: 13px;\r\n            font-weight: 500;\r\n            white-space: nowrap;\r\n            color: white;\r\n        }\r\n\r\n        .hdr-btn.active {\r\n            background: #4e86c7;\r\n            color: black;\r\n        }\r\n\r\n        /* fix select alignment */\r\n        .inbox-user-switcher {\r\n            display: flex;\r\n            align-items: center;\r\n        }\r\n\r\n        /* dropdown */\r\n        .hdr-dropdown {\r\n            position: relative;\r\n            width: 180px;\r\n        }\r\n\r\n        .dropdown-menu {\r\n            position: absolute;\r\n            top: 110%;\r\n            left: 0;\r\n            background: #fff;\r\n            border-radius: 8px;\r\n            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.15);\r\n            display: none;\r\n            min-width: 180px;\r\n            z-index: 9999;\r\n        }\r\n\r\n        .dropdown-item {\r\n            padding: 8px 12px;\r\n            cursor: pointer;\r\n        }\r\n\r\n        .dropdown-item:hover {\r\n            background: #f3f6fb;\r\n        }\r\n\r\n        /* show dropdown */\r\n        .hdr-dropdown.open .dropdown-menu {\r\n            display: block;\r\n        }\r\n\r\n        .dots-menu {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            width: 36px;\r\n            height: 36px;\r\n            padding: 0;\r\n            border-radius: 50%;\r\n        }\r\n\r\n        .dots-menu .material-icons {\r\n            font-size: 20px;\r\n        }\r\n\r\n        .dropdown-submenu {\r\n            position: relative;\r\n        }\r\n\r\n        .dropdown-submenu .submenu {\r\n            display: none;\r\n            position: absolute;\r\n            left: 100%;\r\n            top: 0;\r\n            min-width: 180px;\r\n            background: #fff;\r\n            border-radius: 6px;\r\n            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.15);\r\n        }\r\n\r\n        .dropdown-submenu:hover .submenu {\r\n            display: block;\r\n        }\r\n\r\n        .submenu-toggle {\r\n            display: flex;\r\n            justify-content: space-between;\r\n        }\r\n\r\n        .accordion-header {\r\n            padding: 8px 12px;\r\n            background: #f3f6fb;\r\n            cursor: pointer;\r\n            border-bottom: 1px solid #ddd;\r\n            font-weight: 500;\r\n            display: flex;\r\n            justify-content: space-between;\r\n        }\r\n\r\n        .accordion-body {\r\n            padding: 8px 12px;\r\n            background: #fff;\r\n        }\r\n\r\n        .task-item {\r\n            padding: 4px 0;\r\n            font-size: 13px;\r\n            border-bottom: 1px dashed #eee;\r\n        }\r\n\r\n        .search-highlight {\r\n            border: 2px solid #90ee90;\r\n            /* light green */\r\n            border-radius: 6px;\r\n            background: #f0fff0;\r\n        }\r\n\r\n        /* Target the actual header element */\r\n        .user-main {\r\n            position: sticky !important;\r\n            top: 0;\r\n            z-index: 1050;\r\n            /* Stays above task cards */\r\n            background: white;\r\n        }\r\n\r\n        .submenu-toggle {\r\n            pointer-events: none;\r\n            /* ❌ disable click */\r\n            cursor: default;\r\n            /* normal cursor */\r\n            font-weight: 600;\r\n            /* looks like header */\r\n        }\r\n\r\n        .stepper-horizontal li:not(:first-child)::before {\r\n            position: relative;\r\n            -webkit-box-flex: 1;\r\n            flex: 1 1 0%;\r\n            height: 1px;\r\n            margin: 0.5rem 0px 0px;\r\n            content: "";\r\n            background-color: rgba(0, 0, 0, 0.1);\r\n            min-width: 40px;\r\n        }\r\n\r\n\r\n        /* v2css */\r\n        .v2-accordion-item {\r\n            border-bottom: 1px solid #e5e7eb;\r\n        }\r\n\r\n        .v2-accordion-header {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            padding: 14px 16px;\r\n            cursor: pointer;\r\n            background: #fff;\r\n        }\r\n\r\n        .v2-accordion-header.active {\r\n            background: #eff6ff;\r\n        }\r\n\r\n        .v2-left {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n        }\r\n\r\n        .v2-arrow {\r\n            font-family: ''Material Icons'';\r\n            font-size: 18px;\r\n        }\r\n\r\n        .v2-title {\r\n            font-size: 14px;\r\n            font-weight: 600;\r\n        }\r\n\r\n        .v2-accordion-body {\r\n            display: none;\r\n            background: #fff;\r\n        }\r\n\r\n        .empty-state {\r\n            display: flex;\r\n            justify-content: center;\r\n            align-items: center;\r\n            min-height: 40px;\r\n            color: #888;\r\n        }\r\n\r\n        .v2-accordion-body.show {\r\n            display: block;\r\n        }\r\n\r\n        .v2-pagination {\r\n            display: flex;\r\n            justify-content: center;\r\n            align-items: center;\r\n            gap: 12px;\r\n            padding: 12px;\r\n        }\r\n\r\n        .page-btn {\r\n            border: none;\r\n            background: #2563eb;\r\n            color: #fff;\r\n            padding: 4px 10px;\r\n            border-radius: 4px;\r\n            cursor: pointer;\r\n        }\r\n\r\n        .v2-accordion-item {\r\n            border-bottom: 1px solid #e5e7eb;\r\n        }\r\n\r\n        .v2-accordion-header {\r\n            position: sticky;\r\n            top: 0;\r\n            z-index: 10;\r\n\r\n            background: #fff;\r\n\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n\r\n            padding: 14px 16px;\r\n\r\n            cursor: pointer;\r\n\r\n            border-bottom: 1px solid #e5e7eb;\r\n        }\r\n\r\n        .v2-accordion-header.active {\r\n            background: #eff6ff;\r\n        }\r\n\r\n        .v2-accordion-body {\r\n            display: none;\r\n        }\r\n\r\n        .v2-accordion-body.show {\r\n            display: block;\r\n        }\r\n\r\n        .v2-scroll-body {\r\n\r\n            max-height: 319px;\r\n\r\n            overflow-y: auto;\r\n\r\n            background: #fff;\r\n        }\r\n\r\n        .v2-scroll-body[data-section="people"],\r\n        .v2-scroll-body[data-section="groups"] {\r\n            max-height: 240px;\r\n        }\r\n\r\n        #body_Container {\r\n            display: flex;\r\n            flex-direction: column;\r\n            min-height: 0;\r\n        }\r\n\r\n        #ProcessFlow_New-container,\r\n        #ProcessFlow_Content,\r\n        #tickets,\r\n        #InboxAccordion {\r\n            display: flex;\r\n            flex-direction: column;\r\n            flex: 1;\r\n            min-height: 0;\r\n        }\r\n\r\n        #InboxAccordion {\r\n            flex: 1;\r\n            overflow-y: auto;\r\n        }\r\n\r\n        #Tickets_details_view {\r\n            display: flex;\r\n            flex-direction: column;\r\n            overflow: hidden;\r\n            max-height: 90vh;\r\n            position: relative;\r\n        }\r\n\r\n        .directory-chat-panel {\r\n            position: absolute;\r\n            inset: 0;\r\n            z-index: 20;\r\n            display: flex;\r\n            flex-direction: column;\r\n            background: #f8fbff;\r\n        }\r\n\r\n        .directory-chat-panel.d-none {\r\n            display: none !important;\r\n        }\r\n\r\n        #process_centerpanel {\r\n            width: 100%;\r\n            height: 100%;\r\n            margin-bottom: 0;\r\n            border: 0;\r\n            background: transparent;\r\n            overflow: hidden;\r\n            display: flex;\r\n            flex-direction: column;\r\n            min-height: 0;\r\n        }\r\n\r\n        .chat-shell {\r\n            height: 100%;\r\n            min-height: 0;\r\n            display: flex;\r\n            flex-direction: column;\r\n            background: #f8fbff;\r\n        }\r\n\r\n        .chat-shell-header {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: space-between;\r\n            gap: 16px;\r\n            padding: 16px 18px;\r\n            background: #fff;\r\n            border-bottom: 1px solid #dbe4f0;\r\n        }\r\n\r\n        .chat-profile {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 12px;\r\n            min-width: 0;\r\n        }\r\n\r\n        .chat-avatar {\r\n            width: 48px;\r\n            height: 48px;\r\n            border-radius: 14px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            color: #fff;\r\n            font-weight: 700;\r\n            font-size: 15px;\r\n            background: #2563eb;\r\n            flex: none;\r\n            box-shadow: 0 10px 18px rgba(37, 99, 235, 0.14);\r\n        }\r\n\r\n        .chat-avatar.chat-avatar-group {\r\n            background: #0f766e;\r\n            box-shadow: 0 10px 18px rgba(15, 118, 110, 0.12);\r\n        }\r\n\r\n        .chat-name {\r\n            font-size: 18px;\r\n            font-weight: 700;\r\n            line-height: 1.2;\r\n            color: #1f2937;\r\n            white-space: nowrap;\r\n            overflow: hidden;\r\n            text-overflow: ellipsis;\r\n        }\r\n\r\n        .chat-subline {\r\n            margin-top: 4px;\r\n            display: flex;\r\n            gap: 8px;\r\n            flex-wrap: wrap;\r\n            font-size: 12px;\r\n            color: #64748b;\r\n        }\r\n\r\n        .chat-chip {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            padding: 4px 9px;\r\n            border-radius: 999px;\r\n            background: #eef4ff;\r\n            color: #2563eb;\r\n            font-size: 11px;\r\n            font-weight: 600;\r\n            white-space: nowrap;\r\n        }\r\n\r\n        .chat-actions {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            flex: none;\r\n        }\r\n\r\n        .chat-icon-btn {\r\n            width: 36px;\r\n            height: 36px;\r\n            border: none;\r\n            border-radius: 10px;\r\n            background: #f3f7fb;\r\n            color: #475569;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            cursor: default;\r\n        }\r\n\r\n        .chat-feed {\r\n            flex: 1;\r\n            min-height: 0;\r\n            overflow-y: auto;\r\n            padding: 18px;\r\n            display: flex;\r\n            flex-direction: column;\r\n            gap: 12px;\r\n        }\r\n\r\n        .chat-empty {\r\n            flex: 1;\r\n            min-height: 220px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            text-align: center;\r\n            color: #64748b;\r\n        }\r\n\r\n        .chat-empty-card {\r\n            background: #fff;\r\n            border: 1px solid #dbe4f0;\r\n            border-radius: 18px;\r\n            padding: 22px 24px;\r\n            box-shadow: 0 14px 30px rgba(15, 23, 42, 0.06);\r\n            max-width: 360px;\r\n        }\r\n\r\n        .chat-empty-title {\r\n            margin-top: 12px;\r\n            font-size: 16px;\r\n            font-weight: 700;\r\n            color: #1f2937;\r\n        }\r\n\r\n        .chat-empty-meta {\r\n            margin-top: 8px;\r\n            font-size: 13px;\r\n            line-height: 1.5;\r\n            color: #64748b;\r\n        }\r\n\r\n        .chat-message {\r\n            display: flex;\r\n            align-items: flex-end;\r\n            gap: 8px;\r\n            max-width: 50%;\r\n        }\r\n\r\n        .chat-message.self {\r\n            margin-left: auto;\r\n            flex-direction: row-reverse;\r\n        }\r\n\r\n        .chat-avatar-sm {\r\n            width: 32px;\r\n            height: 32px;\r\n            border-radius: 10px;\r\n            background: #dbeafe;\r\n            color: #1d4ed8;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-size: 11px;\r\n            font-weight: 700;\r\n            flex: none;\r\n        }\r\n\r\n        .chat-bubble {\r\n            padding: 6px 12px;\r\n            border-radius: 18px;\r\n            background: #f0f0f0;\r\n            border: none;\r\n            box-shadow: none;\r\n            color: #1f2937;\r\n            line-height: 0.8;\r\n            white-space: unset;\r\n            font-size: 14px;\r\n            padding: 17px;\r\n        }\r\n\r\n        .chat-message.self .chat-bubble {\r\n            background: #0078d4;\r\n            border-color: #0078d4;\r\n            color: #fff;\r\n            border-radius: 18px;\r\n        }\r\n\r\n        .chat-message-meta {\r\n            margin-top: 2px;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            gap: 4px;\r\n            font-size: 10px;\r\n            color: #64748b;\r\n        }\r\n\r\n        .chat-message.self .chat-message-meta {\r\n            color: rgba(255, 255, 255, 0.85);\r\n        }\r\n\r\n        .chat-composer {\r\n            padding: 14px 16px;\r\n            background: #fff;\r\n            border-top: 1px solid #dbe4f0;\r\n            display: flex;\r\n            gap: 10px;\r\n            align-items: flex-end;\r\n        }\r\n\r\n        .chat-input-wrap {\r\n            flex: 1;\r\n            position: relative;\r\n        }\r\n\r\n        .chat-input {\r\n            width: 100%;\r\n            min-height: 46px;\r\n            max-height: 120px;\r\n            resize: none;\r\n            border: 1px solid #dbe4f0;\r\n            border-radius: 14px;\r\n            padding: 12px 14px;\r\n            outline: none;\r\n            font-size: 14px;\r\n            line-height: 1.4;\r\n            background: #f8fbff;\r\n            color: #1f2937;\r\n        }\r\n\r\n        .chat-input:focus {\r\n            border-color: #93c5fd;\r\n            box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.12);\r\n            background: #fff;\r\n        }\r\n\r\n        .chat-send {\r\n            width: 44px;\r\n            height: 44px;\r\n            border: none;\r\n            border-radius: 14px;\r\n            background: #2563eb;\r\n            color: #fff;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            box-shadow: 0 10px 18px rgba(37, 99, 235, 0.18);\r\n        }\r\n\r\n        .chat-send:disabled {\r\n            background: #94a3b8;\r\n            box-shadow: none;\r\n        }\r\n\r\n        .directory-row {\r\n            display: flex;\r\n            align-items: flex-start;\r\n            gap: 12px;\r\n            padding: 16px 18px;\r\n            cursor: pointer;\r\n            border-bottom: 1px solid #eef2f7;\r\n            background: #fff;\r\n            transition: background 0.15s ease, border-color 0.15s ease;\r\n        }\r\n\r\n        .directory-row:hover {\r\n            background: #f8fbff;\r\n        }\r\n\r\n        .directory-row.selected {\r\n            background: #eaf2ff;\r\n            border-left: 3px solid #2563eb;\r\n            padding-left: 15px;\r\n        }\r\n\r\n        .directory-row.group-member-row {\r\n            padding-left: 44px;\r\n            background: #fbfdff;\r\n        }\r\n\r\n        .directory-row.group-member-row.selected {\r\n            padding-left: 41px;\r\n        }\r\n\r\n        .group-loading,\r\n        .group-empty {\r\n            padding: 12px 18px 12px 72px;\r\n            font-size: 13px;\r\n            color: #64748b;\r\n            background: #fbfdff;\r\n            border-bottom: 1px solid #eef2f7;\r\n        }\r\n\r\n        .directory-avatar {\r\n            width: 44px;\r\n            height: 44px;\r\n            border-radius: 14px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            background: #dbeafe;\r\n            color: #1d4ed8;\r\n            font-weight: 700;\r\n            flex: none;\r\n            box-shadow: 0 8px 14px rgba(59, 130, 246, 0.08);\r\n        }\r\n\r\n        .directory-avatar.directory-avatar-group {\r\n            background: #dcfce7;\r\n            color: #166534;\r\n            box-shadow: 0 8px 14px rgba(22, 101, 52, 0.08);\r\n        }\r\n\r\n        .directory-main {\r\n            flex: 1;\r\n            min-width: 0;\r\n        }\r\n\r\n        .directory-name {\r\n            font-size: 15px;\r\n            font-weight: 700;\r\n            color: #0f172a;\r\n            white-space: nowrap;\r\n            overflow: hidden;\r\n            text-overflow: ellipsis;\r\n        }\r\n\r\n        .directory-meta {\r\n            margin-top: 5px;\r\n            font-size: 12px;\r\n            color: #64748b;\r\n            line-height: 1.45;\r\n            display: flex;\r\n            flex-wrap: wrap;\r\n            gap: 6px;\r\n        }\r\n\r\n        .directory-badges {\r\n            margin-top: 8px;\r\n            display: flex;\r\n            flex-wrap: wrap;\r\n            gap: 6px;\r\n        }\r\n\r\n        .directory-badge {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            padding: 3px 8px;\r\n            border-radius: 999px;\r\n            background: #eef2ff;\r\n            color: #4f46e5;\r\n            font-size: 11px;\r\n            font-weight: 600;\r\n            white-space: nowrap;\r\n        }\r\n\r\n        .directory-cta {\r\n            color: #94a3b8;\r\n            font-size: 18px;\r\n            margin-top: 8px;\r\n            flex: none;\r\n        }\r\n    </style> -->\r\n\t<link type="text/css" rel="stylesheet" href="Css/AxpertInbox_1784889372733.css?v=1784889451538">\r\n</head>\r\n\r\n\r\n<body id="Process_Flow" class="header-fixed header-tablet-and-mobile-fixed aside-fixed overflow-hidden vh-100 min-vh-100">\r\n\r\n    <!--begin::Content-->\r\n    <div class="content-- d-flex flex-column flex-column-fluid">\r\n        <!--begin::Container-->\r\n        <div id="pf_content_container" class="">\r\n            <!--begin::Row-->\r\n\r\n            <div class="row overflow-hidden-- vh-100-- min-vh-100--" id="PROFLOW-overalldiv">\r\n                <div class="Page-Title-Bar">\r\n                    <div class="Title-Section">\r\n\r\n\r\n                        <div class="Tkts-toolbar-Right">\r\n                            <button id="" type="submit" class="btn btn-sm btn-icon btn-primary btn-active-primary btn-custom-border-radius d-none">\r\n                                <span class="material-icons material-icons-style material-icons-2">add_task</span>\r\n                            </button>\r\n                            <button type="submit" id="" class="btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm tb-btn btn-sm" title="Refresh Page" onclick="axProcessObj.refreshPage();">\r\n                                <span class="material-icons material-icons-style material-icons-2">refresh</span>\r\n                            </button>\r\n\r\n                            <button id="pd_timeline" class="btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm tb-btn btn-sm d-none" data-kt-menu-trigger="click" data-kt-menu-placement="bottom-start" data-kt-menu-flip="top-end" data-kt-menu-attach="parent" title="Timeline">\r\n                                <span class="material-icons material-icons-style material-icons-2">history_toggle_off</span>\r\n                            </button>\r\n\r\n                            <div class="menu menu-sub menu-sub-dropdown menu-column menu-rounded menu-gray-600 menu-state-bg-light fw-bolder w-400px py-3" data-kt-menu="true" data-id="pd_timeline">\r\n                                <div id="TimeLine_overall" class="content">\r\n                                    <div class="card" id="Timeline-wrap">\r\n                                        <h1 class="Timeline-heading">\r\n                                            Timeline\r\n                                        </h1>\r\n                                        <ul class="Timel-sessions full-session d-none">\r\n                                        </ul>\r\n                                        <span id="nodata" class="p-5">No Timeline data available.</span>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n\r\n                        </div>\r\n\r\n                        <div class="top-panel" id="topPanel">\r\n\r\n                            <div class="Page-Title" id="process-name">\r\n                                <input type="checkbox" class="maincheckbox">\r\n\r\n                                <div class="btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm  tb-btn btn-sm " data-kt-menu-attach="parent" data-bs-title="Hide record List" data-bs-toggle="tooltip" data-bs-placement="bottom" title="" id="collapseicon">\r\n                                    <span class="material-icons material-icons-style material-icons-2">menu</span>\r\n                                </div>\r\n\r\n\r\n                                <span>My Inbox</span>\r\n\r\n\r\n\r\n                                <div class="Tkts-toolbar-Left">\r\n                                    <div class="d-flex gap-1">\r\n                                        <div class="d-flex-- align-items-stretch flex-shrink-0 gap-8 filterAlignChild">\r\n                                            <div class="btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm  tb-btn btn-sm d-none" data-kt-menu-attach="parent" data-bs-title="Next Record" data-bs-toggle="tooltip" data-bs-placement="bottom" id="nextrecord">\r\n                                                <span class="material-icons material-icons-style material-icons-2">arrow_downward</span>\r\n                                            </div>\r\n                                            <div class="btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm  tb-btn btn-sm d-none" data-kt-menu-attach="parent" data-bs-title="Previous Record" data-bs-toggle="tooltip" data-bs-placement="bottom" id="previousrecord">\r\n                                                <span class="material-icons material-icons-style material-icons-2">arrow_upward</span>\r\n                                            </div>\r\n\r\n\r\n\r\n                                            <div class="btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm  tb-btn btn-sm" data-kt-menu-placement="bottom" data-kt-menu-flip="top" data-kt-menu-attach="parent" id="filterButton" data-kt-menu-trigger="click">\r\n                                                <span class="material-icons material-icons-style material-icons-2" data-bs-toggle="tooltip" data-bs-title="Filter">filter_list</span>\r\n                                            </div>\r\n\r\n                                            <div class="menu menu-sub menu-sub-dropdown menu-column menu-rounded  menu-title-gray-700 menu-icon-gray-500 menu-active-bg menu-state-color fw-semibold py-4 fs-base w-250px" data-kt-menu="true" id="ktMenu" data-kt-element="theme-mode-menu">\r\n                                                <div class="menu-item cursor-pointer">\r\n                                                    <a href="#" class="menu-link active" id="alllist" data-id="all">\r\n                                                        <span class="menu-icon">\r\n                                                            <span class="material-icons">mail</span></span>\r\n                                                        <span class="menu-title">All</span>\r\n                                                        <span class="menu-count">150</span>\r\n                                                    </a>\r\n                                                </div>\r\n                                                <div class="menu-item cursor-pointer">\r\n                                                    <a href="#" class="menu-link" id="Open_Task" data-id="">\r\n                                                        <span class="menu-icon">\r\n                                                            <span class="material-icons">mark_email_unread</span></span>\r\n\r\n                                                        <span class="menu-title">Open Task</span>\r\n                                                        <span class="menu-count">10</span>\r\n                                                    </a>\r\n                                                </div>\r\n                                                <div class="menu-item cursor-pointer">\r\n                                                    <a href="#" class="menu-link" id="My_Team" data-id="">\r\n                                                        <span class="menu-icon">\r\n                                                            <span class="material-icons">groups</span></span>\r\n\r\n                                                        <span class="menu-title">My Team</span>\r\n                                                        <span class="menu-count">10</span>\r\n                                                    </a>\r\n                                                </div>\r\n                                                <div class="menu-item cursor-pointer">\r\n                                                    <a href="#" class="menu-link" id="Pending_Approval" data-id="">\r\n                                                        <span class="menu-icon">\r\n                                                            <span class="material-icons">mark_email_read</span></span>\r\n\r\n                                                        <span class="menu-title">Pending Approval</span>\r\n                                                        <span class="menu-count">10</span>\r\n                                                    </a>\r\n                                                </div>\r\n                                                <div class="menu-item cursor-pointer">\r\n                                                    <a href="#" class="menu-link" id="Unread" data-id="">\r\n                                                        <span class="menu-icon">\r\n                                                            <span class="material-icons">unsubscribe</span></span>\r\n\r\n                                                        <span class="menu-title">Unread</span>\r\n                                                        <span class="menu-count">10</span>\r\n                                                    </a>\r\n                                                </div>\r\n                                                <div class="menu-item cursor-pointer">\r\n                                                    <a href="#" class="menu-link" id="Send_Items" data-id="completed">\r\n                                                        <span class="menu-icon">\r\n                                                            <span class="material-icons">forward_to_inbox</span></span>\r\n\r\n                                                        <span class="menu-title">Send Items</span>\r\n                                                        <span class="menu-count">110</span>\r\n                                                    </a>\r\n                                                </div>\r\n\r\n\r\n                                            </div>\r\n\r\n                                            <div class="btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm  tb-btn btn-sm selectbtn" data-kt-menu-placement="bottom" data-kt-menu-flip="top" data-kt-menu-attach="parent">\r\n                                                <span class="material-icons material-icons-style material-icons-2" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-title="Select">copy</span>\r\n                                            </div>\r\n\r\n                                        </div>\r\n\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n\r\n\r\n\r\n                            <!-- Actions Section -->\r\n                            <div class="d-flex Right-Header-Section">\r\n\r\n\r\n\r\n                                <!-- <div class="Filter-Section-wrapper">\r\n                                    <span style="\r\n                                  font-size: small;\r\n                                  display: flex;\r\n                                  align-items: center;\r\n                                  justify-content: center;\r\n                                  color: gray;\r\n                                  margin: 5px;\r\n                              ">Filter</span>\r\n                                    <div class="hdr-dropdown main-filter">\r\n\r\n                                        <div class="hdr-btn submenu-toggle dropdown-toggle">\r\n                                            All\r\n                                            <!-- <span class="material-icons arrow">expand_more</span>\r\n                                        </div>\r\n\r\n                                        <div class="dropdown-menu">\r\n\r\n                                            <!-- ALL\r\n                                            <div class="dropdown-item" data-id="ALL">All</div>\r\n\r\n                                            <!-- MY TASKS \r\n                                            <div class="dropdown-item" data-id="Open Tasks">My Tasks</div>\r\n\r\n                                            <!-- MY TEAM TASKS\r\n                                            <div class="dropdown-submenu">\r\n                                                <div class="dropdown-item submenu-toggle dropdown-toggle">\r\n                                                    My Team Tasks\r\n                                                </div>\r\n                                                <div class="submenu">\r\n                                                    <div class="dropdown-item" data-id="TeamAll">All</div>\r\n                                                    <!-- dynamically append team members \r\n                                                    <div id="userSelect"></div>\r\n                                                </div>\r\n                                            </div>\r\n\r\n                                            <!-- PENDING APPROVAL\r\n                                            <div class="dropdown-item" data-id="Pending">My Pending Approvals</div>\r\n\r\n                                            <!-- OTHER FILTERS \r\n                                            <div class="dropdown-submenu">\r\n                                                <div class="dropdown-item submenu-toggle dropdown-toggle">\r\n                                                    Other Filters\r\n                                                </div>\r\n                                                <div class="submenu">\r\n                                                    <div class="dropdown-item" data-id="Approved">Approved</div>\r\n                                                    <div class="dropdown-item" data-id="Rejected">Rejected</div>\r\n                                                    <div class="dropdown-item" data-id="Returned">Returned</div>\r\n                                                    <!-- <div class="dropdown-item" data-id="Messages">Messages</div> \r\n                                                    <div class="dropdown-item" data-id="Notifications">Notifications\r\n                                                    </div>\r\n                                                </div>\r\n                                            </div>\r\n\r\n                                        </div>\r\n                                    </div>\r\n                                </div> -->\r\n\r\n                                <div class="section search-section">\r\n                                    <div class="search-box">\r\n                                        <input id="advTextSearch" class="search-input" placeholder="Search..">\r\n                                        <span class="material-icons search-icon" id="deepSearchToggle">search</span>\r\n\r\n                                        <!-- Deep search toggle -->\r\n                                        <!-- <span id="deepSearchToggle" class="material-icons filter-icon" title="Deep Search">\r\n                                              tune\r\n                                                     </span> -->\r\n                                    </div>\r\n                                </div>\r\n                                <div class="section actions">\r\n                                    <div>\r\n                                        <!-- Trigger -->\r\n                                        <div id="pd_all_tasksNew" class="act btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm tb-btn btn-sm" onclick="axProcessObj.openBulkApprove();" data-kt-menu-placement="bottom-start" data-kt-menu-flip="top-start" data-kt-menu-attach="parent" title="Bulk Approve">\r\n                                            <span class="material-icons material-icons-style material-icons-2">\r\n                                                checklist\r\n                                            </span>\r\n                                        </div>\r\n\r\n                                        <!-- Menu -->\r\n                                        <div class="menu menu-sub menu-sub-dropdown menu-rounded menu-gray-600 menu-state-bg-light fw-bolder w-300px py-3" data-kt-menu="true" data-id="pd_all_tasksNew">\r\n                                            <pd-alltasksnew></pd-alltasksnew>\r\n                                        </div>\r\n                                    </div>\r\n\r\n                                    <button id="schedulerBtn" class="act btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm tb-btn btn-sm ">\r\n                                        <span class="material-icons material-icons-style material-icons-2 initialized" data-bs-toggle="tooltip" data-bs-original-title="Scheduler" title="">calendar_month</span></button>\r\n\r\n                                    <button id="refreshBtn" class="act btn btn-icon btn-white btn-color-gray-600 btn-active-primary shadow-sm tb-btn btn-sm ">\r\n                                        <span class="material-icons material-icons-style material-icons-2 initialized" data-bs-toggle="tooltip" data-bs-original-title="Refresh" title="">refresh</span></button>\r\n                                </div>\r\n\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n                    <div class="row d-none" id="Process-stepper">\r\n                        <div class="col-md-12" id="horizontal">\r\n                            <ul class="stepper stepper-horizontal" id="horizontal-processbar">\r\n                            </ul>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n                <div id="filterMessageBar" class="filter-message-bar hidden">\r\n\r\n                    <span id="filterMessageText"></span>\r\n                    <button id="closeFilterBar" class="close-btn">✕</button>\r\n                </div>\r\n\r\n\r\n\r\n\r\n                <!--begin:::Col-->\r\n                <div class="col-xl-4 p-0 col-md-4 d-flex flex-column flex-column-fluid vh-100 min-vh-100" id="PROFLOW_Left">\r\n                    <div class="card card-xl-stretch  flex-root h-1px  ">\r\n\r\n                        <!--begin::Body-->\r\n                        <div class="card-body h-300px mb-3" id="body_Container">\r\n                            <div id="ProcessFlow_New-container">\r\n\r\n                                <div class="tab-content" id="ProcessFlow_Content">\r\n                                    <!-- <div class="tab-pane fade active show" role="tabpanel" id="Tickets_Pending">\r\n                                        <div id="plistContentPending">\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class="tab-pane fade" role="tabpanel" id="Tickets_Completed">\r\n                                        <div id="plistContentCompleted">\r\n                                        </div>\r\n                                    </div> -->\r\n\r\n                                    <div class="tab-pane fade active show" role="tabpanel" id="tickets">\r\n                                        <div id="InboxAccordion" class="inbox-accordion"></div>\r\n\r\n                                        <!-- <div id="plistContent"></div> -->\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                            <!--end::Body-->\r\n                        </div>\r\n\r\n                    </div>\r\n                    <!--end::Table Widget 1-->\r\n                </div>\r\n                <!--end:::Col-->\r\n                <!--begin:::Col-->\r\n                <div id="PROFLOW_Right" class="p-0 col-xl-8  col-md-8 d-flex flex-column flex-column-fluid vh-100 min-vh-100">\r\n                    <div class="card card-xl-stretch  flex-root h-1px  ">\r\n                        <iframe data-ignore-history="true" class="d-none horizontal-iframe" id="rightIframe" src="about:blank"></iframe>\r\n                        <!--begin::Body-->\r\n                        <div class="card-body p-0" id="Tickets_details_view">\r\n                            <div id="directoryChatPanel" class="directory-chat-panel d-none"></div>\r\n                            <div class="card mb-5 mb-xl-2 h-100" id="process_centerpanel">\r\n                                <div class="d-flex flex-column text-center h-100 justify-content-center" style="height:95%">\r\n                                    <span class="material-icons material-icons-style material-icons-5tx mx-auto text-gray-500">add_task</span>\r\n                                    <h3 class="fw-boldest">Select a task to load</h3>\r\n                                    <h6 class="fst-italic text-gray-400">Nothing is selected</h6>\r\n                                </div>\r\n                            </div>\r\n                            <!--end::Card body-->\r\n                        </div>\r\n\r\n                    </div>\r\n                    <!--end:::Col-->\r\n                </div>\r\n                <div id="ProcessFlow_New_Right_Last" class="col-xl-2 col-md-2 d-flex flex-column flex-column-fluid vh-100 min-vh-100 d-block d-none">\r\n                    <div class="card card-xl-stretch  flex-root h-1px  ">\r\n\r\n                        <!--begin::Body-->\r\n                        <div class="card-body h-300px ">\r\n                            <div class="row">\r\n                                <div class="col-xl-12 col-md-4 d-flex flex-column flex-column-fluid KPI_Section  ">\r\n                                    <div class="card ">\r\n                                        <div class="card-header collapsible cursor-pointer rotate " data-bs-toggle="collapse" aria-expanded="false" data-bs-target="#KPI-1">\r\n                                            <h3 class="card-title">KPI Title</h3>\r\n                                            <div class="card-toolbar rotate-180">\r\n                                                <span class="material-icons material-icons-style material-icons-2">\r\n                                                    expand_circle_down\r\n                                                </span>\r\n                                            </div>\r\n                                        </div>\r\n                                        <div class="collapse show" id="KPI-1">\r\n                                            <div class="card-body">\r\n                                                <figure>\r\n                                                    <img class="img-fluid" src="data:image/png;base64,">\r\n                                                </figure>\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class="card ">\r\n                                        <div class="card-header collapsible cursor-pointer rotate" data-bs-toggle="collapse" aria-expanded="true" data-bs-target="#KPI-2">\r\n                                            <h3 class="card-title">KPI Title</h3>\r\n                                            <div class="card-toolbar rotate-180">\r\n                                                <span class="material-icons material-icons-style material-icons-2">\r\n                                                    expand_circle_down\r\n                                                </span>\r\n                                            </div>\r\n                                        </div>\r\n                                        <div class="collapse show" id="KPI-2">\r\n                                            <div class="card-body">\r\n                                                <figure>\r\n                                                    <img class="img-fluid" src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTvyClOEGXUMdXM2DezoaC8GkYJ_Oo6BOSQAg&amp;usqp=CAU">\r\n                                                </figure>\r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <!--end::Container-->\r\n            </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n\r\n    <!--end::Content-->\r\n    <div id="waitDiv" class="page-loader rounded-2 bg-radial-gradient">\r\n        <div class="loader-box-wrapper d-flex bg-white p-20 shadow rounded">\r\n            <span class="loader"></span>\r\n        </div>\r\n    </div>\r\n\r\n    <div class="modal fade" id="filterModal">\r\n        <div class="modal-dialog modal-fullscreen modal-dialog-scrollable">\r\n            <div class="modal-content">\r\n\r\n                <!-- Modal body -->\r\n                <div class="modal-body p-0">\r\n                    <div class="container" id="dvModalFilter"></div>\r\n                </div>\r\n\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class="modal fade" id="teamModal" tabindex="-1">\r\n        <div class="modal-dialog modal-dialog-scrollable">\r\n            <div class="modal-content">\r\n\r\n                <!-- Header -->\r\n                <div class="modal-header">\r\n                    <h5 class="modal-title">Team Tasks</h5>\r\n                    <button type="button" class="btn-close---" data-bs-dismiss="modal"></button>\r\n                </div>\r\n\r\n                <!-- Body -->\r\n                <div class="modal-body" id="teamPopupContent">\r\n                    <!-- Dynamic content -->\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <script type="text/javascript" src="../../UI/axpertUI/plugins.bundle.js"></script>\r\n    <script type="text/javascript" src="../../UI/axpertUI/scripts.bundle.js"></script>\r\n    <script type="text/javascript" src="../../ThirdParty/jquery-confirm-master/jquery-confirm.min.js"></script>\r\n    <script type="text/javascript" src="../../Js/alerts.min.js?v=32"></script>\r\n    <script type="text/javascript" src="../../Js/handlebars.min.js?v=2"></script>\r\n    <script type="text/javascript" src="../../Js/common.min.js?v=158"></script>\r\n    <script type="text/javascript" src="../../Js/helper.min.js?v=172"></script>\r\n    <script type="text/javascript" src="../../Js/xmlToJson.min.js"></script>\r\n    <script type="text/javascript" src="../../Js/AxProcessFlowCommon.min.js?v=1"></script>\r\n    <script type="text/javascript" src="../HTMLPages/js/AxProcessFlow_V3.js?v=5"></script>\r\n    <script src="../report/js/taskslst_inbox.js?v=1230202515104"></script>\r\n\r\n\r\n    <script type="text/javascript">\r\n        var _processName = ''AxProcessFlow'';\r\n    </script>\r\n\r\n    <script>\r\n        class InboxV2 {\r\n\r\n            constructor() {\r\n\r\n                this.store = {\r\n                    approvalPending: [],\r\n                    approvalRequested: [],\r\n                    reminders: [],\r\n                    escalations: [],\r\n                    completed: []\r\n\r\n                };\r\n                this.schedulerFromLHS = false;\r\n                this.schedulerUserName = "";\r\n                this.currentChildSection = "approvalPending";\r\n                this.currentSection = "approvals";\r\n                this.pageSize = 0;\r\n                this.clientChunkSize = 20;\r\n                this.clientRenderLimit = {\r\n\r\n                    pending: 20,\r\n\r\n                    completed: 20,\r\n                    reminders: 20,\r\n                    escalations: 20,\r\n                };\r\n\r\n                this.pagination = {\r\n                    reminders: 1,\r\n                    escalations: 1,\r\n                    completed: 1\r\n                };\r\n\r\n                this.loading = {\r\n                    tasks: false,\r\n                    pending: false,\r\n                    notifications: false,\r\n                    completed: false,\r\n                    reminders: true,\r\n                    escalations: true,\r\n                    people: false,\r\n                    groups: false\r\n\r\n                };\r\n                this.visibleCount = {\r\n\r\n                    reminders: 0,\r\n                    escalations: 0,\r\n                    approvalPending: 0,\r\n                    approvalRequested: 0,\r\n\r\n                    completed: 0\r\n                };\r\n                this.hasMore = {\r\n                    tasks: true,\r\n                    pending: true,\r\n                    notifications: true,\r\n                    completed: true,\r\n                    reminders: false,\r\n                    people: true,\r\n                    groups: true\r\n                };\r\n                this.chatThreads = {};\r\n                this.activeConversationKey = "";\r\n                this.activeConversationItem = null;\r\n                this.activeConversationSection = "";\r\n                this.peopleSourceRows = [];\r\n                this.peopleSearchText = "";\r\n                this.groupSourceRows = [];\r\n                this.groupSearchText = "";\r\n                this.groupChildrenCache = {};\r\n                this.groupChildrenLoading = {};\r\n                this.expandedGroupKey = "";\r\n                this.accordionDelegateBound = false;\r\n                this.sections = [\r\n                    {\r\n                        key: "approvals",\r\n                        label: "Approvals",\r\n                        children: [\r\n                            {\r\n                                key: "approvalPending",\r\n                                label: "Approvals Pending With Me",\r\n                                ds: "DS_PendingApprovals"\r\n                            },\r\n                            {\r\n                                key: "approvalRequested",\r\n                                label: "Approvals Requested By Me",\r\n                                ds: "REQUESTEDBYME"\r\n                            }\r\n                        ]\r\n                    },\r\n                    {\r\n                        key: "reminders",\r\n                        label: "Reminders",\r\n                        ds: "DS_Reminders"\r\n                    },\r\n                    {\r\n                        key: "escalations",\r\n                        label: "Escalations",\r\n                        ds: "DS_Escalations"\r\n                    },\r\n                    {\r\n                        key: "completed",\r\n                        label: "Completed",\r\n                        ds: "DS_Completed"\r\n                    }\r\n                ];\r\n\r\n                this.init();\r\n            }\r\n\r\n            async init() {\r\n\r\n                this.cacheDom();\r\n                //     this.showDefaultRightPanel();\r\n\r\n                this.bindEvents();\r\n\r\n                await Promise.all([\r\n\r\n                    await this.loadAllDS(),\r\n\r\n                    // this.loadSection("pending"),\r\n\r\n                    // this.loadSection("notifications"),\r\n\r\n                    //  this.loadSection("completed"),\r\n\r\n                    // this.loadSection("people"),\r\n\r\n                    // this.loadSection("groups")\r\n                ]);\r\n\r\n                this.buildAccordion();\r\n\r\n                //   this.renderSection("tasks");\r\n            }\r\n\r\n            cacheDom() {\r\n\r\n                this.accordionEl =\r\n                    document.getElementById("InboxAccordion");\r\n\r\n                this.contentEl =\r\n                    document.getElementById("plistContent");\r\n\r\n                this.searchEl =\r\n                    document.getElementById("advTextSearch");\r\n\r\n                this.refreshBtn =\r\n                    document.getElementById("refreshBtn");\r\n\r\n                this.rightIframe =\r\n                    document.getElementById("rightIframe");\r\n\r\n                this.rightPanelHostEl =\r\n                    document.getElementById("Tickets_details_view") ||\r\n                    document.getElementById("PROFLOW_Right");\r\n\r\n                this.directoryChatPanelEl =\r\n                    document.getElementById("directoryChatPanel");\r\n\r\n                this.processCenterPanelEl =\r\n                    document.getElementById("process_centerpanel");\r\n\r\n                this.defaultRightPanelHtml =\r\n                    this.processCenterPanelEl?.innerHTML || "";\r\n            }\r\n\r\n            bindEvents() {\r\n\r\n                if (\r\n                    this.searchEl &&\r\n                    typeof this.searchEl.addEventListener === "function"\r\n                ) {\r\n                    this.searchEl.addEventListener(\r\n                        "input",\r\n                        this.debounce(async () => {\r\n                            const sections = [\r\n                                "tasks",\r\n                                "pending",\r\n                                // "notifications",\r\n                                "completed",\r\n                                // "people",\r\n                                // "groups"\r\n                            ];\r\n\r\n                            sections.forEach(section => {\r\n                                this.resetSectionLoadState(section);\r\n                            });\r\n\r\n                            await Promise.all([\r\n                                this.loadSection("tasks"),\r\n                                this.loadSection("pending"),\r\n                                // this.loadSection("notifications"),\r\n                                this.loadSection("completed"),\r\n                                // this.loadSection("people"),\r\n                                // this.loadSection("groups")\r\n                            ]);\r\n                        }, 500)\r\n                    );\r\n                }\r\n\r\n                if (\r\n                    this.refreshBtn &&\r\n                    typeof this.refreshBtn.addEventListener === "function"\r\n                ) {\r\n                    this.refreshBtn.addEventListener("click", async () => {\r\n                        // 1️⃣ Reset Chat layout states and hide the active chat containers immediately\r\n                        if (this.directoryChatPanelEl) {\r\n                            this.directoryChatPanelEl.classList.add("d-none");\r\n                            this.directoryChatPanelEl.style.display = "none";\r\n                        }\r\n\r\n                        // Clear active chat message threads or active receiver details if tracked\r\n                        this.activeChatId = null;\r\n                        this.activeReceiver = null;\r\n\r\n                        // 2️⃣ Stop any active background polling timers/intervals so they don''t fight for DOM space\r\n                        if (this.chatRefreshInterval) {\r\n                            clearInterval(this.chatRefreshInterval);\r\n                            this.chatRefreshInterval = null;\r\n                        }\r\n                        if (this.pollingTimer) {\r\n                            clearInterval(this.pollingTimer);\r\n                            this.pollingTimer = null;\r\n                        }\r\n\r\n\r\n\r\n                        showDefaultRightPanel();\r\n\r\n\r\n                        // 4️⃣ Remove selected/active background highlights from list elements\r\n                        if (this.accordionEl) {\r\n                            this.accordionEl\r\n                                .querySelectorAll(".directory-row.selected, .task-item.selected, .active")\r\n                                .forEach(row => row.classList.remove("selected", "active"));\r\n                        }\r\n\r\n                        // 5️⃣ Existing load section refreshes\r\n                        const sections = [\r\n                            "tasks",\r\n                            "pending",\r\n                            "notifications",\r\n                            "completed",\r\n                            "people",\r\n                            "groups"\r\n                        ];\r\n\r\n                        sections.forEach(section => {\r\n                            this.resetSectionLoadState(section);\r\n                        });\r\n\r\n                        await Promise.all([\r\n                            this.loadSection("tasks"),\r\n                            this.loadSection("pending"),\r\n                            this.loadSection("notifications"),\r\n                            this.loadSection("completed"),\r\n                            this.loadSection("people"),\r\n                            this.loadSection("groups")\r\n                        ]);\r\n                    });\r\n                    if (this.directoryChatPanelEl) {\r\n                        this.directoryChatPanelEl.classList.add("d-none");\r\n                        this.directoryChatPanelEl.style.display = "none";\r\n                    }\r\n                }\r\n            }\r\n\r\n            resetSectionLoadState(section) {\r\n                this.pagination[section] = 1;\r\n                this.hasMore[section] = true;\r\n                this.store[section] = [];\r\n                this.visibleCount[section] = 0;\r\n\r\n                if (this.isClientPagedSection(section)) {\r\n                    this.clientRenderLimit[section] =\r\n                        this.clientChunkSize;\r\n                }\r\n\r\n                if (section === "groups") {\r\n                    this.groupChildrenCache = {};\r\n                    this.groupChildrenLoading = {};\r\n                    this.expandedGroupKey = "";\r\n                }\r\n            }\r\n\r\n            async loadAllDS() {\r\n\r\n                const searchText = this.searchEl?.value || "";\r\n\r\n                const promises = [];\r\n\r\n                this.sections.forEach(section => {\r\n\r\n                    // Parent has children\r\n                    if (section.children) {\r\n\r\n                        section.children.forEach(child => {\r\n\r\n                            promises.push((async () => {\r\n\r\n                                const rows = await this.fetchDS(\r\n                                    child.ds,\r\n                                    searchText,\r\n                                    1\r\n                                );\r\n\r\n                                this.store[child.key] =\r\n                                    this.sortLatest(rows.rows || []);\r\n\r\n                                this.visibleCount[child.key] =\r\n                                    rows.totalCount ??\r\n                                    (rows.rows || []).length;\r\n\r\n                            })());\r\n\r\n                        });\r\n\r\n                    }\r\n                    // Normal accordion\r\n                    else if (section.ds) {\r\n\r\n                        promises.push((async () => {\r\n\r\n                            const rows = await this.fetchDS(\r\n                                section.ds,\r\n                                searchText,\r\n                                1\r\n                            );\r\n\r\n                            this.store[section.key] =\r\n                                this.sortLatest(rows.rows || []);\r\n\r\n                            this.visibleCount[section.key] =\r\n                                rows.totalCount ??\r\n                                (rows.rows || []).length;\r\n\r\n                        })());\r\n\r\n                    }\r\n\r\n                });\r\n\r\n                await Promise.all(promises);\r\n\r\n                this.buildAccordion();\r\n            }\r\n            fetchDS(\r\n                dsName,\r\n                searchText = "",\r\n                pageNo = 1,\r\n                extraSqlParams = {},\r\n                requestOptions = {}\r\n            ) {\r\n\r\n                return new Promise((resolve, reject) => {\r\n                    const safeExtraSqlParams =\r\n                        extraSqlParams &&\r\n                            typeof extraSqlParams === "object"\r\n                            ? extraSqlParams\r\n                            : {};\r\n                    const safeRequestOptions =\r\n                        requestOptions &&\r\n                            typeof requestOptions === "object"\r\n                            ? requestOptions\r\n                            : {};\r\n                    const includeDefaultSqlParams =\r\n                        safeRequestOptions.includeDefaultSqlParams !== false;\r\n\r\n                    const params = {\r\n\r\n                        adsNames: [dsName],\r\n\r\n                        props: {\r\n                            pageno: pageNo,\r\n                            pagesize: this.pageSize\r\n                        },\r\n\r\n                        sqlParams: includeDefaultSqlParams\r\n                            ? {\r\n\r\n                                uname:\r\n                                    parent.mainUserName,\r\n\r\n                                searchtext:\r\n                                    searchText,\r\n\r\n                                ...safeExtraSqlParams\r\n                            }\r\n                            : {\r\n                                ...safeExtraSqlParams\r\n                            }\r\n                    };\r\n\r\n                    parent.GetDataFromAxList(\r\n\r\n                        params,\r\n\r\n                        (response) => {\r\n\r\n                            try {\r\n\r\n                                const rawResponse =\r\n                                    typeof response === "string"\r\n                                        ? response\r\n                                        : typeof response?.d === "string"\r\n                                            ? response.d\r\n                                            : JSON.stringify(response?.d || response);\r\n\r\n                                const parsedResponse =\r\n                                    JSON.parse(rawResponse);\r\n\r\n                                const parsed =\r\n                                    typeof parsedResponse?.d === "string"\r\n                                        ? JSON.parse(parsedResponse.d)\r\n                                        : parsedResponse;\r\n\r\n                                const ds =\r\n                                    parsed?.result?.data?.[0] || {};\r\n\r\n                                const rows =\r\n                                    ds.data || [];\r\n\r\n                                const totalCount =\r\n                                    ds.totalcount ||\r\n                                    ds.recordcount ||\r\n                                    ds.totalrows ||\r\n                                    rows.length;\r\n\r\n                                resolve({\r\n                                    rows,\r\n                                    totalCount\r\n                                });\r\n\r\n                            } catch (e) {\r\n\r\n                                console.error(e);\r\n\r\n                                resolve({\r\n                                    rows: [],\r\n                                    totalCount: 0\r\n                                });\r\n                            }\r\n                        },\r\n\r\n                        reject\r\n                    );\r\n                });\r\n            }\r\n            sortLatest(data = []) {\r\n\r\n                return data.sort((a, b) => {\r\n\r\n                    const d1 = new Date(\r\n                        b.modifiedon ||\r\n                        b.createdon ||\r\n                        b.createddate ||\r\n                        0\r\n                    );\r\n\r\n                    const d2 = new Date(\r\n                        a.modifiedon ||\r\n                        a.createdon ||\r\n                        a.createddate ||\r\n                        0\r\n                    );\r\n\r\n                    return d1 - d2;\r\n                });\r\n            }\r\n\r\n            isClientPagedSection(section) {\r\n                return true;\r\n            }\r\n\r\n            getRenderedSectionRows(section, data = []) {\r\n                if (!this.isClientPagedSection(section)) {\r\n                    return data;\r\n                }\r\n\r\n                const limit =\r\n                    this.clientRenderLimit[section] ||\r\n                    this.clientChunkSize;\r\n\r\n                return data.slice(0, limit);\r\n            }\r\n\r\n            getRenderedSectionCount(section) {\r\n                const data = this.store[section] || [];\r\n\r\n                if (!this.isClientPagedSection(section)) {\r\n                    return data.length;\r\n                }\r\n\r\n                return Math.min(\r\n                    this.clientRenderLimit[section] ||\r\n                    this.clientChunkSize,\r\n                    data.length\r\n                );\r\n            }\r\n\r\n            revealNextClientRows(section, scrollBody) {\r\n                if (!this.isClientPagedSection(section)) {\r\n                    return false;\r\n                }\r\n\r\n                const data = this.store[section] || [];\r\n                const start = this.getRenderedSectionCount(section);\r\n\r\n                if (start >= data.length) {\r\n                    return false;\r\n                }\r\n\r\n                const nextLimit = Math.min(\r\n                    start + this.clientChunkSize,\r\n                    data.length\r\n                );\r\n                const rows = data.slice(start, nextLimit);\r\n\r\n                this.clientRenderLimit[section] = nextLimit;\r\n\r\n                if (scrollBody) {\r\n                    scrollBody.insertAdjacentHTML(\r\n                        "beforeend",\r\n                        this.renderCards(rows, section, start)\r\n                    );\r\n                    this.updateSectionCount(section);\r\n                    this.bindDirectoryAndTaskClicks();\r\n                    this.bindAccordionScrollHandoff();\r\n                } else {\r\n                    this.buildAccordion();\r\n                }\r\n\r\n                return true;\r\n            }\r\n\r\n            updateSectionCount(section) {\r\n\r\n                let countBadge =\r\n                    this.accordionEl.querySelector(\r\n                        `.v2-child-header[data-section="${section}"] .inbox-count`\r\n                    );\r\n\r\n                if (!countBadge) {\r\n\r\n                    countBadge =\r\n                        this.accordionEl.querySelector(\r\n                            `.v2-accordion-header[data-section="${section}"] .inbox-count`\r\n                        );\r\n                }\r\n\r\n                if (!countBadge) return;\r\n\r\n                const total =\r\n                    this.visibleCount[section] ??\r\n                    this.store[section].length;\r\n\r\n                const shown =\r\n                    this.getRenderedSectionCount(section);\r\n\r\n                countBadge.innerText = `${shown}/${total}`;\r\n            }\r\n\r\n            buildAccordion() {\r\n\r\n                if (!this.accordionEl) return;\r\n\r\n                let html = "";\r\n                this.sections\r\n                    .filter(section => !section.isChildOf)\r\n                    .forEach(section => {\r\n\r\n                        const expanded = this.currentSection === section.key;\r\n                        const data = this.store[section.key] || [];\r\n\r\n                        const renderedData =\r\n                            this.getRenderedSectionRows(section.key, data);\r\n\r\n                        const totalCount =\r\n                            this.visibleCount[section.key] ?? data.length;\r\n\r\n                        const shownCount =\r\n                            this.isClientPagedSection(section.key)\r\n                                ? renderedData.length\r\n                                : data.length;\r\n                        html += `\r\n        <div class="v2-accordion-item">\r\n\r\n            <div class="v2-accordion-header ${expanded ? "active" : ""}"\r\n                 data-section="${section.key}">\r\n\r\n                <div class="v2-left">\r\n                    <span class="material-icons">\r\n                        ${expanded ? "expand_less" : "expand_more"}\r\n                    </span>\r\n\r\n                    <span class="v2-title">\r\n                        ${section.label}\r\n                    </span>\r\n                </div>\r\n ${!section.children\r\n                                ? `<span class="inbox-count">\r\n                   ${shownCount}/${totalCount}\r\n               </span>`\r\n                                : ""\r\n                            }\r\n            </div>\r\n\r\n            <div class="v2-accordion-body ${expanded ? "show" : ""}">\r\n        `;\r\n\r\n                        // Child accordions\r\n                        const children = section.children || [];\r\n\r\n                        if (children.length) {\r\n\r\n                            children.forEach(child => {\r\n\r\n                                const data = this.store[child.key] || [];\r\n\r\n                                const renderedData =\r\n                                    this.getRenderedSectionRows(child.key, data);\r\n\r\n                                const totalCount =\r\n                                    this.visibleCount[child.key] ??\r\n                                    data.length;\r\n\r\n                                const shownCount =\r\n                                    this.isClientPagedSection(child.key)\r\n                                        ? renderedData.length\r\n                                        : data.length;\r\n\r\n                                html += `\r\n                <div class="v2-child-item">\r\n\r\n                    <div class="v2-child-header ${this.currentChildSection === child.key ? "active" : ""\r\n                                    }"\r\n                         data-section="${child.key}">\r\n\r\n                        <div class="v2-left">\r\n\r\n                           <span class="material-icons">\r\n    ${this.currentChildSection === child.key\r\n                                        ? "expand_less"\r\n                                        : "expand_more"\r\n                                    }\r\n</span>\r\n\r\n                            <span class="v2-title">\r\n                                ${child.label}\r\n                            </span>\r\n\r\n                        </div>\r\n\r\n                        <span class="inbox-count">\r\n                            ${shownCount}/${totalCount}\r\n                        </span>\r\n\r\n                    </div>\r\n\r\n                    <div class="v2-child-body ${this.currentChildSection === child.key ? "show" : ""\r\n                                    }">\r\n\r\n                        <div class="v2-scroll-body"\r\n                             data-section="${child.key}">\r\n\r\n                            ${this.renderCards(\r\n                                        renderedData,\r\n                                        child.key\r\n                                    )}\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n                </div>\r\n                `;\r\n                            });\r\n\r\n                        } else {\r\n\r\n                            // Normal accordion (Pending, Completed...)\r\n                            const data = this.store[section.key] || [];\r\n\r\n                            const renderedData =\r\n                                this.getRenderedSectionRows(section.key, data);\r\n\r\n                            html += `\r\n            <div class="v2-scroll-body"\r\n                 data-section="${section.key}">\r\n\r\n                ${this.renderCards(\r\n                                renderedData,\r\n                                section.key\r\n                            )}\r\n\r\n            </div>\r\n            `;\r\n                        }\r\n\r\n                        html += `\r\n            </div>\r\n        </div>\r\n        `;\r\n                    });\r\n                //                 this.sections.forEach(section => {\r\n\r\n                //                     const data =\r\n                //                         this.store[section.key] || [];\r\n                //                     const renderedData =\r\n                //                         this.getRenderedSectionRows(\r\n                //                             section.key,\r\n                //                             data\r\n                //                         );\r\n\r\n                //                     const expanded =\r\n                //                         this.currentSection === section.key;\r\n                //                     const totalCount =\r\n                //                         this.visibleCount[section.key] ??\r\n                //                         data.length ??\r\n                //                         0;\r\n                //                     const shownCount =\r\n                //                         this.isClientPagedSection(section.key)\r\n                //                             ? renderedData.length\r\n                //                             : data.length;\r\n\r\n                //                     html += `\r\n\r\n                //             <div class="v2-accordion-item">\r\n\r\n                //                 <div class="\r\n                //                     v2-accordion-header\r\n                //                     ${expanded ? "active" : ""}\r\n                //                 "\r\n                //                 data-section="${section.key}">\r\n\r\n                //                     <div class="v2-left">\r\n\r\n                //                         <span class="material-icons">\r\n                //                             ${expanded ? "expand_less" : "expand_more"}\r\n                //                         </span>\r\n\r\n                //                         <span class="v2-title">\r\n                //                             ${section.label}\r\n                //                         </span>\r\n\r\n                //                     </div>\r\n\r\n                //               <span class="inbox-count">\r\n                //    ${shownCount}/${totalCount}\r\n                // </span>\r\n                //                 </div>\r\n\r\n                //               <div class="\r\n                //     v2-accordion-body\r\n                //     ${expanded ? "show" : ""}\r\n                // ">\r\n\r\n                //     <div class="v2-scroll-body"\r\n                //          data-section="${section.key}">\r\n\r\n                //         ${this.renderCards(\r\n                //                         renderedData,\r\n                //                         section.key\r\n                //                     )}\r\n\r\n                //     </div>\r\n\r\n                // </div>\r\n                //         `;\r\n                //                 });\r\n\r\n                this.accordionEl.innerHTML = html;\r\n\r\n                this.bindAccordionClicks();\r\n                this.bindDirectoryAndTaskClicks();\r\n                this.bindScrollPagination();\r\n                this.bindAccordionScrollHandoff();\r\n\r\n            }\r\n            bindAccordionClicks() {\r\n\r\n                // Parent accordion click\r\n                document\r\n                    .querySelectorAll(".v2-accordion-header")\r\n                    .forEach(el => {\r\n\r\n                        el.onclick = (e) => {\r\n\r\n                            e.stopPropagation();\r\n\r\n                            const parent =\r\n                                el.dataset.parent || el.dataset.section;\r\n\r\n                            this.currentSection =\r\n                                this.currentSection === parent\r\n                                    ? ""\r\n                                    : parent;\r\n\r\n                            this.buildAccordion();\r\n                        };\r\n                    });\r\n\r\n                // Child accordion click\r\n                document\r\n                    .querySelectorAll(".v2-child-header")\r\n                    .forEach(el => {\r\n\r\n                        el.onclick = async (e) => {\r\n\r\n                            e.stopPropagation();\r\n\r\n                            const section = el.dataset.section;\r\n\r\n                            const body = el.nextElementSibling;\r\n\r\n                            // Load only first time\r\n                            if (!this.store[section]?.length) {\r\n\r\n                                await this.loadSection(section);\r\n\r\n                                body.querySelector(".v2-scroll-body").innerHTML =\r\n                                    this.renderCards(\r\n                                        this.store[section],\r\n                                        section\r\n                                    );\r\n                            }\r\n\r\n                            body.classList.toggle("show");\r\n\r\n                            const icon =\r\n                                el.querySelector(".material-icons");\r\n\r\n                            icon.innerText =\r\n                                body.classList.contains("show")\r\n                                    ? "expand_less"\r\n                                    : "expand_more";\r\n                        };\r\n\r\n                    });\r\n\r\n                document.addEventListener("click", e => {\r\n\r\n                    const icon = e.target.closest(".people-scheduler");\r\n                    if (!icon) return;\r\n\r\n                    e.preventDefault();\r\n                    e.stopPropagation();\r\n\r\n                    const row = icon.closest(".people-row");\r\n\r\n                    this.schedulerFromLHS = true;\r\n                    this.schedulerUserName = row.dataset.uname;\r\n\r\n                    document.getElementById("schedulerBtn").click();\r\n                });\r\n\r\n            }\r\n\r\n            ensureRightPanelHosts() {\r\n                this.rightPanelHostEl =\r\n                    document.getElementById("Tickets_details_view") ||\r\n                    document.getElementById("PROFLOW_Right");\r\n\r\n                this.rightIframe =\r\n                    document.getElementById("rightIframe");\r\n\r\n                this.processCenterPanelEl =\r\n                    document.getElementById("process_centerpanel");\r\n\r\n                this.directoryChatPanelEl =\r\n                    document.getElementById("directoryChatPanel");\r\n\r\n                if (\r\n                    this.rightPanelHostEl &&\r\n                    this.directoryChatPanelEl &&\r\n                    !this.rightPanelHostEl.contains(\r\n                        this.directoryChatPanelEl\r\n                    )\r\n                ) {\r\n                    this.rightPanelHostEl.insertBefore(\r\n                        this.directoryChatPanelEl,\r\n                        this.rightPanelHostEl.firstChild\r\n                    );\r\n                }\r\n\r\n                if (\r\n                    this.rightPanelHostEl &&\r\n                    !this.directoryChatPanelEl\r\n                ) {\r\n                    this.directoryChatPanelEl =\r\n                        document.createElement("div");\r\n                    this.directoryChatPanelEl.id =\r\n                        "directoryChatPanel";\r\n                    this.directoryChatPanelEl.className =\r\n                        "directory-chat-panel d-none";\r\n\r\n                    this.rightPanelHostEl.insertBefore(\r\n                        this.directoryChatPanelEl,\r\n                        this.rightPanelHostEl.firstChild\r\n                    );\r\n                }\r\n\r\n                if (this.rightPanelHostEl) {\r\n                    this.rightPanelHostEl.style.position = "relative";\r\n                }\r\n            }\r\n\r\n            showProcessCenterPanel(html) {\r\n                this.ensureRightPanelHosts();\r\n\r\n                if (!this.processCenterPanelEl) return;\r\n\r\n                this.showTaskPanelHost();\r\n\r\n                this.processCenterPanelEl.innerHTML = html;\r\n            }\r\n\r\n            showDirectoryChatPanel(html) {\r\n                this.ensureRightPanelHosts();\r\n\r\n                if (!this.directoryChatPanelEl) return;\r\n\r\n                if (this.processCenterPanelEl) {\r\n                    this.processCenterPanelEl.style.display = "none";\r\n                    this.processCenterPanelEl.classList.add("d-none");\r\n                }\r\n\r\n                if (this.rightIframe) {\r\n                    this.rightIframe.classList.add("d-none");\r\n                    if (this.rightIframe.getAttribute("src") !== "about:blank") {\r\n                        this.rightIframe.setAttribute("src", "about:blank");\r\n                    }\r\n                }\r\n\r\n                this.directoryChatPanelEl.innerHTML = html;\r\n                this.directoryChatPanelEl.style.display = "flex";\r\n                this.directoryChatPanelEl.style.position = "absolute";\r\n                this.directoryChatPanelEl.style.inset = "0";\r\n                this.directoryChatPanelEl.style.zIndex = "1000";\r\n                this.directoryChatPanelEl.style.background = "#f8fbff";\r\n                this.directoryChatPanelEl.classList.remove("d-none");\r\n\r\n                console.log("[InboxV2] right panel: chat rendered", {\r\n                    hasChatShell:\r\n                        !!this.directoryChatPanelEl.querySelector(\r\n                            ".chat-shell"\r\n                        ),\r\n                    panelState: this.getRightPanelDebugState()\r\n                });\r\n            }\r\n\r\n            showTaskPanelHost() {\r\n                this.ensureRightPanelHosts();\r\n\r\n                this.hideDirectoryChatPanel();\r\n\r\n                if (this.processCenterPanelEl) {\r\n                    this.processCenterPanelEl.style.display = "";\r\n                    this.processCenterPanelEl.classList.remove("d-none");\r\n                }\r\n\r\n                console.log("[InboxV2] right panel: task host shown", {\r\n                    panelState: this.getRightPanelDebugState()\r\n                });\r\n            }\r\n\r\n            hideDirectoryChatPanel() {\r\n                if (!this.directoryChatPanelEl) return;\r\n\r\n                this.directoryChatPanelEl.style.display = "none";\r\n                this.directoryChatPanelEl.classList.add("d-none");\r\n                this.directoryChatPanelEl.innerHTML = "";\r\n            }\r\n\r\n            getActiveRightPanelRoot() {\r\n                this.ensureRightPanelHosts();\r\n\r\n                if (\r\n                    this.directoryChatPanelEl &&\r\n                    !this.directoryChatPanelEl.classList.contains("d-none")\r\n                ) {\r\n                    return this.directoryChatPanelEl;\r\n                }\r\n\r\n                return this.processCenterPanelEl;\r\n            }\r\n\r\n            getRightPanelDebugState() {\r\n                return {\r\n                    currentSection: this.currentSection,\r\n                    rightHostId: this.rightPanelHostEl?.id || "",\r\n                    chatPanelInDom: !!this.directoryChatPanelEl?.isConnected,\r\n                    chatPanelHidden:\r\n                        this.directoryChatPanelEl?.classList.contains(\r\n                            "d-none"\r\n                        ),\r\n                    chatPanelDisplay:\r\n                        this.directoryChatPanelEl?.style.display || "",\r\n                    processPanelInDom:\r\n                        !!this.processCenterPanelEl?.isConnected,\r\n                    processPanelHidden:\r\n                        this.processCenterPanelEl?.classList.contains(\r\n                            "d-none"\r\n                        ),\r\n                    processPanelDisplay:\r\n                        this.processCenterPanelEl?.style.display || "",\r\n                    iframeHidden:\r\n                        this.rightIframe?.classList.contains("d-none")\r\n                };\r\n            }\r\n\r\n            activateDirectoryRow(directoryRow) {\r\n                const section =\r\n                    directoryRow.dataset.section || "";\r\n                const index =\r\n                    Number(directoryRow.dataset.index || 0);\r\n                const groupKey =\r\n                    directoryRow.dataset.groupKey || "";\r\n                const isGroupRow =\r\n                    directoryRow.classList.contains("group-row");\r\n\r\n                console.log("[InboxV2] switch: directory row clicked", {\r\n                    from: this.currentSection,\r\n                    to: section,\r\n                    index,\r\n                    groupKey,\r\n                    isGroupRow,\r\n                    panelState: this.getRightPanelDebugState()\r\n                });\r\n\r\n                if (isGroupRow) {\r\n                    this.toggleGroupUsers(groupKey);\r\n                    return;\r\n                }\r\n\r\n                if (section === "groupMembers") {\r\n                    this.openGroupMemberChat(groupKey, index);\r\n                    return;\r\n                }\r\n\r\n                this.openDirectoryChat(section, index);\r\n            }\r\n\r\n            bindDirectoryAndTaskClicks() {\r\n                if (!this.accordionEl) return;\r\n\r\n                if (!this.accordionDelegateBound) {\r\n                    this.accordionDelegateBound = true;\r\n\r\n                    window.addEventListener(\r\n                        "click",\r\n                        event => {\r\n                            const source =\r\n                                event.target instanceof Element\r\n                                    ? event.target\r\n                                    : event.target?.parentElement;\r\n\r\n                            const directoryRow =\r\n                                source?.closest?.(".directory-row");\r\n\r\n                            if (\r\n                                !directoryRow ||\r\n                                !this.accordionEl?.contains(directoryRow)\r\n                            ) {\r\n                                return;\r\n                            }\r\n\r\n                            event.preventDefault();\r\n                            event.stopPropagation();\r\n                            event.stopImmediatePropagation();\r\n\r\n                            this.activateDirectoryRow(directoryRow);\r\n                            const selectedRow =\r\n                                document.querySelector(".directory-row.selected");\r\n\r\n                            if (selectedRow) {\r\n\r\n                                const toUser =\r\n                                    selectedRow.querySelector(".directory-name")\r\n                                        ?.textContent?.trim();\r\n\r\n                                this.loadChatHistory(toUser);\r\n                                this.startChatPolling();\r\n                            }\r\n                        },\r\n                        true\r\n                    );\r\n\r\n                    this.accordionEl.addEventListener(\r\n                        "click",\r\n                        event => {\r\n                            const source =\r\n                                event.target instanceof Element\r\n                                    ? event.target\r\n                                    : event.target?.parentElement;\r\n\r\n                            const target =\r\n                                source?.closest?.(".tasktitle, .directory-row");\r\n\r\n                            if (!target || !this.accordionEl.contains(target)) {\r\n                                return;\r\n                            }\r\n\r\n                            event.preventDefault();\r\n                            event.stopPropagation();\r\n                            event.stopImmediatePropagation();\r\n\r\n                            if (target.classList.contains("tasktitle")) {\r\n                                const taskLink = target;\r\n\r\n                                const msgType = taskLink.dataset.msgtype || "NA";\r\n                                const taskId = taskLink.dataset.taskid || "";\r\n                                const hlinkParams = taskLink.dataset.hlinkParams || "";\r\n\r\n                                this.activeConversationKey = "";\r\n                                this.activeConversationItem = null;\r\n\r\n                                if (this.chatRefreshInterval) {\r\n                                    clearInterval(this.chatRefreshInterval);\r\n                                    this.chatRefreshInterval = null;\r\n                                }\r\n\r\n                                if (this.pollingTimer) {\r\n                                    clearInterval(this.pollingTimer);\r\n                                    this.pollingTimer = null;\r\n                                }\r\n\r\n                                this.hideDirectoryChatPanel();\r\n                                this.showTaskPanelHost();\r\n\r\n                                if (msgType === "NA" || msgType !== "Task" || msgType !== "Ticket") {\r\n\r\n                                    axProcessObj.openTask(\r\n                                        taskLink,\r\n                                        taskLink.dataset.taskname,\r\n                                        taskLink.dataset.tasktype,\r\n                                        taskLink.dataset.transid,\r\n                                        taskLink.dataset.keyfield,\r\n                                        taskLink.dataset.keyvalue,\r\n                                        taskLink.dataset.recordid,\r\n                                        taskId,\r\n                                        taskLink.dataset.indexno,\r\n                                        taskLink.dataset.hlinkTransid,\r\n                                        hlinkParams,\r\n                                        taskLink.dataset.processname,\r\n                                        msgType,\r\n                                        "LeftPanel"\r\n                                    );\r\n\r\n                                    axProcessObj.toggleRowBackground(taskLink);\r\n\r\n                                } else {\r\n\r\n                                    openTicketDetails(\r\n                                        taskId,\r\n                                        window.top.mainUserName,\r\n                                        msgType,\r\n                                        hlinkParams\r\n                                    );\r\n\r\n                                }\r\n\r\n\r\n\r\n                                return;\r\n                            }\r\n\r\n                            this.activateDirectoryRow(target);\r\n                        },\r\n                        true\r\n                    );\r\n                }\r\n\r\n                this.accordionEl\r\n                    .querySelectorAll(".tasktitle")\r\n                    .forEach(taskLink => {\r\n                        taskLink.onclick = event => {\r\n                            event.preventDefault();\r\n                            event.stopPropagation();\r\n                            event.stopImmediatePropagation();\r\n\r\n                            const taskId =\r\n                                taskLink.dataset.taskid || "";\r\n                            const touser =\r\n                                taskLink.dataset.touser || "";\r\n                            const tasktype =\r\n                                taskLink.dataset.tasktype || "";\r\n                            const hlinkParams =\r\n                                taskLink.dataset.hlinkParams || "";\r\n\r\n                            if (\r\n                                typeof window.openTicketDetails ===\r\n                                "function"\r\n                            ) {\r\n                                console.log(\r\n                                    "[InboxV2] switch: task detail clicked",\r\n                                    {\r\n                                        from: this.currentSection,\r\n                                        to: "task",\r\n                                        taskId,\r\n                                        touser,\r\n                                        tasktype,\r\n                                        hlinkParams,\r\n                                        panelState:\r\n                                            this.getRightPanelDebugState()\r\n                                    }\r\n                                );\r\n                                // Stop chat mode\r\n                                this.activeConversationKey = "";\r\n                                this.activeConversationItem = null;\r\n\r\n                                if (this.chatRefreshInterval) {\r\n                                    clearInterval(this.chatRefreshInterval);\r\n                                    this.chatRefreshInterval = null;\r\n                                }\r\n\r\n                                if (this.pollingTimer) {\r\n                                    clearInterval(this.pollingTimer);\r\n                                    this.pollingTimer = null;\r\n                                }\r\n\r\n                                this.hideDirectoryChatPanel();\r\n                                this.showTaskPanelHost();\r\n                                window.openTicketDetails(\r\n                                    taskId,\r\n                                    touser,\r\n                                    tasktype,\r\n                                    hlinkParams\r\n                                );\r\n                            }\r\n                        };\r\n                    });\r\n\r\n                this.accordionEl\r\n                    .querySelectorAll(".directory-row")\r\n                    .forEach(directoryRow => {\r\n                        const activate = async event => {\r\n                            event.preventDefault();\r\n                            event.stopPropagation();\r\n                            event.stopImmediatePropagation();\r\n\r\n                            this.activateDirectoryRow(directoryRow);\r\n                        };\r\n\r\n                        directoryRow.onclick = activate;\r\n                        directoryRow.onkeydown = event => {\r\n                            if (\r\n                                event.key === "Enter" ||\r\n                                event.key === " "\r\n                            ) {\r\n                                activate(event);\r\n                            }\r\n                        };\r\n                    });\r\n            }\r\n\r\n            // renderSection(section) {\r\n\r\n            //     const data =\r\n            //         this.store[section] || [];\r\n\r\n            //     this.renderCards(data);\r\n            // }\r\n\r\n            renderCards(data, section, startIndex = 0) {\r\n\r\n\r\n\r\n                if (section === "people") {\r\n                    return this.renderPeople(data);\r\n                }\r\n                if (!data.length) {\r\n\r\n                    return `\r\n            <div class="empty-state">\r\n                No records found\r\n            </div>\r\n        `;\r\n                }\r\n\r\n                let html = "";\r\n\r\n                if (section === "groups") {\r\n                    return data\r\n                        .map((item, index) =>\r\n                            this.renderGroupCard(item, startIndex + index)\r\n                        )\r\n                        .join("");\r\n                }\r\n\r\n                if (section === "people" || section === "groupMembers") {\r\n                    return data\r\n                        .map((item, index) =>\r\n                            this.renderDirectoryCard(\r\n                                item,\r\n                                section,\r\n                                startIndex + index\r\n                            )\r\n                        )\r\n                        .join("");\r\n                }\r\n\r\n                data.forEach((item, index) => {\r\n\r\n                    const title =\r\n                        item.subject ||\r\n                        item.displaytitle ||\r\n                        item.taskname ||\r\n                        "Untitled";\r\n\r\n                    const content =\r\n                        item.displaycontent ||\r\n                        item.processname ||\r\n                        item.description ||\r\n                        "";\r\n\r\n                    const date =\r\n                        item.eventdatetime ||\r\n                        item.modifiedon ||\r\n                        item.createdon ||\r\n                        "";\r\n                    const taskId = getTaskId(item);\r\n                    const checkboxId = taskId || item.taskid || index;\r\n\r\n\r\n                    html += `\r\n\r\n<div class="container listrow completed-row"\r\n     data-status="${this.escapeHtml(item.cstatus || "")}"\r\n     data-index="${index}">\r\n\r\n    <div class="row">\r\n\r\n        <div class="col-2 checkbox-wrapper">\r\n\r\n           \r\n            <div class="user">\r\n\r\n                <span class="material-icons">\r\n\r\n                    ${item.rectype === "MSG"\r\n                            ? "notifications"\r\n                            : "task"\r\n                        }\r\n\r\n                </span>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class="col-7">\r\n\r\n            <div>\r\n\r\n                <a href="javascript:void(0)"\r\n\r\n                   class="\r\n                        tasktitle\r\n                        ProcessFlow_New-List-Title\r\n                        Procurement-list\r\n                   "\r\n\r\n                   data-taskid="${this.escapeHtml(taskId || "")}"\r\n                   data-msgtype="${this.escapeHtml(item.msgtype || ''NA'')}"\r\n                   data-taskname="${this.escapeHtml(item.taskname || '''')}"\r\n    data-transid="${this.escapeHtml(item.transid || '''')}"\r\n    data-keyfield="${this.escapeHtml(item.keyfield || '''')}"\r\n    data-keyvalue="${this.escapeHtml(item.keyvalue || '''')}"\r\n    data-recordid="${this.escapeHtml(item.recordid || '''')}"\r\n    data-indexno="${this.escapeHtml(item.indexno || '''')}"\r\n    data-hlink-transid="${this.escapeHtml(item.hlink_transid || '''')}"\r\n    data-hlink-params="${this.escapeHtml(item.hlink_params || '''')}"\r\n    data-processname="${this.escapeHtml(item.processname || '''')}"\r\n                   data-touser="${this.escapeHtml(item.touser || "")}"\r\n                   data-tasktype="${this.escapeHtml(item.tasktype || "")}"\r\n                   data-hlink-params="${this.escapeHtml(item.hlink_params || "")}"\r\n                   data-caption="${this.escapeHtml(title)}"\r\n\r\n                   data-bs-toggle="tooltip"\r\n                   data-bs-placement="bottom"\r\n                   data-bs-title="${this.escapeHtml(title)}" >\r\n\r\n                    ${this.escapeHtml(title)}\r\n\r\n                </a>\r\n\r\n            </div>\r\n\r\n            <div class="taskcontent"\r\n\r\n                 data-bs-toggle="tooltip"\r\n                 data-bs-placement="bottom"\r\n                 data-bs-title="${this.escapeHtml(content)}">\r\n\r\n                ${content}\r\n\r\n            </div>\r\n\r\n            <div class="rowicons"></div>\r\n\r\n        </div>\r\n\r\n        <div class="timespace col-3">\r\n\r\n            <div class="nametime"\r\n\r\n                 data-bs-toggle="tooltip"\r\n                 data-bs-placement="bottom"\r\n                 data-bs-title="${this.escapeHtml(item.fromuser || "")}">\r\n\r\n                ${this.escapeHtml(item.fromuser || " ")}\r\n\r\n            </div>\r\n\r\n            <div class="nametime"\r\n\r\n                 data-bs-toggle="tooltip"\r\n                 data-bs-placement="bottom"\r\n                 data-bs-title="${this.escapeHtml(date)}">\r\n\r\n                ${this.escapeHtml(date)}\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n\r\n</div>\r\n`;\r\n                });\r\n\r\n\r\n\r\n                return html;\r\n            }\r\n\r\n            renderPeople(data) {\r\n\r\n                if (!data.length) {\r\n                    return `<div class="empty-state">No associates found</div>`;\r\n                }\r\n\r\n                return data.map(item => `\r\n\r\n               <div class="people-row"\r\n               data-uname="${item.username}">\r\n\r\n                <div class="people-name">\r\n                ${item.username}\r\n               </div>\r\n\r\n            <span class="material-icons people-scheduler">\r\n                calendar_month\r\n            </span>\r\n\r\n        </div>\r\n\r\n    `).join("");\r\n\r\n            }\r\n            renderGroupCard(item, index) {\r\n                const groupName = this.getGroupName(item);\r\n                const groupKey = groupName;\r\n                const expanded = this.expandedGroupKey === groupKey;\r\n                const children = this.groupChildrenCache[groupKey] || [];\r\n                const loading = !!this.groupChildrenLoading[groupKey];\r\n                const initials = this.getInitials(groupName, "GR");\r\n\r\n                let childHtml = "";\r\n\r\n                if (expanded) {\r\n                    if (loading) {\r\n                        childHtml = `\r\n<div class="group-loading">Loading users...</div>\r\n`;\r\n                    } else if (!children.length) {\r\n                        childHtml = `\r\n<div class="group-empty">No users found</div>\r\n`;\r\n                    } else {\r\n                        childHtml = children\r\n                            .map((child, childIndex) =>\r\n                                this.renderGroupMemberCard(\r\n                                    child,\r\n                                    groupKey,\r\n                                    childIndex\r\n                                )\r\n                            )\r\n                            .join("");\r\n                    }\r\n                }\r\n\r\n                return `\r\n<div class="directory-row group-row"\r\n     role="button"\r\n     tabindex="0"\r\n     data-section="groups"\r\n     data-group-key="${this.escapeHtml(groupKey)}"\r\n     data-index="${index}">\r\n    <div class="directory-avatar directory-avatar-group">\r\n        ${this.escapeHtml(initials)}\r\n    </div>\r\n    <div class="directory-main">\r\n        <div class="directory-name">\r\n            ${this.escapeHtml(groupName)}\r\n        </div>\r\n        <div class="directory-meta">\r\n            User group\r\n        </div>\r\n    </div>\r\n    <span class="material-icons directory-cta">${expanded ? "expand_less" : "expand_more"\r\n                    }</span>\r\n</div>\r\n${childHtml}\r\n`;\r\n            }\r\n\r\n            renderGroupMemberCard(item, groupKey, index) {\r\n                const member = {\r\n                    ...item,\r\n                    __parentGroup: groupKey,\r\n                    usergroups: item.usergroups || groupKey\r\n                };\r\n                const title = this.getDirectoryTitle(\r\n                    member,\r\n                    "groupMembers"\r\n                );\r\n                const metaText = this.getDirectoryMetaText(\r\n                    member,\r\n                    "groupMembers"\r\n                );\r\n                const badges = this.getDirectoryBadges(\r\n                    member,\r\n                    "groupMembers"\r\n                );\r\n                const initials = this.getInitials(title, "PE");\r\n                const selected =\r\n                    this.activeConversationKey ===\r\n                    this.getConversationKey(member, "groupMembers");\r\n\r\n                return `\r\n<div class="directory-row group-member-row ${selected ? "selected" : ""}"\r\n     role="button"\r\n     tabindex="0"\r\n     data-section="groupMembers"\r\n     data-group-key="${this.escapeHtml(groupKey)}"\r\n     data-index="${index}">\r\n    <div class="directory-avatar">\r\n        ${this.escapeHtml(initials)}\r\n    </div>\r\n    <div class="directory-main">\r\n        <div class="directory-name">\r\n            ${this.escapeHtml(title)}\r\n        </div>\r\n        ${metaText\r\n                        ? `<div class="directory-meta">${this.escapeHtml(metaText)}</div>`\r\n                        : ""\r\n                    }\r\n        ${badges.length\r\n                        ? `<div class="directory-badges">${badges\r\n                            .map(\r\n                                badge =>\r\n                                    `<span class="directory-badge">${this.escapeHtml(\r\n                                        badge\r\n                                    )}</span>`\r\n                            )\r\n                            .join("")}</div>`\r\n                        : ""\r\n                    }\r\n    </div>\r\n    <span class="material-icons directory-cta">chevron_right</span>\r\n</div>\r\n`;\r\n            }\r\n\r\n            renderDirectoryCard(item, section, index) {\r\n                const title = this.getDirectoryTitle(item, section);\r\n                const metaText = this.getDirectoryMetaText(item, section);\r\n                const badges = this.getDirectoryBadges(item, section);\r\n                const initials = this.getInitials(title, section === "groups" ? "GR" : "PE");\r\n                const selected =\r\n                    this.activeConversationKey ===\r\n                    this.getConversationKey(item, section);\r\n\r\n                return `\r\n<div class="directory-row ${selected ? "selected" : ""}"\r\n     role="button"\r\n     tabindex="0"\r\n     data-section="${this.escapeHtml(section)}"\r\n     data-index="${index}">\r\n    <div class="directory-avatar ${section === "groups" ? "directory-avatar-group" : ""\r\n                    }">\r\n        ${this.escapeHtml(initials)}\r\n    </div>\r\n    <div class="directory-main">\r\n        <div class="directory-name">\r\n            ${this.escapeHtml(title)}\r\n        </div>\r\n        ${metaText\r\n                        ? `<div class="directory-meta">${this.escapeHtml(metaText)}</div>`\r\n                        : ""\r\n                    }\r\n        ${badges.length\r\n                        ? `<div class="directory-badges">${badges\r\n                            .map(\r\n                                badge =>\r\n                                    `<span class="directory-badge">${this.escapeHtml(\r\n                                        badge\r\n                                    )}</span>`\r\n                            )\r\n                            .join("")}</div>`\r\n                        : ""\r\n                    }\r\n    </div>\r\n    <span class="material-icons directory-cta">chevron_right</span>\r\n</div>\r\n`;\r\n            }\r\n\r\n            async toggleGroupUsers(groupKey) {\r\n                if (!groupKey) return;\r\n\r\n                if (this.expandedGroupKey === groupKey) {\r\n                    this.expandedGroupKey = "";\r\n                    this.buildAccordion();\r\n                    return;\r\n                }\r\n\r\n                this.expandedGroupKey = groupKey;\r\n                this.currentSection = "groups";\r\n\r\n                if (\r\n                    Object.prototype.hasOwnProperty.call(\r\n                        this.groupChildrenCache,\r\n                        groupKey\r\n                    )\r\n                ) {\r\n                    this.buildAccordion();\r\n                    return;\r\n                }\r\n\r\n                this.groupChildrenLoading[groupKey] = true;\r\n                this.buildAccordion();\r\n\r\n                try {\r\n                    const result = await this.fetchDS(\r\n                        "DS_User_Groups",\r\n                        this.searchEl?.value || "",\r\n                        1,\r\n                        {\r\n                            ugroup: groupKey,\r\n                            searchtext: this.searchEl?.value || ""\r\n                        },\r\n                        {\r\n                            includeDefaultSqlParams: false\r\n                        }\r\n                    );\r\n\r\n                    this.groupChildrenCache[groupKey] =\r\n                        (result.rows || []).map(row => ({\r\n                            ...row,\r\n                            __parentGroup: groupKey,\r\n                            usergroups: row.usergroups || groupKey\r\n                        }));\r\n                } finally {\r\n                    this.groupChildrenLoading[groupKey] = false;\r\n                    this.buildAccordion();\r\n                }\r\n            }\r\n\r\n            openGroupMemberChat(groupKey, index) {\r\n                const item =\r\n                    this.groupChildrenCache?.[groupKey]?.[index];\r\n\r\n                if (!item) return;\r\n\r\n                this.ensureRightPanelHosts();\r\n\r\n                const fromSection = this.currentSection;\r\n                const conversationKey = this.getConversationKey(\r\n                    item,\r\n                    "groupMembers"\r\n                );\r\n                const title = this.getDirectoryTitle(\r\n                    item,\r\n                    "groupMembers"\r\n                );\r\n\r\n                this.activeConversationItem = item;\r\n                this.activeConversationSection = "groupMembers";\r\n                this.activeConversationKey = conversationKey;\r\n                this.currentSection = "groups";\r\n                this.expandedGroupKey = groupKey;\r\n\r\n                console.log("[InboxV2] switch: opening group member chat", {\r\n                    from: fromSection,\r\n                    to: "groupMembers",\r\n                    groupKey,\r\n                    index,\r\n                    title,\r\n                    conversationKey,\r\n                    panelState: this.getRightPanelDebugState()\r\n                });\r\n\r\n                this.showDirectoryChatPanel(\r\n                    this.renderChatPanel(\r\n                        item,\r\n                        "groupMembers"\r\n                    )\r\n                );\r\n                this.bindChatComposer();\r\n\r\n                if (this.accordionEl) {\r\n                    this.accordionEl\r\n                        .querySelectorAll(".directory-row.selected")\r\n                        .forEach(row => row.classList.remove("selected"));\r\n\r\n                    const currentRows =\r\n                        this.accordionEl.querySelectorAll(\r\n                            ''.group-member-row[data-section="groupMembers"]''\r\n                        );\r\n\r\n                    currentRows[index]?.classList.add("selected");\r\n                }\r\n\r\n                requestAnimationFrame(() => {\r\n                    const feed =\r\n                        this.getActiveRightPanelRoot()?.querySelector(\r\n                            ".chat-feed"\r\n                        );\r\n                    if (feed) {\r\n                        feed.scrollTop = feed.scrollHeight;\r\n                    }\r\n                });\r\n            }\r\n\r\n            openDirectoryChat(section, index) {\r\n                const item = this.store?.[section]?.[index];\r\n                if (!item) return;\r\n\r\n                this.ensureRightPanelHosts();\r\n\r\n                const fromSection = this.currentSection;\r\n                const conversationKey = this.getConversationKey(item, section);\r\n                const title = this.getDirectoryTitle(item, section);\r\n                const shouldRebuild =\r\n                    fromSection !== section;\r\n                this.activeConversationItem = item;\r\n                this.activeConversationSection = section;\r\n                this.activeConversationKey = conversationKey;\r\n                this.currentSection = section;\r\n\r\n                console.log("[InboxV2] switch: opening directory chat", {\r\n                    from: fromSection,\r\n                    to: section,\r\n                    index,\r\n                    title,\r\n                    conversationKey,\r\n                    shouldRebuild,\r\n                    panelState: this.getRightPanelDebugState()\r\n                });\r\n\r\n                this.showDirectoryChatPanel(\r\n                    this.renderChatPanel(\r\n                        item,\r\n                        section\r\n                    )\r\n                );\r\n                this.bindChatComposer();\r\n                const toUser =\r\n                    item.uname ||\r\n                    item.username ||\r\n                    item.name;\r\n\r\n                this.loadChatHistory(toUser);\r\n                this.startChatPolling();\r\n                if (!shouldRebuild && this.accordionEl) {\r\n                    this.accordionEl\r\n                        .querySelectorAll(".directory-row.selected")\r\n                        .forEach(row => row.classList.remove("selected"));\r\n\r\n                    const currentRow =\r\n                        this.accordionEl.querySelector(\r\n                            `.directory-row[data-section="${section}"][data-index="${index}"]`\r\n                        );\r\n\r\n                    currentRow?.classList.add("selected");\r\n                }\r\n\r\n                if (shouldRebuild) {\r\n                    requestAnimationFrame(() => {\r\n                        this.buildAccordion();\r\n                    });\r\n                }\r\n\r\n                requestAnimationFrame(() => {\r\n                    const feed =\r\n                        this.getActiveRightPanelRoot()?.querySelector(".chat-feed");\r\n                    if (feed) {\r\n                        feed.scrollTop = feed.scrollHeight;\r\n                    }\r\n                });\r\n            }\r\n\r\n            bindAccordionScrollHandoff() {\r\n                if (!this.accordionEl) return;\r\n\r\n                const outer = this.accordionEl;\r\n\r\n                this.accordionEl\r\n                    .querySelectorAll(".v2-scroll-body")\r\n                    .forEach(el => {\r\n                        el.onwheel = event => {\r\n                            const delta = event.deltaY || 0;\r\n                            const atTop = el.scrollTop <= 0;\r\n                            const atBottom =\r\n                                el.scrollTop + el.clientHeight >=\r\n                                el.scrollHeight - 1;\r\n\r\n                            if (\r\n                                (delta < 0 && atTop) ||\r\n                                (delta > 0 && atBottom)\r\n                            ) {\r\n                                outer.scrollTop = Math.max(\r\n                                    0,\r\n                                    outer.scrollTop + delta\r\n                                );\r\n                                event.preventDefault();\r\n                            }\r\n                        };\r\n                    });\r\n            }\r\n\r\n            //             showDefaultRightPanel() {\r\n            //                 if (!this.processCenterPanelEl) return;\r\n\r\n            //                 this.showProcessCenterPanel(\r\n            //                     this.defaultRightPanelHtml || this.renderEmptyRightPanel()\r\n            //                 );\r\n            //             }\r\n\r\n            //             renderEmptyRightPanel() {\r\n            //                 return `\r\n            // <div class="d-flex flex-column text-center h-100 justify-content-center">\r\n            //     <span class="material-icons material-icons-style material-icons-5tx mx-auto text-gray-500">forum</span>\r\n            //     <h3 class="fw-boldest">Nothing is selected</h3>\r\n            // </div>\r\n            // `;\r\n            //             }\r\n\r\n            renderChatPanel(item, section) {\r\n                const title = this.getDirectoryTitle(item, section);\r\n                const metaText = this.getDirectoryMetaText(item, section);\r\n                const badges = this.getDirectoryBadges(item, section);\r\n                const initials = this.getInitials(\r\n                    title,\r\n                    section === "groups" ? "GR" : "PE"\r\n                );\r\n                const threadKey = this.getConversationKey(item, section);\r\n                const messages = this.chatThreads[threadKey] || [];\r\n\r\n                if (!this.chatThreads[threadKey]) {\r\n                    this.chatThreads[threadKey] = [];\r\n                }\r\n\r\n                return `\r\n<div class="chat-shell" data-thread-key="${this.escapeHtml(threadKey)}">\r\n    <div class="chat-shell-header">\r\n        <div class="chat-profile">\r\n            <div class="chat-avatar ${section === "groups" ? "chat-avatar-group" : ""\r\n                    }">${this.escapeHtml(initials)}</div>\r\n            <div class="min-w-0">\r\n                <div class="chat-name">${this.escapeHtml(title)}</div>\r\n                <div class="chat-subline">\r\n                    ${section === "people" && item.reportingto\r\n                        ? `<span class="chat-chip">Reports to ${this.escapeHtml(\r\n                            item.reportingto\r\n                        )}</span>`\r\n                        : ""\r\n                    }\r\n                    ${section === "groups" && item.reportingto\r\n                        ? `<span class="chat-chip">Owner ${this.escapeHtml(\r\n                            item.reportingto\r\n                        )}</span>`\r\n                        : ""\r\n                    }\r\n                    ${badges\r\n                        .slice(0, 3)\r\n                        .map(\r\n                            badge =>\r\n                                `<span class="chat-chip">${this.escapeHtml(\r\n                                    badge\r\n                                )}</span>`\r\n                        )\r\n                        .join("")}\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class="chat-actions" style="display: none;">\r\n        </div>\r\n    </div>\r\n    <div class="chat-feed" id="chatFeed">\r\n        ${messages.length\r\n                        ? messages\r\n                            .map(message => this.renderChatMessage(message, title))\r\n                            .join("")\r\n                        : this.renderChatEmpty(title, metaText, badges, initials, section)\r\n                    }\r\n    </div>\r\n    <form class="chat-composer" id="chatComposerForm" data-thread-key="${this.escapeHtml(\r\n                        threadKey\r\n                    )}">\r\n        <div class="chat-input-wrap">\r\n            <textarea class="chat-input" id="chatInput" rows="1" placeholder="Type a message..."></textarea>\r\n        </div>\r\n        <button class="chat-send" type="submit" aria-label="Send">\r\n            <span class="material-icons material-icons-style material-icons-2">send</span>\r\n        </button>\r\n    </form>\r\n</div>\r\n`;\r\n            }\r\n\r\n            renderChatEmpty(title, metaText, badges, initials, section) {\r\n                return `\r\n<div class="chat-empty">\r\n    <div class="chat-empty-card">\r\n        <div class="chat-avatar ${section === "groups" ? "chat-avatar-group" : ""\r\n                    } mx-auto">${this.escapeHtml(initials)}</div>\r\n        <div class="chat-empty-title">${this.escapeHtml(title)}</div>\r\n        ${metaText\r\n                        ? `<div class="chat-empty-meta">${this.escapeHtml(metaText)}</div>`\r\n                        : ""\r\n                    }\r\n        ${badges.length\r\n                        ? `<div class="chat-subline" >${badges\r\n                            .slice(0, 3)\r\n                            .map(\r\n                                badge =>\r\n                                    `<span class="chat-chip">${this.escapeHtml(\r\n                                        badge\r\n                                    )}</span>`\r\n                            )\r\n                            .join("")}</div>`\r\n                        : ""\r\n                    }\r\n    </div>\r\n</div>\r\n`;\r\n            }\r\n\r\n            renderChatMessage(message, contactName) {\r\n                const isSelf = message.sender === "me";\r\n                const avatar = isSelf\r\n                    ? "ME"\r\n                    : this.getInitials(contactName, "PE");\r\n                const label = isSelf ? "You" : contactName;\r\n                const time = message.time || "";\r\n\r\n                return `\r\n<div class="chat-message ${isSelf ? "self" : ""}">\r\n    <div class="chat-avatar-sm">${this.escapeHtml(avatar)}</div>\r\n    <div class="chat-bubble">\r\n        <div>${this.escapeHtml(message.text || "")}</div>\r\n        <div class="chat-message-meta">\r\n            <span>${this.escapeHtml(label)}</span>\r\n            <span>${this.escapeHtml(time)}</span>\r\n        </div>\r\n    </div>\r\n</div>\r\n`;\r\n            }\r\n\r\n            bindChatComposer() {\r\n                const panelRoot = this.getActiveRightPanelRoot();\r\n                const form =\r\n                    panelRoot?.querySelector("#chatComposerForm");\r\n                const input =\r\n                    panelRoot?.querySelector("#chatInput");\r\n                const feed =\r\n                    panelRoot?.querySelector("#chatFeed");\r\n\r\n                if (!form || !input || !feed) return;\r\n\r\n                form.onsubmit = event => {\r\n                    event.preventDefault();\r\n\r\n                    const text = input.value.trim();\r\n                    if (!text) return;\r\n\r\n                    const threadKey = form.dataset.threadKey || "";\r\n                    if (!this.chatThreads[threadKey]) {\r\n                        this.chatThreads[threadKey] = [];\r\n                    }\r\n\r\n                    const toUser = threadKey.split("|")[1] || "";\r\n                    const now = new Date();\r\n                    const eventDateTime =\r\n                        now.getFullYear().toString() +\r\n                        String(now.getMonth() + 1).padStart(2, "0") +\r\n                        String(now.getDate()).padStart(2, "0") +\r\n                        String(now.getHours()).padStart(2, "0") +\r\n                        String(now.getMinutes()).padStart(2, "0") +\r\n                        String(now.getSeconds()).padStart(2, "0") +\r\n                        String(now.getMilliseconds()).padStart(3, "0");\r\n\r\n                    parent.AxSetValue("a__sm", "fromuser", "1", "0", parent.mainUserName);\r\n                    parent.AxSetValue("a__sm", "touser_ui", "1", "0", toUser);\r\n                    parent.AxSetValue("a__sm", "msgtitle", "1", "0", text);\r\n                    parent.AxSetValue("a__sm", "message", "1", "0", text);\r\n                    parent.AxSetValue("a__sm", "eventdatetime", "1", "0", eventDateTime);\r\n\r\n                    const resp = parent.AxSubmitData("a__sm", "0");\r\n\r\n                    this.chatThreads[threadKey].push({\r\n                        sender: "me",\r\n                        text,\r\n                        time: this.formatTime(new Date())\r\n                    });\r\n\r\n                    this.showDirectoryChatPanel(\r\n                        this.renderChatPanel(\r\n                            this.activeConversationItem,\r\n                            this.activeConversationSection\r\n                        )\r\n                    );\r\n                    this.bindChatComposer();\r\n\r\n                    requestAnimationFrame(() => {\r\n                        const nextFeed =\r\n                            this.getActiveRightPanelRoot()?.querySelector("#chatFeed");\r\n                        if (nextFeed) {\r\n                            nextFeed.scrollTop = nextFeed.scrollHeight;\r\n                        }\r\n                    });\r\n                };\r\n\r\n                input.onkeydown = event => {\r\n                    if (event.key === "Enter" && !event.shiftKey) {\r\n                        event.preventDefault();\r\n                        form.requestSubmit\r\n                            ? form.requestSubmit()\r\n                            : form.dispatchEvent(\r\n                                new Event("submit", {\r\n                                    bubbles: true,\r\n                                    cancelable: true\r\n                                })\r\n                            );\r\n                        const selectedRow =\r\n                            document.querySelector(".directory-row.selected");\r\n\r\n                        if (selectedRow) {\r\n\r\n                            const toUser =\r\n                                selectedRow.querySelector(".directory-name")\r\n                                    ?.textContent?.trim();\r\n\r\n                            this.loadChatHistory(toUser);\r\n                            this.startChatPolling();\r\n                        }\r\n                    }\r\n                };\r\n\r\n                requestAnimationFrame(() => {\r\n                    input.focus();\r\n                });\r\n            }\r\n\r\n            getGroupName(item) {\r\n                return (\r\n                    item.usergroup ||\r\n                    item.groupname ||\r\n                    item.displaytitle ||\r\n                    item.name ||\r\n                    item.username ||\r\n                    item.title ||\r\n                    "Untitled"\r\n                );\r\n            }\r\n\r\n            getDirectoryTitle(item, section) {\r\n                const candidates =\r\n                    section === "groups"\r\n                        ? [\r\n                            item.usergroup,\r\n                            item.groupname,\r\n                            item.displaytitle,\r\n                            item.name,\r\n                            item.username,\r\n                            item.title\r\n                        ]\r\n                        : [\r\n                            item.username,\r\n                            item.user,\r\n                            item.userid,\r\n                            item.member,\r\n                            item.membername,\r\n                            item.displaytitle,\r\n                            item.name,\r\n                            item.fullname,\r\n                            item.email,\r\n                            item.taskname,\r\n                            item.usergroup\r\n                        ];\r\n\r\n                return candidates.find(value => value) || "Untitled";\r\n            }\r\n\r\n            getDirectoryMetaText(item, section) {\r\n                const meta = [];\r\n\r\n                if (section === "people" || section === "groupMembers") {\r\n                    if (item.reportingto) {\r\n                        meta.push(`Reports to ${item.reportingto}`);\r\n                    }\r\n                    if (section === "groupMembers" && item.__parentGroup) {\r\n                        meta.push(`Group ${item.__parentGroup}`);\r\n                    }\r\n                    const groups =\r\n                        section === "groupMembers"\r\n                            ? []\r\n                            : this.splitList(item.usergroups);\r\n                    if (groups.length) {\r\n                        meta.push(\r\n                            `${groups.length} group${groups.length === 1 ? "" : "s"\r\n                            }`\r\n                        );\r\n                    }\r\n                } else if (section === "groups") {\r\n                    const owner =\r\n                        item.reportingto ||\r\n                        item.owner ||\r\n                        item.createdby ||\r\n                        item.lead ||\r\n                        item.manager;\r\n                    if (owner) {\r\n                        meta.push(`Owner ${owner}`);\r\n                    }\r\n                    const members =\r\n                        item.members ||\r\n                        item.membercount ||\r\n                        item.totalmembers ||\r\n                        item.usercount;\r\n                    if (members) {\r\n                        const memberCount = Array.isArray(members)\r\n                            ? members.length\r\n                            : Number(members);\r\n                        if (!Number.isNaN(memberCount)) {\r\n                            meta.push(\r\n                                `${memberCount} member${memberCount === 1 ? "" : "s"\r\n                                }`\r\n                            );\r\n                        } else {\r\n                            meta.push(String(members));\r\n                        }\r\n                    }\r\n                }\r\n\r\n                return meta.join(" | ");\r\n            }\r\n\r\n            getDirectoryBadges(item, section) {\r\n                const values =\r\n                    section === "groups"\r\n                        ? this.splitList(item.usergroups || item.members)\r\n                        : this.splitList(\r\n                            item.usergroups || item.__parentGroup\r\n                        );\r\n\r\n                return values.slice(0, 4);\r\n            }\r\n\r\n            getConversationKey(item, section) {\r\n                return [\r\n                    section,\r\n                    item.username,\r\n                    item.user,\r\n                    item.userid,\r\n                    item.member,\r\n                    item.membername,\r\n                    item.email,\r\n                    item.usergroup,\r\n                    item.groupname,\r\n                    item.displaytitle,\r\n                    item.name,\r\n                    item.taskid,\r\n                    item.id,\r\n                    item.__parentGroup,\r\n                    item.reportingto\r\n                ]\r\n                    .filter(Boolean)\r\n                    .join("|")\r\n                    .toLowerCase();\r\n            }\r\n\r\n            splitList(value) {\r\n                if (!value) return [];\r\n                if (Array.isArray(value)) {\r\n                    return value.map(item => String(item).trim()).filter(Boolean);\r\n                }\r\n\r\n                return String(value)\r\n                    .split(/[;,|]/)\r\n                    .map(item => item.trim())\r\n                    .filter(Boolean);\r\n            }\r\n\r\n            getInitials(label, fallback = "PE") {\r\n                const parts = String(label || "")\r\n                    .trim()\r\n                    .split(/\\s+/)\r\n                    .filter(Boolean);\r\n\r\n                if (!parts.length) {\r\n                    return fallback;\r\n                }\r\n\r\n                if (parts.length === 1) {\r\n                    return parts[0].slice(0, 2).toUpperCase();\r\n                }\r\n\r\n                return parts\r\n                    .slice(0, 2)\r\n                    .map(word => word.charAt(0))\r\n                    .join("")\r\n                    .toUpperCase();\r\n            }\r\n\r\n            escapeHtml(value) {\r\n                const node = document.createElement("div");\r\n                node.textContent = String(value ?? "");\r\n                return node.innerHTML;\r\n            }\r\n\r\n            formatTime(value) {\r\n                const date = value instanceof Date ? value : new Date(value);\r\n                if (Number.isNaN(date.getTime())) {\r\n                    return "";\r\n                }\r\n\r\n                return date.toLocaleTimeString([], {\r\n                    hour: "2-digit",\r\n                    minute: "2-digit"\r\n                });\r\n            }\r\n\r\n            bindScrollPagination() {\r\n                document\r\n                    .querySelectorAll(".v2-scroll-body")\r\n                    .forEach(el => {\r\n                        el.onscroll = async () => {\r\n                            const section = el.dataset.section;\r\n\r\n                            if (this.loading[section]) return;\r\n\r\n                            // Threshold distance from bottom to trigger (in pixels)\r\n                            const threshold = 50;\r\n                            const reachedBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - threshold;\r\n\r\n                            if (reachedBottom) {\r\n                                if (this.revealNextClientRows(section, el)) {\r\n                                    return;\r\n                                }\r\n\r\n                                if (!this.hasMore[section]) return;\r\n\r\n                                this.pagination[section]++;\r\n\r\n                                console.log("Loading page", this.pagination[section], "for section", section);\r\n\r\n                                // Execution flow transfers to custom chunk-appending inside loadSection\r\n                                await this.loadSection(section);\r\n                            }\r\n                        };\r\n                    });\r\n            }\r\n            bindPagination() {\r\n\r\n                document\r\n                    .querySelectorAll(".page-btn")\r\n                    .forEach(btn => {\r\n\r\n                        btn.onclick = async () => {\r\n\r\n                            const section =\r\n                                btn.dataset.section;\r\n\r\n                            const type =\r\n                                btn.dataset.type;\r\n\r\n                            if (type === "next") {\r\n\r\n                                this.pagination[section]++;\r\n\r\n                            } else if (\r\n                                type === "prev" &&\r\n                                this.pagination[section] > 1\r\n                            ) {\r\n\r\n                                this.pagination[section]--;\r\n                            }\r\n\r\n                            await this.loadSection(section);\r\n\r\n                            this.buildAccordion();\r\n                        };\r\n                    });\r\n            }\r\n            async loadSection(sectionKey) {\r\n                if (this.loading[sectionKey]) return;\r\n                if (!this.hasMore[sectionKey]) return;\r\n\r\n                const section = this.sections.find(x => x.key === sectionKey);\r\n                if (!section?.ds) return;\r\n\r\n                this.loading[sectionKey] = true;\r\n\r\n                try {\r\n                    const pageNo = this.pagination[sectionKey] || 1;\r\n                    const result = await this.fetchDS(\r\n                        section.ds,\r\n                        this.searchEl?.value || "",\r\n                        pageNo\r\n                    );\r\n\r\n                    const rows = result.rows || [];\r\n                    const totalCount = result.totalCount ?? rows.length;\r\n\r\n                    this.visibleCount[sectionKey] = totalCount;\r\n\r\n                    if (pageNo === 1) {\r\n                        if (this.isClientPagedSection(sectionKey)) {\r\n                            this.clientRenderLimit[sectionKey] =\r\n                                this.clientChunkSize;\r\n                        }\r\n\r\n                        this.store[sectionKey] = rows;\r\n                        this.buildAccordion();\r\n                    } else {\r\n                        const appendStart =\r\n                            this.store[sectionKey]?.length || 0;\r\n\r\n                        this.store[sectionKey] = [\r\n                            ...this.store[sectionKey],\r\n                            ...rows\r\n                        ];\r\n\r\n                        if (this.isClientPagedSection(sectionKey)) {\r\n                            this.clientRenderLimit[sectionKey] =\r\n                                this.store[sectionKey].length;\r\n                        }\r\n\r\n                        const scrollBody = this.accordionEl?.querySelector(\r\n                            `.v2-scroll-body[data-section="${sectionKey}"]`\r\n                        );\r\n\r\n                        if (scrollBody) {\r\n                            scrollBody.insertAdjacentHTML(\r\n                                "beforeend",\r\n                                this.renderCards(\r\n                                    rows,\r\n                                    sectionKey,\r\n                                    appendStart\r\n                                )\r\n                            );\r\n                        }\r\n\r\n                        const countBadge = this.accordionEl?.querySelector(\r\n                            `.v2-accordion-header[data-section="${sectionKey}"] .inbox-count`\r\n                        );\r\n\r\n                        if (countBadge) {\r\n                            countBadge.innerText = `${this.getRenderedSectionCount(\r\n                                sectionKey\r\n                            )}/${totalCount}`;\r\n                        }\r\n\r\n                        this.bindDirectoryAndTaskClicks();\r\n                        this.bindAccordionScrollHandoff();\r\n                    }\r\n\r\n                    this.hasMore[sectionKey] =\r\n                        this.store[sectionKey].length < totalCount &&\r\n                        rows.length > 0;\r\n                } finally {\r\n                    this.loading[sectionKey] = false;\r\n                }\r\n            }\r\n            debounce(callback, delay) {\r\n\r\n                let timer;\r\n\r\n                return (...args) => {\r\n\r\n                    clearTimeout(timer);\r\n\r\n                    timer = setTimeout(() => {\r\n\r\n                        callback.apply(this, args);\r\n\r\n                    }, delay);\r\n                };\r\n            }\r\n\r\n            async loadChatHistory(toUser) {\r\n\r\n                try {\r\n\r\n                    const result = await this.fetchDS(\r\n                        "ds_chathistory",\r\n                        "",\r\n                        1,\r\n                        {\r\n                            uname: parent.mainUserName,\r\n                            touser: toUser\r\n                        }\r\n                    );\r\n\r\n                    const rows = result.rows || [];\r\n\r\n                    rows.sort((a, b) =>\r\n                        (a.eventdatetime || "").localeCompare(\r\n                            b.eventdatetime || ""\r\n                        )\r\n                    );\r\n\r\n                    this.renderChatHistory(rows, toUser);\r\n\r\n                } catch (ex) {\r\n                    console.error(ex);\r\n                }\r\n            }\r\n\r\n            startChatPolling() {\r\n\r\n                clearInterval(this.chatPoller);\r\n\r\n                this.chatPoller = setInterval(() => {\r\n\r\n                    if (!this.activeConversationItem) return;\r\n\r\n                    const toUser =\r\n                        this.activeConversationItem.uname ||\r\n                        this.activeConversationItem.username ||\r\n                        this.activeConversationItem.name;\r\n\r\n                    this.loadChatHistory(toUser);\r\n                    this.startChatPolling();\r\n\r\n                }, 2000); // every 3 sec\r\n            }\r\n            //         renderChatHistory(messages, toUser) {\r\n\r\n            //             const currentUser =\r\n            //                 (parent.mainUserName || "").toLowerCase();\r\n\r\n            //             const html = messages.map(msg => {\r\n\r\n            //                 const sender =\r\n            //                     (msg.fromuser || "").toLowerCase();\r\n\r\n            //                 const isMine =\r\n            //                     sender === currentUser;\r\n\r\n            //                 return `\r\n            //         <div class="chat-message ${isMine ? "self" : ""}">\r\n\r\n            //             <div class="chat-avatar-sm">\r\n            //                 ${(msg.fromuser || "?")\r\n            //                         .substring(0, 2)\r\n            //                         .toUpperCase()}\r\n            //             </div>\r\n\r\n            //             <div>\r\n            //                 <div class="chat-bubble">\r\n            //                     ${msg.message || ""}\r\n            //                 </div>\r\n\r\n            //                 <div class="chat-message-meta">\r\n            //                     <span>\r\n            //                         ${this.formatChatTime(\r\n            //                             msg.eventdatetime\r\n            //                         )}\r\n            //                     </span>\r\n            //                 </div>\r\n            //             </div>\r\n\r\n            //         </div>\r\n            //     `;\r\n            //             }).join("");\r\n\r\n            //             const panel = `\r\n            //     <div class="chat-shell">\r\n\r\n            //         <div class="chat-shell-header">\r\n            //             <div class="chat-profile">\r\n            //                 <div class="chat-avatar">\r\n            //                     ${toUser.substring(0, 2).toUpperCase()}\r\n            //                 </div>\r\n\r\n            //                 <div>\r\n            //                     <div class="chat-name">\r\n            //                         ${toUser}\r\n            //                     </div>\r\n            //                 </div>\r\n            //             </div>\r\n            //         </div>\r\n\r\n            //         <div class="chat-feed" id="chatFeed">\r\n            //             ${html}\r\n            //         </div>\r\n\r\n            //     </div>\r\n            // `;\r\n\r\n            //             // this.showDirectoryChatPanel(panel);\r\n\r\n            //             setTimeout(() => {\r\n\r\n            //                 const feed =\r\n            //                     document.getElementById("chatFeed");\r\n\r\n            //                 if (feed) {\r\n            //                     feed.scrollTop =\r\n            //                         feed.scrollHeight;\r\n            //                 }\r\n\r\n            //             }, 100);\r\n            //         }\r\n\r\n            renderChatHistory(messages, toUser) {\r\n\r\n                // No history\r\n                if (!messages || messages.length === 0) {\r\n\r\n                    this.showDirectoryChatPanel(\r\n                        this.renderChatPanel(\r\n                            this.activeConversationItem,\r\n                            this.activeConversationSection\r\n                        )\r\n                    );\r\n\r\n                    this.bindChatComposer();\r\n                    return;\r\n                }\r\n\r\n                const currentUser =\r\n                    (parent.mainUserName || "").toLowerCase();\r\n\r\n                const html = messages.map(msg => {\r\n\r\n                    const sender =\r\n                        (msg.fromuser || "").toLowerCase();\r\n\r\n                    const isMine =\r\n                        sender === currentUser;\r\n\r\n                    return `\r\n            <div class="chat-message ${isMine ? "self" : ""}">\r\n                \r\n                <div class="chat-avatar-sm">\r\n                    ${(msg.fromuser || "?")\r\n                            .substring(0, 2)\r\n                            .toUpperCase()}\r\n                </div>\r\n\r\n                <div>\r\n                    <div class="chat-bubble">\r\n                        ${msg.message || ""}\r\n                    </div>\r\n\r\n                    <div class="chat-message-meta">\r\n                        <span>\r\n                            ${this.formatChatTime(\r\n                                msg.eventdatetime\r\n                            )}\r\n                        </span>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        `;\r\n                }).join("");\r\n\r\n                // Update only the feed\r\n                const feed = document.getElementById("chatFeed");\r\n\r\n                if (feed) {\r\n                    feed.innerHTML = html;\r\n                    feed.scrollTop = feed.scrollHeight;\r\n                }\r\n            }\r\n            formatChatTime(ts) {\r\n\r\n                if (!ts) return "";\r\n\r\n                const year = ts.substr(0, 4);\r\n                const month = ts.substr(4, 2);\r\n                const day = ts.substr(6, 2);\r\n\r\n                const hour = ts.substr(8, 2);\r\n                const min = ts.substr(10, 2);\r\n\r\n                const dt = new Date(\r\n                    `${year}-${month}-${day}T${hour}:${min}:00`\r\n                );\r\n\r\n                return dt.toLocaleString("en-IN", {\r\n                    day: "2-digit",\r\n                    month: "short",\r\n                    hour: "2-digit",\r\n                    minute: "2-digit"\r\n                });\r\n            }\r\n        }\r\n\r\n        window.addEventListener(\r\n            "DOMContentLoaded",\r\n            () => {\r\n\r\n                window.inboxV2 =\r\n                    new InboxV2();\r\n            }\r\n        );\r\n\r\n        function getTaskId(item) {\r\n            const pattern = /\\b(?:TSK|TASK|TKT)-\\d+\\b|\\bTask ID-\\d+\\b/i;\r\n            // 1️⃣ First try hlink_params\r\n            if (item.hlink_params) {\r\n                const match = item.hlink_params.match(pattern);\r\n                if (match) return match[0];\r\n            }\r\n            // 2️⃣ Try displaytitle\r\n            if (item.displaytitle) {\r\n                const match = item.displaytitle.match(pattern);\r\n                if (match) return match[0];\r\n            }\r\n            // 3️⃣ Try displaycontent\r\n            if (item.displaycontent) {\r\n                const match = item.displaycontent.match(pattern);\r\n                if (match) return match[0];\r\n            }\r\n            if (item.taskid) {\r\n                return item.taskid\r\n            }\r\n            return null;\r\n        }\r\n\r\n\r\n    </script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\t<script type="text/javascript" src="Js/taskslst_inbox_1784889372733.js?v=1784889451540"></script>\r\n\t<script type="text/javascript" src="Js/AxProcessFlow_V3_1784889372733.js?v=1784889451541"></script>\r\n</body></html>\r\n'),
(1014010000000, 1012660000000, E'<html lang="en"><head>\r\n    <meta charset="UTF-8">\r\n    <meta name="viewport" content="width=device-width, initial-scale=1">\r\n\r\n    <title>AXI UI</title>\r\n\r\n    <link rel="stylesheet" href="../../UI/axpertUI/style.bundle.css">\r\n    <link rel="stylesheet" href="../../UI/axpertUI/plugins.bundle.css">\r\n    <link rel="stylesheet" href="../../ThirdParty/jquery-confirm-master/jquery-confirm.min.css">\r\n    <link rel="stylesheet" href="css/Package-Installed.css?v=1">\r\n\r\n    <!-- Default Style Start -->\r\n    <!-- link href="/axpert/UI/axpertUI/ltrBundleCss?v=RK7QA8qnRcrYBOQMuCCVxXmltix7NcOjbRbD5Debq6E1" rel="stylesheet" -->\r\n    <script src="../../Js/thirdparty/jquery/3.1.1/jquery.min.js"></script>\r\n    <script src="../../Js/noConflict.min.js?v=5" type="text/javascript"></script>\r\n    <script src="../../Js/thirdparty/bootstrap/3.3.6/bootstrap.min.js"></script>\r\n\r\n    <!-- Default Style End -->\r\n\r\n    <!-- Bootstrap -->\r\n\r\n    <style>\r\n        .INB-cards-wrap {\r\n            overflow: auto;\r\n        }\r\n    </style>\r\n\t\r\n\t\r\n\t<link type="text/css" rel="stylesheet" href="Css/AxpertInbox_1784802774665.css?v=1784889099598">\r\n\t\r\n\t<link type="text/css" rel="stylesheet" href="Css/Package-Installed_1784802774665.css?v=1784896160088">\r\n</head>\r\n\r\n<body>\r\n\r\n    <div class="Axi_Installer_Wrapper">\r\n        <div class="circle1"></div>\r\n        <div class="circle2"></div>\r\n        <div class="circle3"></div>\r\n        <div class="star"></div>\r\n\r\n        <div class="Quick-Links">\r\n\r\n\r\n            <nav class="nav nav-pills flex-column  flex-sm-row ">\r\n                <a data-target="#Inbox" class="nav-link active">Inbox</a>\r\n                <a data-target="#Masters" class="nav-link ">Masters</a>\r\n                <a data-target="#ProcureToPay" class="nav-link ">Procure to pay</a>\r\n                <a data-target="#OrderToCash" class="  nav-link">Order to cash</a>\r\n                <a data-target="#InventoryControl" class="  nav-link">Inventory Control</a>\r\n                <a data-target="#FinancialAccounting" class="  nav-link">Financial accounting</a>\r\n                <a data-target="#AccountReceivables" class="  nav-link">Account receivables</a>\r\n                <a data-target="#AccountPayable" class="  nav-link">Account Payable</a>\r\n            </nav>\r\n\r\n\r\n\r\n        </div>\r\n        <div class="col-lg-12">\r\n\r\n            <div class="card-ui Module-Wrapper ">\r\n                <div class="Module-Parent ">\r\n                    <div class="module-header" id="Inbox">\r\n                        <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">mail</span>\r\n                        </div>\r\n                        <div class="title">Inbox</div>\r\n                    </div>\r\n\r\n\r\n\r\n                    <div class="desc">There are 10+ new messages in your inbox.</div>\r\n                    <div class="INB-cards-wrap" id="InboxCards">\r\n\r\n                        <!-- <div class="Aggregation-Item-wrap">\r\n                            <a  class="Aggregation-item">\r\n                                <div class="Aggregation-icon">\r\n                                    <span\r\n                                        class="material-icons material-icons-style material-icons-2">mark_email_unreadt</span>\r\n                                </div>\r\n                                <div class="Aggregation-content">\r\n                                    <h6 class="subtitle">PO</h6>\r\n                                    <h4 class="value">10</h4>\r\n\r\n                                </div>\r\n\r\n                            </a>\r\n                        </div>\r\n                        <div class="Aggregation-Item-wrap">\r\n                            <a  class="Aggregation-item">\r\n                                <div class="Aggregation-icon">\r\n                                    <span\r\n                                        class="material-icons material-icons-style material-icons-2">mark_email_unreadt</span>\r\n                                </div>\r\n                                <div class="Aggregation-content">\r\n                                    <h6 class="subtitle">Sales orders</h6>\r\n                                    <h4 class="value">10</h4>\r\n\r\n                                </div>\r\n\r\n                            </a>\r\n                        </div>\r\n                        <div class="Aggregation-Item-wrap">\r\n                            <a  class="Aggregation-item">\r\n                                <div class="Aggregation-icon">\r\n                                    <span\r\n                                        class="material-icons material-icons-style material-icons-2">mark_email_unreadt</span>\r\n                                </div>\r\n                                <div class="Aggregation-content">\r\n                                    <h6 class="subtitle">Payments</h6>\r\n                                    <h4 class="value">10</h4>\r\n\r\n                                </div>\r\n\r\n                            </a>\r\n                        </div>\r\n                        <div class="Aggregation-Item-wrap">\r\n                            <a  class="Aggregation-item">\r\n                                <div class="Aggregation-icon">\r\n                                    <span\r\n                                        class="material-icons material-icons-style material-icons-2">mark_email_unreadt</span>\r\n                                </div>\r\n                                <div class="Aggregation-content">\r\n                                    <h6 class="subtitle">Receipts</h6>\r\n                                    <h4 class="value">10</h4>\r\n\r\n                                </div>\r\n\r\n                            </a>\r\n                        </div>\r\n                        <div class="Aggregation-Item-wrap">\r\n                            <a  class="Aggregation-item">\r\n                                <div class="Aggregation-icon">\r\n                                    <span\r\n                                        class="material-icons material-icons-style material-icons-2">mark_email_unreadt</span>\r\n                                </div>\r\n                                <div class="Aggregation-content">\r\n                                    <h6 class="subtitle">Renewals</h6>\r\n                                    <h4 class="value">10</h4>\r\n\r\n                                </div>\r\n\r\n                            </a>\r\n                        </div>\r\n                        <div class="Aggregation-Item-wrap">\r\n                            <a  class="Aggregation-item">\r\n                                <div class="Aggregation-icon">\r\n                                    <span\r\n                                        class="material-icons material-icons-style material-icons-2">mark_email_unreadt</span>\r\n                                </div>\r\n                                <div class="Aggregation-content">\r\n                                    <h6 class="subtitle">Maintenance activities</h6>\r\n                                    <h4 class="value">10</h4>\r\n\r\n                                </div>\r\n\r\n                            </a>\r\n                        </div>\r\n\r\n                        <div class="Aggregation-Item-wrap">\r\n                            <a  class="Aggregation-item">\r\n                                <div class="Aggregation-icon">\r\n                                    <span\r\n                                        class="material-icons material-icons-style material-icons-2">mark_email_unreadt</span>\r\n                                </div>\r\n                                <div class="Aggregation-content">\r\n                                    <h6 class="subtitle">Tasks </h6>\r\n                                    <h4 class="value">10</h4>\r\n\r\n                                </div>\r\n\r\n                            </a>\r\n                        </div> -->\r\n\r\n                    </div>\r\n                </div>\r\n\r\n\r\n            </div>\r\n\r\n            <div class="card-ui Module-Wrapper ">\r\n                <div class="Module-Parent ">\r\n                    <div class="module-header" id="Masters">\r\n                        <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">credit_card_clock</span>\r\n                        </div>\r\n                        <div class="title">Masters</div>\r\n                    </div>\r\n\r\n                    <div class="desc">Axi provides a set of common masters that are used across modules. Users can\r\n                        upload master data from excel sheets to respective forms using the upload command during data\r\n                        migration. </div>\r\n\r\n                </div>\r\n\r\n\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/location.png">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="bran">Locations</div>\r\n                            </div>\r\n                            <div class="desc">\r\n\r\n\r\n                                Axi support multi-locations. Locations may be configured to accept only finance\r\n                                transactions, only inventory transactions or both. When a location is configured to\r\n                                maintain inventory, 2 sub locations are created by default by Axi Main store and\r\n                                Rejections store.\r\n\r\n All rejections are automatically moved to the rejections\r\n                                store. Axi provides the capability of creating one or more sub locations within a\r\n                                location. These sub locations may be used as different stores for storing items that are\r\n                                in different stages of production till it is shipped.\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">Create </button>\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="inloc">Create sub\r\n                                    location</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="inloc">View sub\r\n                                    locations</button>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n\r\n\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/items.png">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="prodm">Items</div>\r\n                            </div>\r\n                            <div class="desc">Axi ERP can manage large number of items. Items may comprise of raw\r\n                                materials,\r\n                                semi-finished goods, finished goods & consumables. An item is categorized using the item\r\n                                category, item\r\n                                sub category & brand. \r\n\r\n                                Items can be bought in a unit of measure, stored in a different unit of measure and sold\r\n                                in a different\r\n                                unit of measure. The inventory can be maintained in primary and secondary units of\r\n                                measure too. This is\r\n                                critical in many businesses.\r\n\r\n                                \r\n\r\n\r\n                                Each item category and sub category may be associated with a HSN code, purchase account,\r\n                                sales account &\r\n                                stock account. Items that belong to a sub category and category are associated with\r\n                                corresponding HSN\r\n                                code and GL accounts. The mapping with HSN code or an account can be done at item\r\n                                category, sub category\r\n                                or at item level. The mapping done at item level will override the mapping done at sub\r\n                                category level &\r\n                                category level. Similarly mapping done at sub category level will override the mapping\r\n                                done at category\r\n                                level.\r\n\r\n                                \r\n\r\n\r\n\r\n                                Use <a>Taxes</a> option to setup the list of taxes applicable.\r\n                                \r\n\r\n\r\n                                Use <a>HSN/SAC</a> code option to view/create HSN codes. Every HSN code is associated\r\n                                with the\r\n                                applicable tax code.\r\n\r\n                                \r\n\r\n\r\n                                HSN code may be assigned to an item or its sub category or its category. The tax\r\n                                associated with the\r\n                                assigned HSN code will be used in all transactions.\r\n                                \r\n\r\n\r\n                                The purchase account, sales account and stock account may be assigned to an item or its\r\n                                sub category or\r\n                                its category. The transactions are posted to the assigned account when invoices,\r\n                                purchases and other\r\n                                transactions are made for an item.\r\n                            </div>\r\n\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n                    <div class="Action-Btns">\r\n                        <button class="btn-pill mt-auto align-self-end">View</button>\r\n                        <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                    </div>\r\n                    <div class="Action-Btns">\r\n                        <div class="AB-Links">Links</div>\r\n                        <ul>\r\n                            <li><a data-transid="taxmt">Taxes</a></li>\r\n                            <li><a data-transid="hssc">HSN/SAC code</a></li>\r\n                            <li><a data-transid="hsnta">HSN item mapping</a></li>\r\n                            <li><a data-transid="itmac">Item account mapping</a></li>\r\n                            <li><a data-transid="stkstwov" data-transtype="iview">Stock statement</a></li>\r\n                            <li><a data-transid="" data-transtype="ads">Product wise Profitability Data</a></li>\r\n                        </ul>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n\r\n\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/suppliers.png">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="gsupp">Suppliers</div>\r\n                            </div>\r\n                            <div class="desc">All information about suppliers and the items supplied by them are\r\n                                maintained by Axi ERP. All data about the legal entity, communication addresses, contact\r\n                                people transaction currency &amp; statutory data about suppliers are maintained. A\r\n                                corresponding sub ledger account is created in financial system to auto post into GL\r\n                                &amp; AP. Users can store multiple addresses for a supplier in the address book.\r\n\r\n\r\n                                \r\n\r\n\r\n                                Use the Open supplier bills option to enter pending bills from an external system\r\n                                during data migration. Use the data upload option to upload into this form from an excel\r\n                                sheet.\r\n\r\n\r\n\r\n\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">Create </button>\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n\r\n                            </div>\r\n\r\n\r\n                        </div>\r\n\r\n                    </div>\r\n\r\n\r\n\r\n\r\n                    <div class="Action-Btns">\r\n                        <div class="AB-Links">Links</div>\r\n                        <ul>\r\n                            <li><a data-transid="surma">Supplier item rates</a></li>\r\n                            <li><a data-transid="atpaysum" data-transtype="iview">Accounts payable summary</a>\r\n                            </li>\r\n                            <li><a data-transid="arapagei" data-transtype="iview">Accounts payable billwise</a>\r\n                            </li>\r\n                            <li><a data-transid="cuabo">Address book</a></li>\r\n                            <li><a data-transid="aparo">Open supplier bills</a></li>\r\n                        </ul>\r\n                    </div>\r\n\r\n\r\n                </div>\r\n\r\n\r\n\r\n\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/customers.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="gcust">Customers</div>\r\n                            </div>\r\n                            <div class="desc">\r\n                                All information about customers are maintained by Axi ERP. All data about the legal\r\n                                entity, communication addresses, contact people, transaction currency &amp; statutory\r\n                                data about customers are maintained. A corresponding sub ledger account is created in\r\n                                financial system to auto post into GL &amp; AR. The transaction currency for a customer\r\n                                can be set. In this case all transactions entered for that customer will be done in the\r\n                                selected currency. The books of accounts will be maintained in the company currency.\r\n\r\n\r\n                                \r\n\r\n\r\n                                Use the Open customer invoices option to enter pending invoices from an external\r\n                                system during data migration. Use the data upload option to upload open invoices into\r\n                                this form.\r\n                                \r\n\r\n\r\n                                Use address book option to add more addresses to a customer.\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">Create </button>\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n\r\n                            </div>\r\n                        </div>\r\n\r\n\r\n\r\n\r\n                    </div>\r\n\r\n                    <div class="Action-Btns">\r\n                        <div class="AB-Links">Links</div>\r\n                        <ul>\r\n                            <li><a data-transid="" data-transtype="ads">Customer wise Profitability Data</a>\r\n                            </li>\r\n                            <li><a data-transid="atrevsum" data-transtype="iview">Accounts receivable\r\n                                    summary</a></li>\r\n                            <li><a data-transid="arapagei" data-transtype="iview">Accounts receivable bill\r\n                                    wisee</a></li>\r\n                            <li><a data-transid="arapo">Open customer invoices</a></li>\r\n                            <li><a data-transid="invce">Sales Invoicess</a></li>\r\n                            <li><a data-transid="crrec">Customer receipts</a></li>\r\n                        </ul>\r\n\r\n\r\n                    </div>\r\n\r\n                </div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n            </div>\r\n\r\n            <div class="card-ui Module-Wrapper ">\r\n                <div class="Module-Parent ">\r\n                    <div class="module-header" id="ProcureToPay">\r\n                        <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">credit_card_clock</span>\r\n                        </div>\r\n                        <div class="title">Procure To Pay</div>\r\n                    </div>\r\n\r\n                    <div class="desc">Procure-to-Pay process is how an organization purchases the raw materials and\r\n                        services that are needed for their enterrrise. It starts from getting requests for procurement\r\n                        till materials are received and suppliers are paid. </div>\r\n\r\n                </div>\r\n\r\n\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/purchase-request.png">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="tsreq">Purchase requests</div>\r\n                            </div>\r\n                            <div class="desc">Purchase requests can be raised by users from different departments based\r\n                                on need. The requests may be approved by identified approving authorities. Axi ERP makes\r\n                                it easy to aggregate approved requests and place purchase orders on vendors.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n                                <!-- <button class="btn-pill mt-auto align-self-end navigate" data-transid="tsreq">Purchase Request</button> -->\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/purchase-order.png">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="tslpo">Purchase orders</div>\r\n                            </div>\r\n                            <div class="desc">Purchase orders can be placed on identified suppliers. The purchase order\r\n                                captures all data related to the supplier, list of items, rates, applicable taxes and\r\n                                terms of supply. The PO may be electronically sent to suppliers. PO can be raised\r\n                                against pending purchase requests. The list of pending requests popup for selection\r\n                                clicking on the Pending requests button under the Item particulars section in the PO\r\n                                form. To track the status of a PO, type command in the Axi command line at the bottom\r\n                                View purchase Order &amp; select the required PO No.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="tslpo">Purchase\r\n                                    order</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="" data-transtype="ads">Pending\r\n                                    Purchase Order Data</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="" data-transtype="ads">Purchase\r\n                                    Summary</button>\r\n\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/GRN3.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="tsgrn">Good Receipt Note (GRN)</div>\r\n                            </div>\r\n                            <div class="desc">Goods received note option is used to record receipt of goods into a\r\n                                location and a selected sub location. This is used to record material receipts from\r\n                                suppliers. When goods are transferred from a location to another location that may\r\n                                attract taxes (like across states in India), this option is used to record the receipt\r\n                                of such material transfers. As and when material is received, it is added to the stock\r\n                                of that location &amp; sub location. \r\n\r\n\r\n                                Additional expenses like transportation, clearing &amp; forwarding, logistics related\r\n                                etc, may be incurred after or while receiving goods from a supplier. These will add to\r\n                                the cost of the item. Use this option to record such expenses against a GRN.\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="sbill">Create\r\n                                    Additional cost of goods</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="sbill">View\r\n                                    Additional cost of goods</button>\r\n\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/QC1.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="stkqc">QC</div>\r\n                            </div>\r\n                            <div class="desc">On receiving goods, perform a quality check and identify the damaged or\r\n                                faulty goods. QC is done against a GRN. Rejected items are moved to Rejections store\r\n                                within that location. Items in the Rejection store are not considered as in stock. Use\r\n                                the Fill items button under the Item QC Details section in the QC form to select\r\n                                from a list of items in the selected GRN. </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/GRN1.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="aparo">Supplier bills</div>\r\n                            </div>\r\n                            <div class="desc">Suppliers submit bills against goods that were delivered. The supplier\r\n                                bills are validated by Axi ERP against the purchase order and the GRN. Deviations are\r\n                                raised as exceptions. The bills are automatically posted into GL &amp; AP.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="atpaysum" data-transtype="iview">View Accounts payable\r\n                                            summary</a></li>\r\n                                    <li><a data-transid="arapagei" data-transtype="iview">View accounts payable\r\n                                            billwise</a></li>\r\n                                    <li><a data-transid="gsupp">View Supplier</a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Purchase Summary</a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Pending Purchase Order Data</a></li>\r\n\r\n\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/GRN.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="rppay">Supplier payments</div>\r\n                            </div>\r\n                            <div class="desc">Payments are made to suppliers against approved supplier bills. As the\r\n                                supplier bills are already validated against GRN &amp; PO, Axi ERP ensures tight\r\n                                operations control. The payments are set off against the bills.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="" data-transtype="ads">Purchase Summary</a></li>\r\n                                    <li><a data-transid="atpaysum" data-transtype="iview">Accounts payable\r\n                                            summary</a></li>\r\n                                    <li><a data-transid="arapagei" data-transtype="iview">Accounts payable\r\n                                            billwise</a></li>\r\n                                    <li><a data-transid="gsupp">View Supplier</a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Pending Purchase Order\r\n                                            Data</a></li>\r\n\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/purchase-order.png">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="purre">Purchase returns</div>\r\n                            </div>\r\n                            <div class="desc">This is a module that enables users to record purchase returns. The\r\n                                returns done against a GRN. Returns are posted into GL &amp; AP automatically. Returns\r\n                                can be recorded against a GRN or against a purchase bill. In case of a return against a\r\n                                purchase bill, a corresponding entry is posted into finance.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="purre">Create\r\n                                    Purchase returns against\r\n                                    bills</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="purre">View\r\n                                    Purchase returns against\r\n                                    bills</button>\r\n\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/payroll2.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="purre">Purchase Reports &amp; analysis</div>\r\n                            </div>\r\n                            <div class="desc">Axi provides a complete view of your purchase & purchase order data.\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="" data-transtype="ads">Purchase Summary</a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Pending Purchase Order Data</a>\r\n                                    </li>\r\n                                    <li><a data-transid="surma">Supplier item rates</a></li>\r\n                                    <li><a data-transid="spricena" data-transtype="iview">Price list</a></li>\r\n                                    <li><a data-transid="nonmovin" data-transtype="iview">Slow moving/Non moving\r\n                                            items</a></li>\r\n                                    <li><a data-transid="prodm">Item listing</a></li>\r\n                                    <li><a data-transid="stkreord" data-transtype="iview">Reorder </a></li>\r\n                                    <li><a data-transid="stkstmtp" data-transtype="iview">Stock\r\n                                            availability</a></li>\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n\r\n            </div>\r\n\r\n\r\n            <div class="card-ui Module-Wrapper ">\r\n                <div class="Module-Parent ">\r\n                    <div class="module-header" id="OrderToCash">\r\n                        <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">payments</span></div>\r\n                        <div class="title">Order To Cash</div>\r\n                    </div>\r\n\r\n                    <div class="desc">This covers the cycle of activities that related to sales starting from getting a\r\n                        sales order from a customer till cash is received for the goods or services offered. \r\n\r\n\r\n                        Axi manages the order to cash cycle with ease. Its multiple configurable options make it\r\n                        suitable for managing the dynamic business needs related to sales. This enables end user\r\n                        organizations to innovate.\r\n                    </div>\r\n\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/sales-analysis.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="slord">Sales Orders</div>\r\n                            </div>\r\n                            <div class="desc">Orders from customers are recorded in Sales orders option. The sales\r\n                                orders may be populated from E-Commerce portals. The sales order API may be used to\r\n                                enable direct connections from web portals and E-Comm portals. While creating the sales\r\n                                order, the data about customers, products &amp; sales people can be popped up using\r\n                                commands view customer, view sales data, view sales order data, view price list,\r\n                                view stock availability etc.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/QC.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="dlchl">Delivery notes</div>\r\n                            </div>\r\n                            <div class="desc">These are used to record the deliveries that are made against a selected\r\n                                sales order. A sales order may be delivered fully or partially. This is an optional\r\n                                step. Invoices may be raised directly against sales orders or against delivery notes.\r\n                                Stock is updated at this step. </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="invce">View invoices</a></li>\r\n                                    <li><a data-transid="slord">View sales orders</a></li>\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/Invoice.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="invce">Sales Invoice</div>\r\n                            </div>\r\n                            <div class="desc">\r\n                                Invoices can be entered to record sale of items. Sales invoices may optionally be raised\r\n                                against pending sales orders. The pending items in sales orders can be accessed for\r\n                                selection by clicking on the sales orders button below the Item Details section in\r\n                                the invoice form. There are options to raise direct sales invoice too.\r\n\r\n The\r\n                                applicable taxes like (GST or VAT &amp; TCS) will be applied on products in invoices as\r\n                                setup for the items. Automatically posts invoices to GL, &amp; AR modules to the\r\n                                accounts mapped for the selected accounts. The sales invoice also updates the stock if a\r\n                                delivery note is not entered.\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="spricena" data-transtype="iview">Price list</a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Sales Data</a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Sales Order Summary</a></li>\r\n                                    <li><a data-transid="gcust">Customer</a></li>\r\n                                    <li><a data-transid="prodm">Item</a></li>\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/sales-returns.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="salry">Sales returns</div>\r\n                            </div>\r\n                            <div class="desc">Returns from customers are recorded through this option. The returns are\r\n                                done against a sales invoice. Returns are posted into GL &amp; AR automatically. The\r\n                                stock is also updated. </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="invce">Sales invoices</a></li>\r\n                                    <li><a data-transid="gcust">Customer</a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Sales Data</a></li>\r\n                                    <li><a data-transid="slord">Sales orders</a></li>\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/receipt.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="crrec">Customer receipts</div>\r\n                            </div>\r\n                            <div class="desc">Money received from customers are recorded in this form. The receipt may\r\n                                be in any currency. By default, it will be received in the customer currency and\r\n                                converted to base currency and stored. Optionally, the receipts may be adjusted against\r\n                                one or more bills. Advances received from customers are also recorded in this form.\r\n                                These can then be set off against the invoices using the Settle advances to bills\r\n                                option.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="gcust">Customer</a></li>\r\n                                    <li><a data-transid="invce">Sales Invoice</a></li>\r\n                                    <li><a data-transid="ofset">Settle advances to bills</a></li>\r\n                                    <li><a data-transid="atrevsum" data-transtype="iview">Accounts receivable\r\n                                            summary</a></li>\r\n                                    <li><a data-transid="arapagei" data-transtype="iview">Accounts receivable\r\n                                            billwise</a></li>\r\n                                    <li><a data-transid="exrat">Exchange rate</a></li>\r\n\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/QC4.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="spricena" data-transtype="iview">Price list</div>\r\n                            </div>\r\n                            <div class="desc">The selling price for products can be set from an effective date. The\r\n                                price list may for a location or for a customer too. </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/payroll2.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="slord">Sales Reports</div>\r\n                            </div>\r\n                            <div class="desc">Axi provides a complete view of your sales & sales order data </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="" data-transtype="ads">Sales Data</a></li>\r\n                                    <li><a data-transid="slord">Sales orders</a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Pending Sales Orders </a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Sales Order Summary</a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Product wise Profitability\r\n                                            Data</a>\r\n                                    </li>\r\n                                    <li><a data-transid="" data-transtype="ads">Customer wise Profitability\r\n                                            Data\r\n\r\n                                        </a></li>\r\n                                    <li><a data-transid="" data-transtype="ads">Sales Person wise Profitability\r\n                                            Data\r\n                                        </a></li>\r\n                                    <li><a data-transid="atrevsum" data-transtype="iview">Accounts receivable\r\n                                            summary</a></li>\r\n                                    <li><a data-transid="arapagei" data-transtype="iview">Accounts receivable\r\n                                            billwise</a></li>\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n            </div>\r\n\r\n            <div class="card-ui Module-Wrapper ">\r\n                <div class="Module-Parent ">\r\n                    <div class="module-header" id="InventoryControl">\r\n                        <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assignment</span></div>\r\n                        <div class="title">Inventory Control</div>\r\n                    </div>\r\n\r\n                    <div class="desc">Inventory control, also known as stock control, is regulating and maximizing your\r\n                        company as warehouse inventory. Axi can manage multi locations. Axi maintains location wise\r\n                        inventory and provides complete visibility of stock available. Stock is valued using FIFO or\r\n                        Weighted average. In case of batch wise, the batches are accepted in each transaction that adds\r\n                        to or reduces from stock.\r\n\r\n The actual stock value is posted at the end of every day into\r\n                        the books of accounts. When transactions alter the stock value and item cost rate at a back\r\n                        date, Axi maintains such changes and revalues the stock and item cost rate automatically. This\r\n                        is done as a day end job or user can choose to run this using the Stock revaluation and\r\n                        posting option. This can be run any number of times.\r\n                    </div>\r\n\r\n                </div>\r\n\r\n\r\n\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/receipt.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="instr">Material receipt</div>\r\n                            </div>\r\n                            <div class="desc">Items received into this location/sub location are recorded in this form.\r\n                                One or more items may be selected for receipt. The stock will be increased in the\r\n                                selected location / sub location.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="stkstwov" data-transtype="iview">Stock statement</a>\r\n                                    </li>\r\n                                    <li><a data-transid="stkledge" data-transtype="iview">Stock ledger </a>\r\n                                    </li>\r\n                                    <li><a data-transid="prodm">Items </a></li>\r\n                                    <li><a data-transid="marei">Material issue </a></li>\r\n\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/Items.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="marei">Material issue</div>\r\n                            </div>\r\n                            <div class="desc">Items that are issued from this location/sub location are recorded in this\r\n                                form. The stock of the selected items will be reduced in this location/sub location.\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="stkstwov" data-transtype="iview">Stock statement</a>\r\n                                    </li>\r\n                                    <li><a data-transid="stkledge" data-transtype="iview">Stock ledger </a>\r\n                                    </li>\r\n                                    <li><a data-transid="prodm">Items </a></li>\r\n                                    <li><a data-transid="instr">Material Receipts </a></li>\r\n\r\n\r\n                                </ul>\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/stock.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="sttro">Material transfer</div>\r\n                            </div>\r\n                            <div class="desc">Material transfer option is used to transfer material from one sub\r\n                                location to another sub location within the same location or between two locations that\r\n                                do not attract tax. In case material is to be transferred from one location to another\r\n                                that involves tax, the transfer should be done by raising invoice at source and GRN at\r\n                                destination. </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/stock1.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="stkstwov">Stock statement &amp; Ledger</div>\r\n                            </div>\r\n                            <div class="desc">The stock statement &amp; ledger provide stock related summary &amp;\r\n                                transactions in the selected location. These can be generated with or without value.\r\n                                When generated with value, if required, Axi will automatically revalue stock and present\r\n                                the report.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="stkstwov" data-transtype="iview">stock statement</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="stkstsum" data-transtype="iview">stock statement with value</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="stkledge" data-transtype="iview">stock ledger</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="stkldgv" data-transtype="iview">stock ledger with value</button>\r\n\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="stkstmtp" data-transtype="iview">Stock\r\n                                            availability</a></li>\r\n                                    <li><a data-transid="prodm">Items</a></li>\r\n                                    <li><a data-transid="bran">Locations</a></li>\r\n\r\n\r\n\r\n                                </ul>\r\n\r\n\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n            </div>\r\n\r\n            <div class="card-ui Module-Wrapper ">\r\n                <div class="Module-Parent ">\r\n                    <div class="module-header" id="FinancialAccounting">\r\n                        <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                        </div>\r\n                        <div class="title">Financial Accounting</div>\r\n                    </div>\r\n\r\n                    <div class="desc">Finance is one of the core functions in most enterprises. It is imperative for all\r\n                        enterprises to have a tight control on their financials. Most of the statutory compliance are\r\n                        part of the finance module. Axi offers a robust financial accounting system with tight controls.\r\n                        Transactions from other modules like sales &amp; purchase are auto posted into finance. These\r\n                        postings are done into the finance voucher option. </div>\r\n\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/chart-of-accoutns.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transtype="p">Chart of accounts</div>\r\n                            </div>\r\n                            <div class="desc">Axi comes with a standard chart of accounts. Every row in a chart of\r\n                                account can be group or an account. Groups can have sub groups or accounts under it. Sub\r\n                                ledgers are created by setting Control a/c to true. By default, Axi provides sub\r\n                                ledgers for debtors and creditors. Customers or suppliers are automatically created as a\r\n                                sub ledger account under Debtor/Creditor control account. Use the GL opening balance\r\n                                option to enter opening balances for accounts. Upload data into this form while data\r\n                                migration.</div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end" onclick="parent.LoadIframe(''htmlPages.aspx?loadcaption=Chart Of Accounts'')">View</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="costc">Cost centers</a></li>\r\n                                    <li><a data-transid="dimas">Cost groups</a></li>\r\n                                    <li><a data-transid="trialbal" data-transtype="iview">Trial balance</a>\r\n                                    </li>\r\n                                    <li><a data-transid="gcust">Customer</a></li>\r\n                                    <li><a data-transid="gsupp">Supplier</a></li>\r\n                                    <li><a data-transid="vhngl">GL opening balance</a></li>\r\n                                </ul>\r\n\r\n\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/GRN3.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="vchge">General Journal</div>\r\n                            </div>\r\n                            <div class="desc">General journal option is used to enter all financial transactions that\r\n                                are not auto posted from other modules. This may be used to enter all admin expense\r\n                                entries and financial adjustment entries. </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="trialbal" data-transtype="iview">Trial balance</a>\r\n                                    </li>\r\n                                    <li><a data-transid="glsubrep" data-transtype="iview">General Ledger</a>\r\n                                    </li>\r\n                                    <li><a data-transid="vchft">Fund transfer</a></li>\r\n                                    <li><a data-transid="exrat">Exchange rate</a></li>\r\n                                </ul>\r\n\r\n\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/receipt.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="vchft">Fund transfer</div>\r\n                            </div>\r\n                            <div class="desc">This option is used to record cash withdrawals, deposits and inter-bank\r\n                                transactions. </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="trialbal" data-transtype="iview">Trial balance</a>\r\n                                    </li>\r\n                                    <li><a data-transid="vchge">General Journal</a></li>\r\n                                    <li><a data-transid="glsubrep" data-transtype="iview">General Ledger</a>\r\n                                    </li>\r\n                                </ul>\r\n\r\n\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/payroll2.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="vchtr">Financial reports</div>\r\n                            </div>\r\n                            <div class="desc">As Axi is an online system, financial reports like Trial balance, Balance\r\n                                sheet, Profit &amp; loss statement, General ledger, Sub ledgers, Cash book, Bank book,\r\n                                Voucher listing, Bank balances can all be viewed at any point of time. In case stock\r\n                                related entries are made that may need revaluation of stock, Axi will automatically\r\n                                prompt and run the revaluation routine before generating the report that provides along\r\n                                with value. The auto revaluation will be done when TB, Balance sheet or P&amp;L is\r\n                                generated. </div>\r\n                            <div class="Action-Btns">\r\n                                <div class="AB-Links">Links</div>\r\n                                <ul>\r\n                                    <li><a data-transid="trialbal" data-transtype="iview">Trial balance</a>\r\n                                    </li>\r\n                                    <li><a data-transid="pandlstm" data-transtype="iview">Profit &amp; loss\r\n                                            statement</a></li>\r\n                                    <li><a data-transid="glsubrep" data-transtype="iview">General Ledger</a>\r\n                                    </li>\r\n                                    <li><a data-transid="bsheform" data-transtype="iview">Balance sheet </a>\r\n                                    </li>\r\n\r\n                                    <li><a data-transid="bankreco" data-transtype="iview">Bank book </a></li>\r\n                                    <li><a data-transid="fintrans" data-transtype="iview">Voucher listing </a>\r\n                                    </li>\r\n                                    <li><a data-transid="" data-transtype="ads">Expenses Summary </a></li>\r\n                                    <li><a data-transid="subledge" data-transtype="iview">Subledger report </a>\r\n                                    </li>\r\n                                    <!-- <li><a  data-transid="bcbalnc">Bank balances </a></li> -->\r\n                                </ul>\r\n\r\n\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/services2.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="costc">Cost centers</div>\r\n                            </div>\r\n                            <div class="desc">Cost group option is used to create cost groups. A group may be created\r\n                                under another cost group. This enables a hierarchical creation of cost groups. Cost\r\n                                center option is used to create cost centers in any cost group. For example, SBU\r\n                                (strategic business unit) is a cost group and each business unit is a cost center under\r\n                                it. Similarly, department may be a cost group. Individual departments may be created\r\n                                under department group as cost centers.\r\n\r\n When expense entries are made in general\r\n                                journal, each expense could be apportioned against each cost center based on a\r\n                                percentage. Cost center setup option lets user setup the apportioning percentage against\r\n                                each cost center for any selected account. In case this is setup, the apportioning is\r\n                                automatically done while booking expenses. View cost analysis is used to see the cost\r\n                                center </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="costc">Cost\r\n                                    centers</button>\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="dimas">Cost\r\n                                    groups</button>\r\n                                <!-- <button class="btn-pill mt-auto align-self-end navigate" data-transid="costc">Cost\r\n                                    setup</button> -->\r\n                                <button class="btn-pill mt-auto align-self-end navigate" data-transid="" data-transtype="ads">Cost\r\n                                    Analysis Data</button>\r\n\r\n\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class="Module-Child-Wrapper">\r\n                    <div class="Module-Child">\r\n                        <div class="Module-Img">\r\n                            <img src="images/sub-ledgers.jpg">\r\n                        </div>\r\n\r\n                        <div class="module-Content">\r\n\r\n\r\n\r\n                            <div class="module-header">\r\n                                <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">assured_workload</span>\r\n                                </div>\r\n                                <div class="title" data-transid="tFnYr">Financial year end </div>\r\n                            </div>\r\n                            <div class="desc">At the end of a financial year, open the year end closing journal option\r\n                                select the current year that is to be posted to next financial year. The system auto\r\n                                populates the closing balance as on the last day of the financial year. The system\r\n                                automatically creates a new financial year and posts the closing as opening balance to\r\n                                next year. Users can then start entering transactions into the new financial year. This\r\n                                journal can be populated any number of times. </div>\r\n                            <div class="Action-Btns">\r\n                                <button class="btn-pill mt-auto align-self-end">View</button>\r\n                                <button class="btn-pill mt-auto align-self-end">Create</button>\r\n\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n\r\n            </div>\r\n\r\n\r\n\r\n\r\n\r\n            <div class="card-ui Module-Wrapper ">\r\n                <div class="Module-Parent ">\r\n                    <div class="module-header" id="AccountReceivables">\r\n                        <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">receipt_long</span></div>\r\n                        <div class="title" data-transid="fiacc">Account receivables</div>\r\n                    </div>\r\n\r\n                    <div class="desc">Customer receipts option is used to record money receipts from customers against\r\n                        one or more invoices. In case money is received from customer as an advance, record it in\r\n                        customer receipts option as an advance. Subsequently, after invoices are made, use the Settle\r\n                        advances to invoices option to set off the advances against one or more invoices. Money can be\r\n                        received from customers in any currency. Open customer invoices option is used to record all the\r\n                        open invoices. This may also be done by uploading the list of pending invoices from an excel\r\n                        sheet into this option. </div>\r\n                    <div class="Action-Btns">\r\n                        <button class="btn-pill mt-auto align-self-end">Create</button>\r\n                        <button class="btn-pill mt-auto align-self-end">View</button>\r\n                        <button class="btn-pill mt-auto align-self-end navigate" data-transid="atrevsum" data-transtype="iview">Accounts receivable summary</button>\r\n                        <button class="btn-pill mt-auto align-self-end navigate" data-transid="arapagei" data-transtype="iview">Accounts receivable bill wise</button>\r\n                        <button class="btn-pill mt-auto align-self-end navigate" data-transid="ofset">Settle advances to\r\n                            bills</button>\r\n\r\n\r\n\r\n\r\n                    </div>\r\n\r\n                    <div class="Action-Btns">\r\n                        <div class="AB-Links">Links</div>\r\n                        <ul>\r\n                            <li><a data-transid="arapo">Open customer invoices</a></li>\r\n                            <li><a data-transid="glsubrep" data-transtype="iview">General ledger</a></li>\r\n                            <li><a data-transid="gcust">Customer</a></li>\r\n                            <li><a data-transid="exrat">Exchange rate</a></li>\r\n                        </ul>\r\n                    </div>\r\n\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n            <div class="card-ui Module-Wrapper ">\r\n                <div class="Module-Parent ">\r\n                    <div class="module-header" id="AccountPayable">\r\n                        <div class="icon blue mb-3"><span class="material-icons material-icons-style material-icons-2">receipt_long</span></div>\r\n                        <div class="title" data-transid="fiacc">Accounts payable</div>\r\n                    </div>\r\n\r\n                    <div class="desc">Supplier payment is an option used to pay supplier against supplier invoices. This\r\n                        is also used to pay advances to suppliers. Subsequently, after invoices are made, use the Settle\r\n                        advances to invoices option to set off the advances against one or more supplier invoices. Open\r\n                        supplier invoices are used to record all open invoices from suppliers. </div>\r\n                    <div class="Action-Btns">\r\n                        <button class="btn-pill mt-auto align-self-end">Create</button>\r\n                        <button class="btn-pill mt-auto align-self-end">View</button>\r\n                        <button class="btn-pill mt-auto align-self-end navigate" data-transid="atpaysum" data-transtype="iview">Accounts payable summary</button>\r\n                        <button class="btn-pill mt-auto align-self-end navigate" data-transid="actpaybi" data-transtype="iview">Accounts payable bill wise</button>\r\n                        <button class="btn-pill mt-auto align-self-end navigate" data-transid="ofset">Settle advances to\r\n                            bills</button>\r\n\r\n\r\n\r\n\r\n                    </div>\r\n\r\n                    <div class="Action-Btns">\r\n                        <div class="AB-Links">Links</div>\r\n                        <ul>\r\n                            <li><a data-transid="aparo">Enter open supplier bills</a></li>\r\n\r\n                            <li><a data-transid="glsubrep" data-transtype="iview">General ledger</a></li>\r\n                            <li><a data-transid="gsupp">Supplier</a></li>\r\n                            <li><a data-transid="exrat">Exchange rate</a></li>\r\n                        </ul>\r\n                    </div>\r\n\r\n\r\n                </div>\r\n            </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n\r\n\r\n\r\n    <script>\r\n        $(''.nav-link'').on(''click'', function (e) {\r\n            e.preventDefault();\r\n\r\n            $(''.module-header'').removeClass(''Tab-CActive'');\r\n\r\n            const target = $(this).data(''target'');\r\n            $(target).addClass(''Tab-CActive'');\r\n            const offset = 50; // adjust based on tab/header height\r\n\r\n            $(''html, body'').animate({\r\n                scrollTop: $(target).offset().top - offset\r\n            }, 500);\r\n        });\r\n\r\n        $(''.nav-link'').on(''click'', function () {\r\n            $(''.nav-link'').removeClass(''active'');\r\n            $(this).addClass(''active'');\r\n        });\r\n\r\n\r\n\r\n    </script>\r\n\r\n    <script>\r\n        //        dynamically add readmore btn if content exceeds 6 lines\r\n\r\n\r\n\r\n        $(document).ready(function () {\r\n\r\n            $(''.desc'').each(function () {\r\n\r\n                var $desc = $(this);\r\n\r\n                // Get line height\r\n                var lineHeight = parseFloat($desc.css(''line-height''));\r\n\r\n                // If line-height is normal, calculate it\r\n                if (isNaN(lineHeight)) {\r\n                    lineHeight = parseFloat($desc.css(''font-size'')) * 1.2;\r\n                }\r\n\r\n                var maxHeight = lineHeight * 3;\r\n\r\n                // Check if content exceeds 6 lines\r\n                if ($desc[0].scrollHeight > maxHeight + 4) {\r\n\r\n                    $desc.after(''<button class="read-more-btn">Read More</button>'');\r\n                }\r\n            });\r\n\r\n            $(document).on(''click'', ''.read-more-btn'', function () {\r\n\r\n                var $btn = $(this);\r\n                var $desc = $btn.prev(''.desc'');\r\n\r\n                if ($desc.hasClass(''expanded'')) {\r\n\r\n                    $desc.removeClass(''expanded'');\r\n                    $btn.text(''Read More'');\r\n\r\n                } else {\r\n\r\n                    $desc.addClass(''expanded'');\r\n                    $btn.text(''Read Less'');\r\n                }\r\n            });\r\n\r\n\r\n\r\n        });\r\n\r\n\r\n\r\n\r\n\r\n    </script>\r\n\r\n    <script>\r\n\r\n        document.querySelectorAll(".Quick-Links")\r\n            .forEach(wrapper => {\r\n\r\n                const carousel =\r\n                    wrapper.querySelector(".nav-pills");\r\n\r\n                const leftBtn =\r\n                    wrapper.querySelector(".btn-left");\r\n\r\n                const rightBtn =\r\n                    wrapper.querySelector(".btn-right");\r\n\r\n                const cards =\r\n                    carousel.querySelectorAll(".nav-pills");\r\n                if (!rightBtn || !leftBtn || cards) {\r\n                    console.warn("Carousel buttons not found");\r\n                    return;\r\n                }\r\n\r\n\r\n                function updateButtons() {\r\n\r\n                    const maxScroll =\r\n                        carousel.scrollWidth -\r\n                        carousel.clientWidth;\r\n\r\n                    leftBtn.classList.toggle(\r\n                        "hidden",\r\n                        carousel.scrollLeft <= 5\r\n                    );\r\n\r\n                    rightBtn.classList.toggle(\r\n                        "hidden",\r\n                        carousel.scrollLeft >= maxScroll - 5\r\n                    );\r\n                }\r\n\r\n\r\n                function scrollNext() {\r\n\r\n                    const current =\r\n                        carousel.scrollLeft;\r\n\r\n                    for (let card of cards) {\r\n\r\n                        if (card.offsetLeft > current + 10) {\r\n\r\n                            carousel.scrollTo({\r\n                                left: card.offsetLeft,\r\n                                behavior: "smooth"\r\n                            });\r\n\r\n                            break;\r\n                        }\r\n                    }\r\n                }\r\n\r\n\r\n\r\n                function scrollPrev() {\r\n\r\n                    const current =\r\n                        carousel.scrollLeft;\r\n\r\n                    for (let i = cards.length - 1; i >= 0; i--) {\r\n\r\n                        if (cards[i].offsetLeft < current - 10) {\r\n\r\n                            carousel.scrollTo({\r\n                                left: cards[i].offsetLeft,\r\n                                behavior: "smooth"\r\n                            });\r\n\r\n                            break;\r\n                        }\r\n\r\n                    }\r\n                }\r\n\r\n\r\n\r\n                rightBtn.addEventListener(\r\n                    "click",\r\n                    scrollNext\r\n                );\r\n\r\n\r\n                leftBtn.addEventListener(\r\n                    "click",\r\n                    scrollPrev\r\n                );\r\n\r\n\r\n                carousel.addEventListener(\r\n                    "scroll",\r\n                    updateButtons\r\n                );\r\n\r\n                window.addEventListener(\r\n                    "resize",\r\n                    updateButtons\r\n                );\r\n\r\n                updateButtons();\r\n\r\n            });\r\n    </script>\r\n\r\n\r\n    <script>\r\n\r\n        window.isFromCustomDashboard = true;\r\n\r\n        async function loadInboxSummary() {\r\n\r\n            $("#InboxCards").empty();\r\n\r\n            const sections = [\r\n                // { key: "tasks", label: "Tasks", ds: "DS_AxpertInbox_V2" },\r\n                { key: "pending", label: "Approvals pending with me", ds: "DS_PendingApprovals" },\r\n                { key: "pending", label: "Approvals requested by me", ds: "REQUESTEDBYME" },\r\n                // { key: "notifications", label: "Notifications", ds: "DS_Notifications" },\r\n                { key: "Reminders", label: "Reminders", ds: "DS_Reminders" },\r\n                { key: "Escalations", label: "Escalations", ds: "DS_Escalations" },\r\n                { key: "completed", label: "Completed", ds: "DS_Completed" },\r\n                // { key: "people", label: "People", ds: "DS_People" },\r\n                // { key: "groups", label: "Groups", ds: "DS_Groups" }\r\n            ];\r\n\r\n            for (const sec of sections) {\r\n\r\n                const params = {\r\n                    adsNames: [sec.ds],\r\n                    props: {\r\n                        pageno: 1,\r\n                        pagesize: 0\r\n                    },\r\n                    sqlParams: {\r\n                        uname: parent.mainUserName,\r\n                        searchtext: ""\r\n                    }\r\n                };\r\n\r\n                parent.GetDataFromAxList(params, function (response) {\r\n\r\n                    try {\r\n\r\n                        const raw =\r\n                            typeof response === "string"\r\n                                ? response\r\n                                : typeof response.d === "string"\r\n                                    ? response.d\r\n                                    : JSON.stringify(response.d || response);\r\n\r\n                        const parsed =\r\n                            JSON.parse(raw);\r\n\r\n                        const result =\r\n                            typeof parsed.d === "string"\r\n                                ? JSON.parse(parsed.d)\r\n                                : parsed;\r\n\r\n                        const ds =\r\n                            result.result.data[0];\r\n\r\n                        const count =\r\n                            ds.totalcount ||\r\n                            ds.recordcount ||\r\n                            ds.totalrows ||\r\n                            (ds.data ? ds.data.length : 0);\r\n\r\n                        $("#InboxCards").append(createInboxCard(sec.label, count, sec.key));\r\n\r\n                    }\r\n                    catch (e) {\r\n\r\n                        $("#InboxCards").append(createInboxCard(sec.label, 0, sec.key));\r\n\r\n                    }\r\n\r\n                });\r\n\r\n            }\r\n\r\n        }\r\n\r\n        function createInboxCard(title, count, key) {\r\n\r\n            return `\r\n        <div class="Aggregation-Item-wrap">\r\n            <a href="javascript:void(0)"\r\n               class="Aggregation-item inboxCard"\r\n               data-section="${key}">\r\n\r\n                <div class="Aggregation-icon">\r\n                    <span class="material-icons material-icons-style material-icons-2">\r\n                        mark_email_unread\r\n                    </span>\r\n                </div>\r\n\r\n                <div class="Aggregation-content">\r\n                    <h6 class="subtitle">${title}</h6>\r\n                    <h4 class="value">${count}</h4>\r\n                </div>\r\n\r\n            </a>\r\n        </div>`;\r\n        }\r\n\r\n        $(document).on("click", ".inboxCard", function () {\r\n            debugger\r\n\r\n            const section = $(this).data("section");\r\n\r\n            parent.LoadIframe(''htmlpages.aspx?load=1784889372733'')\r\n\r\n        });\r\n\r\n\r\n        function loadUserAccess() {\r\n\r\n            var params = {\r\n                adsNames: ["ds_custom_useraccess"],\r\n                props: {\r\n                    pageno: 1,\r\n                    pagesize: 0\r\n                },\r\n                sqlParams: {\r\n                    puser: parent.mainUserName\r\n                }\r\n            };\r\n\r\n            parent.GetDataFromAxList(\r\n                params,\r\n                function (response) {\r\n\r\n                    console.log(response);\r\n\r\n                    applyUserAccess(response);\r\n\r\n                },\r\n                function (error) {\r\n\r\n                    console.log(error);\r\n\r\n                }\r\n            );\r\n        }\r\n        function applyUserAccess(response) {\r\n            debugger;\r\n            // Parse response.d\r\n            var parsed = JSON.parse(response);\r\n\r\n            var accessList = parsed.result.data[0].data || [];\r\n\r\n            // Use sname instead of transid\r\n            var userTransIds = accessList.map(function (x) {\r\n                return (x.sname || "").toLowerCase().trim();\r\n            });\r\n\r\n            console.log("User Access:", userTransIds);\r\n\r\n            $(".Module-Child-Wrapper").hide();\r\n\r\n            $(".Module-Child-Wrapper").each(function () {\r\n\r\n                var $title = $(this).find(".title").first();\r\n\r\n                var transid = ($title.attr("data-transid") || "")\r\n                    .toLowerCase()\r\n                    .trim();\r\n\r\n                // Existing logic for forms\r\n                if (transid && userTransIds.includes(transid)) {\r\n                    $(this).show();\r\n                    return;\r\n                }\r\n\r\n                // Special case for pages like Chart of Accounts\r\n                var transtype = ($title.attr("data-transtype") || "")\r\n                    .toLowerCase()\r\n                    .trim();\r\n\r\n                if (transtype === "p") {\r\n\r\n                    var caption = $title.text().trim().toLowerCase();\r\n\r\n                    var hasAccess = accessList.some(function (x) {\r\n                        return (x.stype || "").toLowerCase() === "p" &&\r\n                            (x.caption || "").trim().toLowerCase() === caption;\r\n                    });\r\n\r\n                    if (hasAccess) {\r\n                        $(this).show();\r\n                    }\r\n                }\r\n\r\n            });\r\n\r\n            // Hide empty modules\r\n            $(".card-ui.Module-Wrapper").each(function () {\r\n\r\n                var $module = $(this);\r\n\r\n                // --- FIXED: Skip Inbox, Account Receivables, and Account Payable sections explicitly ---\r\n                if ($module.find("#Inbox").length) // ||\r\n                // $module.find("#AccountReceivables").length ||\r\n                // $module.find("#AccountPayable").length ||\r\n                // $module.find("#ChartOfAccounts").length) \r\n                {\r\n                    $module.show(); // Ensure they remain visible\r\n\r\n                    var moduleId = $module.find(".Module-Parent .module-header:first").attr("id");\r\n                    if (moduleId) {\r\n                        $(''.nav-link[data-target="#'' + moduleId + ''"]'').show();\r\n                    }\r\n                    return true; // Continue to next loop\r\n                }\r\n\r\n                var visibleChildren = $module.find(".Module-Child-Wrapper:visible").length;\r\n\r\n                if (visibleChildren === 0) {\r\n\r\n                    // Hide complete section including header, description and cards\r\n                    $module.hide();\r\n\r\n                    // Hide corresponding tab\r\n                    var moduleId = $module\r\n                        .find(".Module-Parent .module-header:first")\r\n                        .attr("id");\r\n\r\n                    if (moduleId) {\r\n                        $(''.nav-link[data-target="#'' + moduleId + ''"]'').hide();\r\n                    }\r\n                }\r\n                else {\r\n\r\n                    // Ensure section and tab are visible if at least one child is visible\r\n                    $module.show();\r\n\r\n                    var moduleId = $module\r\n                        .find(".Module-Parent .module-header:first")\r\n                        .attr("id");\r\n\r\n                    if (moduleId) {\r\n                        $(''.nav-link[data-target="#'' + moduleId + ''"]'').show();\r\n                    }\r\n                }\r\n            });\r\n        }\r\n\r\n\r\n\r\n        function prevbtn_click(e) {\r\n            debugger\r\n            let btn = $(e).find("button")[0];\r\n\r\n            if (btn) {\r\n                // If already clicked and locked out, exit early\r\n                if (btn.style.pointerEvents === "none") {\r\n                    return false;\r\n                }\r\n                // Lock out the button immediately to avoid duplicate firing\r\n                btn.style.pointerEvents = "none";\r\n            }\r\n\r\n            if (e.hasClass("linkGray")) {\r\n                // Reset block and return if button shouldn''t navigate\r\n                if (btn) btn.style.pointerEvents = "auto";\r\n                return false;\r\n            }\r\n\r\n            // 1️⃣ Safe Array Checks before dropping elements\r\n            if (appLinkHistoryLabel.length > 0) appLinkHistoryLabel.pop();\r\n            if (appLinkHistory.length > 0) {\r\n                appLinkHistory.pop();\r\n            }\r\n\r\n            if (isMobile && 1 == appLinkHistory.length) {\r\n                console.log("axm_mainpageloaded");\r\n            }\r\n\r\n            // 2️⃣ Force clear pointer lock right before navigation updates\r\n            if (btn) {\r\n                setTimeout(() => {\r\n                    btn.style.pointerEvents = "auto";\r\n                }, 300); // 300ms fallback timeout to free click locks\r\n            }\r\n\r\n            updateLinks(e, "prev");\r\n        }\r\n\r\n\r\n\r\n        // 1. Function to open Tstruct (Handles both standard forms and entity views)\r\n        function open_tstruct(transid, mode) {\r\n            debugger\r\n            var url = "";\r\n            if (mode === "create") {\r\n                url = "../../aspx/tstruct.aspx?transid=" + encodeURIComponent(transid) + "&hltype=open&createaxiflag=true&dummyload=false&hdnbElapsTime=0";\r\n            } else if (mode === "view") {\r\n                url = "../../aspx/Entity.aspx?tstid=" + encodeURIComponent(transid) + "&hdnbElapsTime=0";\r\n            } else {\r\n                url = "../../aspx/tstruct.aspx?transid=" + encodeURIComponent(transid) + "&act=load";\r\n            }\r\n            navigateToUrl(url);\r\n        }\r\n\r\n        // 2. Function to open Iview\r\n        function openIview(ivname) {\r\n            var url = "../../aspx/iview.aspx?ivname=" + encodeURIComponent(ivname) + "&hdnbElapsTime=0";\r\n            navigateToUrl(url);\r\n        }\r\n\r\n        // 3. Function to open ADS Smartview\r\n        function openAds(adsParam) {\r\n            var url = "/AxpertPlugins/Axi_Beta/HTMLPages/Smartview.html?ads=" + encodeURIComponent(adsParam) + "&load=1769601086182&filter=eyJmaWx0ZXJzIjpbXX0=&hdnbElapsTime=0";\r\n            navigateToUrl(url);\r\n        }\r\n\r\n        // Global uniform navigation execution function\r\n        function navigateToUrl(url) {\r\n            console.log("Navigating link to URL:", url);\r\n            // Check if Application Shell''s LoadUrl method is available inside the iframe framework\r\n            if (typeof LoadUrl === "function") {\r\n                LoadUrl(url);\r\n            } else if (window.parent && typeof window.parent.LoadUrl === "function") {\r\n                window.parent.LoadUrl(url);\r\n            } else {\r\n                window.location.href = url;\r\n            }\r\n        }\r\n\r\n\r\n\r\n        $(document).ready(function () {\r\n            loadInboxSummary();\r\n            loadUserAccess();\r\n\r\n\r\n\r\n            $(document).on(''click'', ''.Action-Btns button, .Action-Btns a, button.navigate, a[data-transid]'', function (e) {\r\n                e.preventDefault();\r\n\r\n                var $el = $(this);\r\n                var transid = $el.attr(''data-transid'') || '''';\r\n                var transtype = $el.attr(''data-transtype'') || '''';\r\n                var elementText = $el.text().trim().toLowerCase();\r\n\r\n                // FIX: Fallback sequence to discover transid from headers if not specified directly on the button/link\r\n                if (!transid) {\r\n                    // Look into the closest Child wrapper, Module Parent, or card container\r\n                    var $container = $el.closest(''.Module-Child-Wrapper, .Module-Parent, .card-ui'');\r\n                    var $titleEl = $container.find(''.module-header .title'');\r\n\r\n                    transid = $titleEl.attr(''data-transid'') || '''';\r\n                    transtype = transtype || $titleEl.attr(''data-transtype'') || '''';\r\n                }\r\n\r\n                // Automatically determine standard transactional type if not explicitly provided\r\n                if (!transtype) {\r\n                    if (elementText.indexOf(''create'') > -1) {\r\n                        transtype = ''tstruct-create'';\r\n                    } else if (elementText.indexOf(''view'') > -1) {\r\n                        transtype = ''tstruct-view'';\r\n                    }\r\n                }\r\n\r\n                // Safeguard check against unconfigured/empty dummy actions\r\n                if (!transid && transtype !== ''ads'') {\r\n                    console.warn("Navigation halted: ''data-transid'' attribute missing or empty.", $el);\r\n                    return;\r\n                }\r\n\r\n                // Core Router Routing Mechanism\r\n                switch (transtype.toLowerCase()) {\r\n                    case ''iview'':\r\n                        openIview(transid);\r\n                        break;\r\n                    case ''ads'':\r\n                        // For ADS, fallback to link/button text suffix if transid is explicitly blank\r\n                        var adsName = $el.text().trim();\r\n                        openAds(adsName);\r\n                        break;\r\n                    case ''tstruct-create'':\r\n                        open_tstruct(transid, ''create'');\r\n                        break;\r\n                    case ''tstruct-view'':\r\n                        open_tstruct(transid, ''view'');\r\n                        break;\r\n                    default:\r\n                        // Default fallback handler\r\n                        open_tstruct(transid, ''create'');\r\n                        break;\r\n                }\r\n                return false;\r\n            });\r\n\r\n        });\r\n    </script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\t\r\n\t\r\n\r\n\t\r\n\t\r\n\r\n\t\r\n\t\r\n\r\n\t\r\n\t\r\n\r\n\t<script type="text/javascript" src="Js/taskslst_inbox_1784802774665.js?v=1784896160089"></script>\r\n\t<script type="text/javascript" src="Js/AxProcessFlow_V3_1784802774665.js?v=1784896160090"></script>\r\n</body></html>\r\n');

