INSERT INTO {schema}.sect4 (sect4id, htmlsectionsid, sect4row, filename, filetype, css_js_src)
VALUES
(1012660000001, 1012660000000, 1, 'Package-Installed', 'Css', E':root {\r\n  --bg: #f5f6fb;\r\n  --card: #ffffff;\r\n  --border: #eef0f6;\r\n  --text: #111827;\r\n  --muted: #6b7280;\r\n  --primary: #4f46e5;\r\n}\r\n\r\nbody {\r\n\tbackground: var(--bg);\r\n\tfont-family: urbanist;\r\n\tcolor: var(--text);\r\n\tfont-weight: 600;\r\n/*\r\n\tdisplay: flex;\r\n\talign-items: center;\r\n\tjustify-content: center;\r\n*/\r\n}\r\n\r\n/* HEADER */\r\n.header {\r\n  padding: 20px 0;\r\n}\r\n\r\n.logo {\r\n  font-weight: 600;\r\n  font-size: 22px;\r\n}\r\n\r\n.nav-link {\r\n  color: var(--muted);\r\n  font-size: 14px;\r\n  padding-bottom: 6px;\r\n}\r\n\r\n.nav-link.active {\r\n  color: var(--primary);\r\n  border-bottom: 2px solid var(--primary);\r\n}\r\n\r\n/* SEARCH */\r\n.search {\r\n  width: 340px;\r\n  background: #eef1f6;\r\n  border-radius: 999px;\r\n  padding: 10px 18px;\r\n  border: none;\r\n  font-size: 14px;\r\n}\r\n\r\n/* CARD */\r\n.card-ui,.Module-Wrapper {\r\n\tbackground: var(--card);\r\n\tborder-radius: 16px;\r\n\tborder: 1px solid var(--border);\r\n\tbox-shadow: 0 6px 16px rgba(0,0,0,0.04);\r\n\tpadding: 25px !important;\r\n}\r\n\r\n/* HERO */\r\n.hero-img {\r\n  height: 200px;\r\n  background: radial-gradient(circle at 30% 30%, #a78bfa 0%, #6366f1 40%, #4338ca 100%);\r\n  border-top-left-radius: 16px;\r\n  border-top-right-radius: 16px;\r\n}\r\n\r\n/* TEXT */\r\n.title {\r\n  font-weight: bolder;\r\n  font-size: 15px;\r\n}\r\n\r\n.desc {\r\n  font-size: 14px;\r\n  color: var(--muted);\r\n  line-height: 1.5;\r\n    letter-spacing: 0.5px;\r\n    word-spacing: 2px;\r\n}\r\n\r\n/* BUTTONS */\r\n.btn-main {\r\n  background: var(--primary);\r\n  color: white;\r\n  border-radius: 999px;\r\n  padding: 10px 22px;\r\n  font-size: 14px;\r\n  border: none;\r\n}\r\n\r\n.btn-pill {\r\n\tbackground: #eef1f6;\r\n\tborder-radius: 50px;\r\n\tpadding: 5px 20px;\r\n\tfont-size: 12px;\r\n\tborder: none;\r\n\tmargin-top: 15px !important;\r\n\talign-self: flex-start !important;\r\n\tfont-weight: 600;\r\n\t/* box-shadow: 0 5px 5px 2px #dcdcdc85; */\r\n\tborder: 1px solid #cfcfcf4d;\r\n\ttransition: all ease 0.3s;\r\n}\r\n    .btn-pill:hover {\r\n\tbox-shadow: 0 5px 15px #ccc;\r\n\ttransition: all ease 0.3s;\r\n}\r\n\r\n/* ICON BOX */\r\n.icon {\r\n  width: 40px;\r\n  height: 40px;\r\n  border-radius: 10px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.purple { background: #eef2ff; color: #6366f1; }\r\n.blue   { background: #eff6ff; color: #3b82f6; }\r\n.green  { background: #ecfdf5; color: #22c55e; }\r\n.pink   { background: #f5f3ff; color: #a855f7; }\r\n.red    { background: #fef2f2; color: #ef4444; }\r\n\r\n/* GRID SPACING */\r\n.row-gap {\r\n  gap: 20px 0;\r\n}\r\n\r\n/* HOVER */\r\n.card-ui:hover {\r\n  transform: translateY(-3px);\r\n  transition: 0.2s ease;\r\n}\r\n    \r\n    .hero-img {\r\n  height: 200px;\r\n  border-top-left-radius: 16px;\r\n  border-top-right-radius: 16px;\r\n  background: radial-gradient(circle at 30% 30%, #1e1b4b, #0f172a);\r\n}\r\n\r\n/* SVG FULL FIT */\r\n.hero-svg {\r\n  width: 100%;\r\n  height: 100%;\r\n}\r\n\r\n/* GLASS EFFECT */\r\n.glass-overlay {\r\n  position: absolute;\r\n  inset: 0;\r\n  backdrop-filter: blur(20px);\r\n  background: linear-gradient(\r\n    120deg,\r\n    rgba(255,255,255,0.08),\r\n    rgba(255,255,255,0.02)\r\n  );\r\n  z-index: 2;\r\n}\r\n\r\n/* BLOBS ANIMATION */\r\n.blob {\r\n  transform-origin: center;\r\n  animation: float 8s ease-in-out infinite alternate;\r\n}\r\n\r\n.blob2 {\r\n  animation-duration: 10s;\r\n}\r\n\r\n.blob3 {\r\n  animation-duration: 12s;\r\n}\r\n\r\n/* ORB GLOW */\r\n.orb {\r\n  filter: blur(2px);\r\n  animation: pulse 3s infinite ease-in-out;\r\n}\r\n\r\n/* FLOAT ANIMATION */\r\n@keyframes float {\r\n  0% { transform: translateY(0px) scale(1); }\r\n  100% { transform: translateY(-15px) scale(1.05); }\r\n}\r\n\r\n/* GLOW PULSE */\r\n@keyframes pulse {\r\n  0%,100% { opacity: 0.7; }\r\n  50% { opacity: 1; }\r\n}\r\n\r\n/* HOVER PARALLAX (Premium Feel) */\r\n.hero-img:hover .blob1 {\r\n  transform: translateY(-10px) scale(1.08);\r\n}\r\n\r\n.hero-img:hover .blob2 {\r\n  transform: translateY(-5px) scale(1.05);\r\n}\r\n\r\n.hero-img:hover .blob3 {\r\n  transform: translateY(-8px) scale(1.06) rotate(-18deg);\r\n}\r\n    .blob {\r\n  transition: transform 0.3s ease-out;\r\n  will-change: transform;\r\n}\r\n    \r\n    \r\n    \r\n    .icon.orange {\r\n  background: #ffa50030;\r\n  color: orange;\r\n}\r\n.orange .material-icons.material-icons-style.material-icons-2 {\r\n  color: #e27514;\r\n}\r\n/*\r\n.blue  .material-icons.material-icons-style.material-icons-2 {\r\n  color: #0654b9;\r\n}\r\n*/\r\n.green .material-icons.material-icons-style.material-icons-2 {\r\n  color: green;\r\n}\r\n.pink .material-icons.material-icons-style.material-icons-2 {\r\n  color: purple;\r\n}\r\n.red .material-icons.material-icons-style.material-icons-2 {\r\n  color: red;\r\n}\r\n    .purple .material-icons.material-icons-style.material-icons-2 {\r\n\tcolor: #0c818c;\r\n}\r\n    \r\n.Hero-wrapper .title {\r\n  font-size: 19px !important;\r\n}\r\n.Hero-wrapper p.desc {\r\n  margin-top: 15px;\r\n}\r\n    \r\n    \r\n.dark-blue {\r\n  background: #024BCA;\r\n}\r\n.dark-blue .material-icons.material-icons-style.material-icons-2 {\r\n  color: white;\r\n}\r\n    \r\n/*    VJ modules*/\r\n    \r\n    .Axi_Installer_Wrapper {\r\n\tmargin: 0 auto;\r\n\twidth: 90%;\r\n}\r\n\r\n.Module-Child-Wrapper {\r\n  border: 1px solid #4387f6a1;\r\n  padding: 25px;\r\n  border-radius: 8px;\r\n  margin-bottom: 10px;\r\n  /*! display: flex; */\r\n}\r\n.Module-Parent {\r\n  margin-bottom: 10px;\r\n}\r\n.module-header {\r\n\tdisplay: flex;\r\n\talign-items: center;\r\n\tmargin-bottom: 10px;\r\n}\r\n.module-Content {\r\n  /*! display: flex; */\r\n}\r\n.Module-Img img {\r\n  max-width: 150px;\r\n  height: auto;\r\n}\r\n\r\n.Module-Child {\r\n\tdisplay: flex;\r\n\talign-items: stretch;\r\n    gap:25px;\r\n}\r\n.Module-Img img {\r\n  