enter;\r\n            gap: 10px;\r\n        }\r\n\r\n        .icon-filter {\r\n            display: flex;\r\n            align-items: center;\r\n            /* gap: 6px; */\r\n            padding: 6px 10px;\r\n            border-radius: 8px;\r\n            cursor: pointer;\r\n            background: #f3f6fb;\r\n            color: #444;\r\n            font-size: 12px;\r\n            transition: all .2s ease;\r\n            margin: 10px 0px;\r\n        }\r\n\r\n        .icon-filter .material-icons {\r\n            font-size: 18px;\r\n        }\r\n\r\n        .icon-filter:hover {\r\n            background: #e1e7f5;\r\n        }\r\n\r\n        .icon-filter.active {\r\n            background: #4e86c7;\r\n            color: white;\r\n        }\r\n\r\n        .icon-filter .count {\r\n            font-size: 11px;\r\n            opacity: 0.85;\r\n        }\r\n\r\n        .icon-all {\r\n            color: #3b82f6;\r\n        }\r\n\r\n        /* Blue */\r\n        .icon-active {\r\n            color: #f59e0b;\r\n        }\r\n\r\n        /* Amber */\r\n        .icon-completed {\r\n            color: #22c55e;\r\n        }\r\n\r\n        /* Green */\r\n        .icon-sent {\r\n            color: #6366f1;\r\n        }\r\n\r\n        /* Indigo */\r\n        .icon-pending {\r\n            color: #f97316;\r\n        }\r\n\r\n        /* Orange */\r\n        .icon-approved {\r\n            color: #10b981;\r\n        }\r\n\r\n        /* Teal */\r\n        .icon-rejected {\r\n            color: #ef4444;\r\n        }\r\n\r\n        /* Red */\r\n        .icon-returned {\r\n            color: #8b5cf6;\r\n        }\r\n\r\n        /* Violet */\r\n        .icon-filter.active .material-icons {\r\n            color: inherit;\r\n        }\r\n\r\n        .icon-message {\r\n            color: #0ea5e9;\r\n        }\r\n\r\n        /* Sky Blue */\r\n        .icon-notification {\r\n            color: #facc15;\r\n        }\r\n\r\n        /* Yellow */\r\n        .inbox-user-select {\r\n            padding: 6px 14px;\r\n            border-radius: 6px;\r\n            border: 1px solid #d0d5dd;\r\n            background: #2563eb;\r\n            color: #fff;\r\n            font-weight: 600;\r\n            cursor: pointer;\r\n        }\r\n\r\n        .inbox-user-select {\r\n            background: #4e86c7;\r\n            color: #fff;\r\n            padding: 6px 36px 6px 16px;\r\n            border-radius: 6px;\r\n            font-weight: 500;\r\n            cursor: pointer;\r\n            font-size: 15px;\r\n            border: none;\r\n            outline: none;\r\n            appearance: none;\r\n            min-width: 140px;\r\n            max-width: 200px;\r\n            background-image: url("data:image/svg+xml;utf8,<svg fill=''white'' height=''16'' viewBox=''0 0 24 24'' width=''16'' xmlns=''http://www.w3.org/2000/svg''><path d=''M7 10l5 5 5-5z''/></svg>");\r\n            background-repeat: no-repeat;\r\n            background-position: right 10px center;\r\n        }\r\n\r\n        .inbox-user-select option {\r\n            color: #000;\r\n        }\r\n\r\n        /* Make ONLY the dropdown options white */\r\n        .inbox-user-select option {\r\n            background: #ffffff !important;\r\n            color: #000000 !important;\r\n        }\r\n\r\n        /* Highlight on hover / selected option */\r\n        .inbox-user-select option:checked,\r\n        .inbox-user-select option:hover {\r\n            background: #f3f6fb !important;\r\n            color: #000000 !important;\r\n        }\r\n\r\n        .filter-group {\r\n            position: relative;\r\n        }\r\n\r\n        .group-btn {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 6px;\r\n            background: #f3f6fb;\r\n            border-radius: 8px;\r\n            padding: 6px 12px;\r\n            border: none;\r\n            cursor: pointer;\r\n            font-size: 13px;\r\n            width: 100px;\r\n        }\r\n\r\n        .group-btn:hover {\r\n        