eft: 6px;\r\n        }\r\n\r\n\r\n\r\n        .hidden {\r\n            display: none !important;\r\n        }\r\n\r\n        .inbox-sub-toolbar {\r\n            position: relative;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 12px;\r\n        }\r\n\r\n        .filter-wrapper {\r\n            position: relative;\r\n            /* 🔑 anchor for popup */\r\n        }\r\n\r\n        .filter-panel {\r\n            display: none;\r\n            position: absolute;\r\n            top: calc(100% - 12px);\r\n            left: 220px;\r\n            width: 330px;\r\n            background: #fff;\r\n            border: 1px solid #ddd;\r\n            border-radius: 6px;\r\n            padding: 10px 12px;\r\n            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);\r\n            z-index: 1000;\r\n        }\r\n\r\n\r\n\r\n\r\n        .filter-panel label {\r\n            display: inline-block;\r\n            width: 48%;\r\n            margin-bottom: 8px;\r\n            font-size: 14px;\r\n        }\r\n\r\n        .filter-panel.show {\r\n            display: block;\r\n            position: absolute;\r\n            z-index: 2000;\r\n        }\r\n\r\n\r\n        .filter-option {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            padding: 6px 0;\r\n            cursor: pointer;\r\n        }\r\n\r\n        .filter-btn {\r\n            background: none;\r\n            border: none;\r\n            cursor: pointer;\r\n        }\r\n\r\n\r\n\r\n        .filter-message-bar {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: space-between;\r\n            /* pushes X to last */\r\n            background: #eaeef2;\r\n            padding: 5px 16px;\r\n            border-radius: 4px;\r\n            margin: 0;\r\n            font-size: 14px;\r\n        }\r\n\r\n        #filterMessageText {\r\n            flex: 1;\r\n        }\r\n\r\n\r\n        .close-btn {\r\n