lay: flex;\r\n            justify-content: space-between;\r\n        }\r\n\r\n        .accordion-header {\r\n            padding: 8px 12px;\r\n            background: #f3f6fb;\r\n            cursor: pointer;\r\n            border-bottom: 1px solid #ddd;\r\n            font-weight: 500;\r\n            display: flex;\r\n            justify-content: space-between;\r\n        }\r\n\r\n        .accordion-body {\r\n            padding: 8px 12px;\r\n            background: #fff;\r\n        }\r\n\r\n        .task-item {\r\n            padding: 4px 0;\r\n            font-size: 13px;\r\n            border-bottom: 1px dashed #eee;\r\n        }\r\n\r\n        .search-highlight {\r\n            border: 2px solid #90ee90;\r\n            /* light green */\r\n            border-radius: 6px;\r\n            background: #f0fff0;\r\n        }\r\n\r\n        /* Target the actual header element */\r\n        .user-main {\r\n            position: sticky !important;\r\n            top: 0;\r\n            z-index: 1050;\r\n            /* Stays above task cards */\r\n            background: white;\r\n        }\r\n\r\n        .submenu-toggle {\r\n            pointer-events: none;\r\n            /* ❌ disable click */\r\n            cursor: default;\r\n            /* normal cursor */\r\n            font-weight: 600;\r\n            /* looks like header */\r\n        }\r\n\r\n        .stepper-horizontal li:not(:first-child)::before {\r\n            position: relative;\r\n            -webkit-box-flex: 1;\r\n            flex: 1 1 0%;\r\n            height: 1px;\r\n            margin: 0.5rem 0px 0px;\r\n            content: "";\r\n            background-color: rgba(0, 0, 0, 0.1);\r\n            min-width: 40px;\r\n        }\r\n\r\n\r\n        /* v2css */\r\n        .v2-accordion-item {\r\n            border-bottom: 0 !important;\r\n        }\r\n\r\n        .v2-accordion-header {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n       