      .chat-shell {\r\n            height: 100%;\r\n            min-height: 0;\r\n            display: flex;\r\n            flex-direction: column;\r\n            background: #fff;\r\n            box-shadow: 7px 7px 32px 5px #ccc !important;\r\n        }\r\n\r\n        .chat-shell-header {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: space-between;\r\n            gap: 16px;\r\n            padding: 5px 18px;\r\n            background: #fff;\r\n            border-bottom: 1px solid #dbe4f0;\r\n            background: ghostwhite;\r\n        }\r\n\r\n        .chat-profile {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 12px;\r\n            min-width: 0;\r\n        }\r\n\r\n        .chat-avatar {\r\n            width: 26px;\r\n            height: 26px;\r\n            border-radius: 50px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            color: #a00;\r\n            font-weight: 700;\r\n            font-size: 13px;\r\n            background: #fedddd;\r\n            flex: none;\r\n            /*! box-shadow: 0 10px 18px rgba(37, 99, 235, 0.14); */\r\n        }\r\n\r\n        .chat-avatar.chat-avatar-group {\r\n            background: #0f766e;\r\n            box-shadow: 0 10px 18px rgba(15, 118, 110, 0.12);\r\n        }\r\n\r\n        .chat-name {\r\n            font-size: 15px;\r\n            font-weight: 700;\r\n            line-height: 1.2;\r\n            color: #1f2937;\r\n            white-space: nowrap;\r\n            overflow: hidden;\r\n            text-overflow: ellipsis;\r\n            text-transform: capitalize;\r\n        }\r\n\r\n        .chat-subline {\r\n            margin-top: 4px;\r\n            display: flex;\r\n            gap: 8px;\r\n            flex-wrap: wrap;\r\n            font-size: 12px;\r\n            color: #64748b;\r\n        }\r\n\r\n        .chat-chip {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            padding: 4px 9px;\r\n            border-radius: 999px;\r\n            background: #eef4ff;\r\n            color: #2563eb;\r\n            font-size: 11px;\r\n            font-weight: 600;\r\n            white-space: nowrap;\r\n        }\r\n\r\n        .chat-actions {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            flex: none;\r\n        }\r\n\r\n        .chat-icon-btn {\r\n            width: 36px;\r\n            height: 36px;\r\n            border: none;\r\n            border-radius: 10px;\r\n            background: #f3f7fb;\r\n            color: #475569;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            cursor: default;\r\n        }\r\n\r\n        .chat-feed {\r\n            flex: 1;\r\n            min-height: 0;\r\n            overflow-y: auto;\r\n            padding: 18px;\r\n            display: flex;\r\n            flex-direction: column;\r\n            gap: 12px;\r\n        }\r\n\r\n        .chat-empty {\r\n            flex: 1;\r\n            min-height: 220px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            text-align: center;\r\n            color: #64748b;\r\n        }\r\n\r\n        .chat-empty-card {\r\n            background: #fff;\r\n            border: 1px solid #dbe4f0;\r\n            border-radius: 18px;\r\n            padding: 22px 24px;\r\n            box-shadow: 0 14px 30px rgba(15, 23, 42, 0.06);\r\n            max-width: 360px;\r\n        }\r\n\r\n        .chat-empty-title {\r\n            margin-top: 12px;\r\n            font-size: 16px;\r\n            font-weight: 700;\r\n            color: #1f2937;\r\n        }\r\n\r\n        .chat-empty-meta {\r\n            margin-top: 8px;\r\n            font-size: 13px;\r\n            line-height: 1.5;\r\n            color: #64748b;\r\n        }