eviewTypes.includes(ext)) {\r\n        window.open(url, "_blank", "noopener");\r\n        return;\r\n      }\r\n      const container = document.getElementById("PROFLOW_Right");\r\n      if (!container) {\r\n        console.error("PROFLOW_Right not found");\r\n        return;\r\n      }\r\n\r\n      const link = document.createElement("a");\r\n      link.href = url;\r\n      link.download = fileName;\r\n      link.rel = "noopener";\r\n      container.appendChild(link);\r\n      link.click();\r\n      container.removeChild(link);\r\n    },\r\n    error: function (xhr) {\r\n      console.error("API Error:", xhr.responseText);\r\n      alert("File download failed");\r\n    },\r\n  });\r\n}\r\n\r\n//         function downloadIviewFile(fileName, fullPath) {\r\n//             const baseUrl = window.location.origin;\r\n\r\n//             $.ajax({\r\n//                 url: `${baseUrl}/WebService.asmx/GetFilePathForIviewAttachment`,\r\n//                 type: "POST",\r\n//                 contentType: "application/json; charset=utf-8",\r\n//                 dataType: "json",\r\n//                 xhrFields: {\r\n//                     withCredentials: true\r\n//                 },\r\n//                 data: JSON.stringify({\r\n//                     proj: "agilespacedev",\r\n//                     tid: "-",\r\n//                     fldname: "-",\r\n//                     filename: fullPath,\r\n//                     attachtype: "fullpath",\r\n//                     onlyRecordId: "",\r\n//                     onlyFileName: fileName,\r\n//                     isDbAttachment: "false",\r\n//                     onlygetPath: true\r\n//                 }),\r\n\r\n//                 success: function (response) {\r\n\r\n//                     console.log("API Success:", response);\r\n\r\n//                     if (!response?.d) {\r\n//                         alert("Unable to download file");\r\n//                         return;\r\n//                     }\r\n\r\n//           